INSERT INTO news (category_id, title, slug, summary, content, author, image_url, source_url, published_at) VALUES
(1, 'জামায়াত আমিরের এক্স অ্যাকাউন্ট হ্যাকড: ডিবি চায় ডিভাইস, জামায়াতের উদ্বেগ নিরাপত্তায়', 'politics/2fmx28194f', 'জামায়াত আমিরের এক্স অ্যাকাউন্ট হ্যাকের তদন্তে সাত মাসেও সংশ্লিষ্ট ডিভাইস পায়নি ডিবি। আদালতের অনুমতি ও চিঠির পরও ডিভাইস দেওয়া হয়নি।', 'জামায়াতে ইসলামীর আমির শফিকুর রহমানের এক্স অ্যাকাউন্ট হ্যাকের অভিযোগ ওঠার পর আট মাসের বেশি পেরিয়েছে। এ ঘটনায় করা মামলার তদন্তে তাঁর ব্যবহৃত মুঠোফোনসহ সংশ্লিষ্ট ডিভাইস চেয়ে বাদীপক্ষকে অন্তত তিনবার চিঠি দিয়েছে গোয়েন্দা পুলিশ (ডিবি)। ডিভাইস জব্দ করে ফরেনসিক পরীক্ষার জন্য আদালতের অনুমতিও নেওয়া হয়েছে। তবে ডিভাইসগুলো এখনো তদন্ত সংস্থার হাতে দেওয়া হয়নি। তদন্তসংশ্লিষ্ট ব্যক্তিরা বলছেন, হ্যাকিংয়ের অভিযোগের তদন্তে সংশ্লিষ্ট ডিভাইসের ফরেনসিক পরীক্ষা গুরুত্বপূর্ণ। এতে কখন, কোথা থেকে ও কীভাবে অ্যাকাউন্টে প্রবেশ করা হয়েছে, সে বিষয়ে তথ্য পাওয়ার সুযোগ থাকে। লগইন বা সেশন-সংক্রান্ত তথ্য এবং ম্যালওয়্যার কিংবা ফিশিংয়ের আলামতও পাওয়া যেতে পারে। ডিভাইস না পাওয়ায় তদন্তের গুরুত্বপূর্ণ কয়েকটি প্রশ্নের উত্তর মিলছে না। তবে জামায়াত আমিরের পক্ষে মামলার বাদী মো. সিরাজুল ইসলাম প্রথম আলোকে বলেছেন, ডিভাইস দিতে তাঁরা অস্বীকৃতি জানাচ্ছেন না। ডিভাইসের নিরাপত্তা নিয়ে তাঁদের উদ্বেগ রয়েছে। এ নিয়ে ডিবির সঙ্গে দুবার আলোচনা হয়েছে। নিজেদের উপস্থিতিতে ডিভাইস পরীক্ষা করার বিষয়েও কথা হয়েছে বলে জানিয়েছেন তিনি।

আদালতের অনুমতি নিয়ে চিঠি মামলাটি তদন্ত করছে ঢাকা মহানগর ডিবির সাইবার অ্যান্ড স্পেশাল ক্রাইম-দক্ষিণ ইউনিট। তদন্ত কর্মকর্তা বাদী সিরাজুল ইসলামের কাছে ডিভাইস ও অন্যান্য আলামত চেয়ে চিঠি দিয়েছেন। তদন্তের স্বার্থে এসব জব্দ করে ফরেনসিক পরীক্ষার প্রয়োজনীয়তার কথাও চিঠিতে জানানো হয়েছে।

সাইবার অ্যান্ড স্পেশাল ক্রাইম বিভাগের অতিরিক্ত উপকমিশনার (এডিসি) হাফিজুল ইসলাম প্রথম আলোকে বলেন, আদালতের অনুমতি নিয়ে বাদীপক্ষের কাছে অন্তত তিনবার চিঠি দিয়ে ডিভাইস ও তথ্য চাওয়া হয়েছে। তবে বাদীপক্ষ এখনো ডিভাইস দেয়নি। তবে বাদীকে সর্বশেষ কবে চিঠি দেওয়া হয়েছে এবং আদালত কবে ফরেনসিক পরীক্ষার অনুমতি দিয়েছেন, তা হাফিজুল ইসলাম নির্দিষ্ট করে বলতে পারেননি। আদালতে খোঁজ নিয়ে জানা যায়, তদন্ত কর্মকর্তার আবেদনের পরিপ্রেক্ষিতে গত ৬ এপ্রিল আদালত ডিভাইস জব্দ করে ফরেনসিক পরীক্ষার আবেদন মঞ্জুর করেন। আদালত সূত্র জানায়, আগামী ৩ নভেম্বর মামলার তদন্ত প্রতিবেদন দাখিলের দিন ধার্য রয়েছে। ডিভাইসের নিরাপত্তা নিয়ে বাদীপক্ষের উদ্বেগের বিষয়ে তাঁদের কোনো আশ্বাস দেওয়া হয়েছিল কি না, জানতে চাইলে এডিসি হাফিজুল ইসলাম এ বিষয়ে বাদীপক্ষের সঙ্গে কথা বলতে বলেন।

নিজেদের উপস্থিতিতে পরীক্ষা চায় বাদীপক্ষ মামলার বাদী সিরাজুল ইসলাম প্রথম আলোকে বলেন, ‘ডিবির চিঠির পরিপ্রেক্ষিতে আমরা দুবার ডিবির সঙ্গে দেখা করেছি। আমরা ডিভাইস দিচ্ছি না, বিষয়টা এমন নয়। আমরা ডিভাইস ও নিরাপত্তা সুরক্ষা নিয়ে চিন্তিত। এটা নিয়ে আমরা আলাপ করেছি।’

ডিভাইস পরীক্ষার বিষয়ে সিরাজুল ইসলাম বলেন, ‘মনে করেন আমরা ডিভাইস দিলাম, সেটার নিরাপত্তা কী? আমরা বলেছি, আমাদের সামনেই চেক করতে হবে। এগুলো নিয়ে আলোচনা হয়েছে।’ মামলার বাদী আরও বলেন, মামলা করার সময় তাঁদের গবেষণায় পাওয়া কিছু কাগজপত্র দেওয়া হয়েছিল। সরকারের সার্ভার রক্ষণাবেক্ষণের সঙ্গে যুক্ত কোনো জায়গা থেকে হ্যাকিং হয়ে থাকতে পারে—এমন কিছু কাগজপত্রও তাঁরা দিয়েছেন।

আসামির ডিভাইস ফেরত, ফরেনসিক প্রতিবেদন আসেনি বাদীপক্ষের ডিভাইস এখনো না পেলেও মামলার অন্যতম আসামি বঙ্গভবনের সহকারী প্রোগ্রামার মোহাম্মদ ছরওয়ারে আলমের ব্যবহৃত মুঠোফোন, ল্যাপটপ ও ডেস্কটপ জব্দ করে তল্লাশি চালিয়েছে ডিবি। ছরওয়ারে আলমের দাবি, তাঁর পরিবারের সদস্যদের ব্যবহৃত কিছু ডিভাইসও জব্দ করা হয়েছিল। তল্লাশি চালিয়ে প্রায় এক মাস পর সেগুলো ফেরত দেওয়া হয়।

জব্দ করা ডিভাইস থেকে কোনো আলামত পাওয়া গেছে কি না, জানতে চাইলে তদন্ত কর্মকর্তা প্রথম আলোকে বলেন, ফরেনসিক প্রতিবেদন এখনো পাওয়া যায়নি। মামলার শুরুর দিকে এক্স কর্তৃপক্ষের কাছেও বিস্তারিত তথ্য চেয়ে চিঠি দেওয়া হয়েছিল। সেখান থেকেও এখনো কোনো আপডেট আসেনি। এসব প্রতিবেদন আসার পরই এ বিষয়ে বলা সম্ভব হবে।

তদন্ত শেষ হওয়ার অপেক্ষায় ছরওয়ার এই মামলায় গ্রেপ্তার হয়ে পরে জামিন পাওয়া ছরওয়ারে আলম শুরু থেকেই নিজেকে নির্দোষ দাবি করে আসছেন। তাঁর বক্তব্য, তিনি শফিকুর রহমানের এক্স অ্যাকাউন্ট হ্যাকের সঙ্গে জড়িত নন। তাঁর দাবি, পুলিশ তাঁর ব্যবহৃত ডিভাইস পরীক্ষা করলেও এখন পর্যন্ত এই ঘটনার সঙ্গে তাঁর সংশ্লিষ্টতার কোনো তথ্যপ্রমাণ পাওয়া যায়নি। তবে তদন্ত কর্মকর্তা বলেছেন, ফরেনসিক প্রতিবেদন এখনো হাতে আসেনি। ছরওয়ারে আলম প্রথম আলোকে বলেন, ‘ওদের (জামায়াত) কাছে বারবার পাঠাইছে, মোবাইল চাইছে, চেক করার জন্য চাইছে। ওরা দিচ্ছে না। ওরা যদি ওদের ডিভাইস দিত, তাহলে এত দিনে এটার সমাধান হয়ে যেত।’ ছরওয়ারে আলম আরও বলেন, ‘তাঁরা তো বিরোধীদলীয় নেতা। তাঁরা তদন্তে সহযোগিতা না করলে আমার তো এভাবেই ঝুলে থাকতে হবে। আমি সুবিচার চাই। সঠিক তদন্ত হলে আমি সুবিচার পাব।’ মামলায় জড়িয়ে সাময়িক বরখাস্ত হওয়ার পর চাকরিতে ফিরতে না পারায় নিজের চাকরিজীবন নিয়েও উদ্বেগ জানিয়েছেন ছরওয়ারে আলম। তিনি বলেন, তাঁর চাকরির মেয়াদ শেষ হতে আর কয়েক মাস বাকি। মামলার তদন্ত দীর্ঘায়িত হলে পেনশনসহ চাকরিজীবনের আর্থিক সুবিধা থেকে বঞ্চিত হওয়ার আশঙ্কা করছেন তিনি। ছরওয়ারে আলমের ভাষ্য, ‘সাময়িকভাবে বরখাস্ত হয়ে আমি চাকরিতে ফিরতে পারিনি। আমাকে বলির পাঁঠা বানানো হচ্ছে।’

যে পোস্ট ঘিরে মামলা গত ৩১ জানুয়ারি বিকেলে জামায়াতের আমিরের এক্স হ্যান্ডল থেকে ইংরেজিতে একটি পোস্ট দেওয়া হয়। পোস্টের একটি অংশে লেখা হয়, ‘আমরা বিশ্বাস করি, যখন নারীদের আধুনিকতার নামে ঘর থেকে বের করা হয়, তখন তাঁরা শোষণ, নৈতিক অবক্ষয় এবং নিরাপত্তাহীনতার মুখোমুখি হন। এটি অন্য কিছু নয়; বরং পতিতাবৃত্তির অন্য একটি রূপ।’ এ নিয়ে সামাজিক যোগাযোগমাধ্যমে ব্যাপক আলোচনা-সমালোচনা শুরু হয়, যা পরে রাজপথে বিক্ষোভেও গড়ায়। বিএনপিসহ বিভিন্ন দল ও সংগঠন থেকে বলা হয়, জামায়াতের আমির কর্মজীবী নারীদের চরম অবমাননা করেছেন। পরে জামায়াতের পক্ষ থেকে দাবি করা হয়, সরকারি মেইল ব্যবহার করে আমিরের এক্স অ্যাকাউন্ট হ্যাক করে ওই পোস্ট দেওয়া হয়েছে। এ ঘটনায় প্রথমে সাধারণ ডায়েরি এবং পরে মামলা করা হয়। মামলায় রাষ্ট্রপতির কার্যালয়ের সহকারী প্রোগ্রামার মোহাম্মদ ছরওয়ারে আলমসহ অজ্ঞাতনামা ১৫ থেকে ২০ জনকে আসামি করা হয়। ৩ ফেব্রুয়ারি রাতে ছরওয়ারকে আটক করে ডিবি। তাঁর মুঠোফোন ও ল্যাপটপ জব্দ করা হয়। পরদিন তাঁকে মামলায় গ্রেপ্তার দেখানোর কথা জানায় ডিবি। তবে সেদিনই আদালত থেকে জামিন পান ছরওয়ার।

তদন্তে সহযোগিতার তাগিদ তদন্তে বাদীপক্ষের কাছ থেকে প্রয়োজনীয় আলামত না পাওয়ার বিষয়ে ঢাকা মহানগর দায়রা জজ আদালতের সরকারি কৌঁসুলি ওমর ফারুক ফারুকী প্রথম আলোকে বলেন, তদন্তের স্বার্থে তদন্ত কর্মকর্তাকে অবশ্যই সহযোগিতা করা উচিত। এটা বাদী-বিবাদী সবারই দায়িত্ব। তিনি বলেন, ‘খেয়াল রাখা উচিত, নিরপরাধ কেউ যেন হয়রানির শিকার না হয়।’ হ্যাকিংয়ের অভিযোগ ওঠার আট মাসের বেশি সময় পরও বাদীপক্ষের সংশ্লিষ্ট ডিভাইসের ফরেনসিক পরীক্ষা হয়নি। এক্স কর্তৃপক্ষের কাছ থেকেও প্রয়োজনীয় তথ্য আসেনি। ফলে অ্যাকাউন্টে অননুমোদিত প্রবেশ ঘটেছিল কি না, ঘটে থাকলে কীভাবে এবং এই ঘটনার সঙ্গে ছরওয়ারে আলমের কোনো সংশ্লিষ্টতা ছিল কি না—এসব গুরুত্বপূর্ণ প্রশ্নের উত্তর এখনো মেলেনি।', 'ইমরান হোসেন', 'https://media.prothomalo.com/prothomalo-bangla/2026-10-23/9523gdfu/Jamat-Amir.png', 'https://www.prothomalo.com/politics/2fmx28194f', '2026-10-23 17:56:28'),
(1, 'বাংলাদেশ ব্যাংকের পর এবার ৩৬ ঘণ্টা বন্ধ ডিজিটাল ভূমিসেবার সার্ভার', 'bangladesh/mwzql7dtpx', 'পিএইচপি ত্রুটি', 'পিএইচপিতে শনাক্ত নিরাপত্তা ত্রুটির পরিপ্রেক্ষিতে সিস্টেমের নিরাপত্তা উন্নয়নে রক্ষণাবেক্ষণ কার্যক্রম চালানোর ঘোষণা দিয়েছে ভূমি মন্ত্রণালয়। এ জন্য গতকাল বৃহস্পতিবার দিবাগত রাত ১২টা থেকে আগামীকাল শনিবার দুপুর ১২টা পর্যন্ত টানা ৩৬ ঘণ্টা ডিজিটাল ভূমিসেবার (land.gov.bd) সার্ভার বন্ধ রেখেছে তারা। এ সময় ভূমিসেবার কোনো কার্যক্রম ব্যবহার করা যাবে না বলে বিজ্ঞপ্তিতে জানানো হয়েছে। ভূমি মন্ত্রণালয়ের বিজ্ঞপ্তিতে বলা হয়েছে, সরকারের সাইবার নিরাপত্তাসংশ্লিষ্ট সংস্থা বিজিডি ই-গভ সার্টের ২২ অক্টোবরের জরুরি সাইবার সতর্কবার্তার পরিপ্রেক্ষিতে সিস্টেমের নিরাপত্তা উন্নয়নের কাজ করা হবে।

ডিজিটাল ভূমিসেবার মধ্যে আছে নামজারি বা মিউটেশন, ভূমি উন্নয়ন কর পরিশোধ, ভূমি রেকর্ড ও মৌজা ম্যাপ সংগ্রহ, ভূমি অধিগ্রহণ ও হুকুমদখল, ইজারা ও বন্দোবস্ত, ভূমি রাজস্ব মামলা এবং ভূমি তথ্য ব্যাংক। এ ছাড়া জমির উত্তরাধিকার নির্ধারণের ক্যালকুলেটর, ভূমি-সংক্রান্ত আইন ও বিধি, বিভিন্ন ফরম এবং সেবা নেওয়ার নির্দেশিকাও রয়েছে। বিজ্ঞপ্তিতে বৃহস্পতিবার রাত ১১টা ৪৫ মিনিটের পর ভূমিসেবার জন্য কোনো ধরনের পেমেন্ট না করতে সবাইকে অনুরোধ করা হয়েছে। সাময়িক অসুবিধার জন্য দুঃখপ্রকাশ করে রক্ষণাবেক্ষণের কাজ সফলভাবে সম্পন্ন করতে সংশ্লিষ্ট সবার সহযোগিতা চেয়েছে মন্ত্রণালয়।

সম্প্রতি ওয়েবসাইট তৈরি ও পরিচালনায় বহুল ব্যবহৃত প্রোগ্রামিং ভাষা পিএইচপিতে দুটি গুরুতর নিরাপত্তা ত্রুটি শনাক্ত হয়েছে। এসব ত্রুটির কারণে বিশ্বজুড়ে বিভিন্ন সরকারি ও বাণিজ্যিক প্রতিষ্ঠানের ওয়েবসাইটের নিরাপত্তা নিয়ে উদ্বেগ তৈরি হয়েছে। এর পরিপ্রেক্ষিতে বিভিন্ন প্রতিষ্ঠান তাদের সিস্টেমের নিরাপত্তা যাচাই ও হালনাগাদ করার উদ্যোগ নিয়েছে। সরকারের সাইবার নিরাপত্তাসংশ্লিষ্ট বিষয় দেখভালের দায়িত্বপ্রাপ্ত বিজিডি ই-গভ সার্টও পিএইচপির নিরাপত্তা ত্রুটি নিয়ে সতর্কবার্তা জারি করেছে। সংস্থাটির পরামর্শ অনুযায়ী, সংশ্লিষ্ট প্রতিষ্ঠানগুলোকে তাদের সার্ভারে কোথায় কোথায় পিএইচপি ব্যবহার করা হচ্ছে, তা শনাক্ত করতে হবে। পাশাপাশি ব্যবহৃত সংস্করণগুলো ঝুঁকিপূর্ণ কি না, তা যাচাই করে প্রয়োজনীয় নিরাপত্তার ব্যবস্থা নিতে হবে। এর আগে একই নিরাপত্তা ত্রুটির পরিপ্রেক্ষিতে বাংলাদেশ ব্যাংকের সার্ভার বন্ধ রাখার বিষয়টিও সামনে আসে। এবার ভূমিসেবার সার্ভার বন্ধ রেখে নিরাপত্তা হালনাগাদের উদ্যোগ নেওয়া হলো।', 'নিজস্ব প্রতিবেদক', 'https://media.prothomalo.com/prothomalo-bangla/2026-10-23/ofdhj7bh/Untitled-6.jpg', 'https://www.prothomalo.com/bangladesh/mwzql7dtpx', '2026-10-23 15:41:24'),
(1, 'ষষ্ঠ শ্রেণির আইসিটি বইয়ে মস্তিষ্কের বদলে ‘দাঁড়িপাল্লা’, পরিবর্তনের কথা বলছে এনসিটিবি', 'bangladesh/rxez7n73fd', '২০২৭ শিক্ষাবর্ষের ষষ্ঠ শ্রেণির তথ্য ও যোগাযোগ প্রযুক্তি বইয়ে প্রজ্ঞার প্রতীক হিসেবে থাকা দাঁড়িপাল্লার ছবি নিয়ে বিতর্কের পর তা পরিবর্তনের উদ্যোগ নিয়েছে এনসিটিবি।', '২০২৭ শিক্ষাবর্ষের ষষ্ঠ শ্রেণির তথ্য ও যোগাযোগ প্রযুক্তি বইয়ে প্রজ্ঞার প্রতীক হিসেবে রাখা হয়েছে দাঁড়িপাল্লার ছবি। এ নিয়ে বিতর্ক শুরু হওয়ায় প্রতীকটি পরিবর্তনের উদ্যোগ নিয়েছে জাতীয় শিক্ষাক্রম ও পাঠ্যপুস্তক বোর্ড (এনসিটিবি)। গতকাল বৃহস্পতিবার রাতে বইটির ছাপার কাজ বন্ধ রাখার নির্দেশ দেওয়া হয়েছে। একই সঙ্গে মাঠপর্যায়ে চলে যাওয়া বইগুলো সংগ্রহ করে প্রতীক পরিবর্তনের পর আবার শিক্ষার্থীদের কাছে সরবরাহ করার কথা জানিয়েছে সংস্থাটি। তবে বইটির ছাপা, বাঁধাই ও সরবরাহের কাজ অনেক আগেই শেষ হয়েছে বলে জানিয়েছেন মুদ্রণমালিকেরা। ফলে মাঠপর্যায়ে চলে যাওয়া বই সংগ্রহ করে সংশোধন করা হলে বাড়তি খরচ ও সময় লাগবে বলে তাঁদের বক্তব্য।

এনসিটিবির বই ছাপানোর হিসাব বিশ্লেষণ করে দেখা গেছে, মাধ্যমিকের বিভিন্ন শ্রেণির বই ছাপানোয় ধীরগতি রয়েছে। এর মধ্যে মাঠ থেকে বই তুলে এনে পরিমার্জন করে পুনরায় সেটা শিক্ষার্থীদের হাতে পৌঁছাতে সময় বেশি লাগতে পারে। এতে নির্দিষ্ট সময়ে বই পৌঁছানো বিঘ্ন ঘটতে পারে বলেও আশঙ্কা করছেন অনেকে।

এনসিটিবির প্রধান সম্পাদক অধ্যাপক মো. রিয়াজুল ইসলাম প্রথম আলোকে বলেন, যেসব বই মাঠে চলে গেছে, সেগুলো সংগ্রহ করে প্রতীকটি পরিমার্জন করে আবার শিক্ষার্থীদের কাছে সরবরাহ করা হবে। আপাতত ছাপার কাজ বন্ধ রাখা এবং মাঠে যাওয়া বই সংগ্রহের উদ্যোগ নেওয়া হয়েছে। তিনি বলেন, ‘বইয়ের মাধ্যমে শিক্ষার্থীরা যাতে কোনো ভুল তথ্য না পায়, সেটা আমরা নিশ্চিত করতে চাই।’ নাম প্রকাশ না করার শর্তে এনসিটিবির এক কর্মকর্তা বলেন, দাঁড়িপাল্লা মূলত একটি দলের নির্বাচনী প্রতীক। এ কারণে প্রতীকটি নিয়ে সমালোচনা হচ্ছে।

বইয়ে যেভাবে এসেছে দাঁড়িপাল্লা ২০২৭ শিক্ষাবর্ষের ষষ্ঠ শ্রেণির তথ্য ও যোগাযোগ প্রযুক্তি বইয়ের ‘উপাত্ত ও তথ্য’ পাঠে জ্ঞানের পিরামিডের ধারণা তুলে ধরা হয়েছে। এতে চারটি স্তর রয়েছে। নিচ থেকে সেগুলো হলো উপাত্ত, তথ্য, জ্ঞান ও প্রজ্ঞা। প্রতিটি স্তর বোঝাতে ব্যবহার করা হয়েছে আলাদা প্রতীক।

উপাত্তের স্তরে রয়েছে পাই চার্ট বা ঘড়ির মতো বৃত্তাকার প্রতীক। তথ্যের স্তরে রয়েছে পরমাণু বা নেটওয়ার্কের মতো দেখতে একটি প্রতীক। জ্ঞানের স্তর বোঝাতে ব্যবহার করা হয়েছে মানুষের মস্তিষ্কের ছবি। আর পিরামিডের সর্বোচ্চ স্তর প্রজ্ঞার প্রতীক হিসেবে রাখা হয়েছে দাঁড়িপাল্লা। এনসিটিবি সূত্রে জানা গেছে, ২০২৭ শিক্ষাবর্ষের জন্য ষষ্ঠ শ্রেণির তথ্য ও যোগাযোগ প্রযুক্তি বইয়ের প্রায় ৩৮ লাখ কপি ছাপানো হচ্ছে। এর বেশির ভাগই ইতিমধ্যে ছাপা হয়ে গেছে। এ ছাড়া ২০২৭ শিক্ষাবর্ষের জন্য সব মিলিয়ে প্রায় ৩১ কোটি বই ছাপানোর কাজ চলছে।

আগের শিক্ষাবর্ষের বইয়ের সঙ্গে তুলনা করলে প্রজ্ঞার প্রতীক নিয়ে পরিবর্তনের ধারাটি আরও স্পষ্ট হয়। আওয়ামী লীগ সরকারের পতনের পর পাঠ্যক্রমে পরিবর্তন এনে অন্তর্বর্তী সরকার ২০১২ সালের শিক্ষাক্রমে ফিরে যায়। সেই অনুযায়ী, ২০২৫ শিক্ষাবর্ষের জন্য পরিমার্জিত ষষ্ঠ শ্রেণির তথ্য ও যোগাযোগ প্রযুক্তি বইয়েও প্রজ্ঞার স্তরে দাঁড়িপাল্লার ছবি ছিল। তবে চলতি শিক্ষাবর্ষে শিক্ষার্থীদের হাতে থাকা বইয়ে প্রজ্ঞার প্রতীক হিসেবে ব্যবহার করা হয়েছে মানুষের মস্তিষ্কের ছবি। ২০২৭ শিক্ষাবর্ষের বইয়ে আবার দাঁড়িপাল্লার ছবি ফিরে আসে। এ নিয়ে বিতর্কের পর এবার প্রতীকটি পরিবর্তনের উদ্যোগ নেওয়া হয়েছে। প্রজ্ঞার প্রতীক হিসেবে কোন ছবি ব্যবহার করা হবে, সে বিষয়ে সর্বজনস্বীকৃত কোনো নির্দিষ্ট উত্তর নেই। ইতিহাস, দর্শন ও সংস্কৃতিতে প্যাঁচা ও বইয়ের মতো প্রতীকও প্রজ্ঞার প্রতিনিধিত্ব করে। তবে সংশোধনের পর ষষ্ঠ শ্রেণির বইয়ে কোন প্রতীক থাকবে, তা এখনো জানায়নি এনসিটিবি।', 'আহমেদ উল্যা ইউসুফ', 'https://media.prothomalo.com/prothomalo-bangla/2025-07-24/fn18uxro/aec625d4-1485-409f-9dc5-2bd8e1d6f011.jfif', 'https://www.prothomalo.com/bangladesh/rxez7n73fd', '2026-10-23 15:33:13'),
(1, '‘কেঁদো না, বাসায় গিয়ে ফোন দেব’—স্ত্রীর সঙ্গে শেষ কথা ছিল শাহেদের', 'bangladesh/jfnjva46i6', 'সৌদিতে হামলায় নিহত', '‘আমি কাঁদছিলাম। সে আমাকে বলেছিল, “কেঁদো না। এক-দেড় ঘণ্টা পর বাসায় গিয়ে তোমাকে ফোন দেব।” কিন্তু আমার খুব ভয় লাগছিল। সে যাওয়ার আগে থেকেই কেমন যেন লাগছিল, আগে কখনো এমন ভয় লাগেনি। সৌদি আরবে যুদ্ধ হচ্ছে, এই ভেবেই আমি তাঁকে যেতে দিতে চাইনি। কিন্তু ও জোর করেই চলে গেল।’ কথাগুলো বলতে গিয়ে কান্না আটকাতে পারছিলেন না কহিনুর আক্তার কাকলী। সৌদি আরবে যাওয়ার আগে স্বামী মো. শাহেদ আহম্মেদকে নিয়ে যে অজানা ভয় তাঁর মনে জেগেছিল, তা-ই এখন বারবার মনে পড়ছে।

১০ অক্টোবর রিয়াদের কিং খালেদ আন্তর্জাতিক বিমানবন্দরে হামলায় নিহত শাহেদের মরদেহ আজ শুক্রবার সকালে ঢাকার হজরত শাহজালাল আন্তর্জাতিক বিমানবন্দরে পৌঁছেছে। বিমানবন্দরে স্বামীর মরদেহ নিতে এসে শেষ কথাগুলো সাংবাদিকদের বলছিলেন কহিনুর। স্বামীর সঙ্গে কাটানো শেষ দিনগুলোর কথা মনে করে কহিনুর বলেন, এবার প্রায় এক মাসের ছুটিতে দেশে এসেছিলেন শাহেদ। এই সময়ে বন্ধুদের সঙ্গে আড্ডা দিতে কিংবা বাইরে ঘুরতে যেতেন না। স্ত্রী ও দুই সন্তানকে নিয়ে সময় কাটাতেন, তাঁদের নিয়ে বাইরে বের হতেন। পরিবারের সঙ্গে কাটানো সেই দিনগুলোই এখন কহিনুরের স্মৃতিতে বারবার ফিরে আসছে।

‘যেতে দিতে চাইনি, কিন্তু চলে গেল’ সৌদি আরবে ফেরার আগে থেকেই স্বামীকে নিয়ে অজানা এক ভয় কাজ করছিল কহিনুরের মনে। মধ্যপ্রাচ্যে যুদ্ধের পরিস্থিতির কথা ভেবে শাহেদকে যেতে দিতে চাননি তিনি। কিন্তু কাজের টানে ফিরতেই হয়েছিল শাহেদকে। যাওয়ার সময় স্ত্রীকে সান্ত্বনা দিয়ে বলেছিলেন, কান্না না করতে। বাসায় পৌঁছে ফোন দেবেন। সেই ফোনের অপেক্ষা আর শেষ হয়নি। শাহেদ সৌদি আরবের একটি ঠিকাদারি প্রতিষ্ঠানের জেদ্দা প্রকল্পে প্লাম্বার হিসেবে কাজ করতেন। দেশটিতে তাঁর কাজের অনুমতিপত্র (ইকামা) ছিল। ভাইয়ের মৃত্যুর পর ছুটি কাটিয়ে দেশে থেকে রিয়াদ হয়ে জেদ্দায় কর্মস্থলে ফিরছিলেন তিনি। পথে রিয়াদ বিমানবন্দরে হামলার সময় সেখানে অবস্থান করছিলেন শাহেদ।

এর আগে আরও দুবার সৌদি আরবে গিয়েছিলেন শাহেদ। তবে কাজের ব্যবস্থা করতে না পারায় দেশে ফিরে আসতে হয়েছিল। এবার প্রায় দুই বছর আগে সৌদি আরবে গিয়ে প্রথমে শ্বশুরের কাছে থাকেন। পরে শ্বশুরের মাধ্যমে একটি কোম্পানিতে চালকের চাকরি পান। গাড়ি চালানোর লাইসেন্স জমা দিয়ে সেই চাকরিতে যোগ দেন। পরে কর্মস্থল বদল হওয়ায় জেদ্দায় চলে যান শাহেদ। তাঁর শ্বশুর থেকে যান দাম্মামে। গত ৭ সেপ্টেম্বর ছুটিতে দেশে এসেছিলেন শাহেদ। এক মাস তিন দিন পরিবারের সঙ্গে কাটিয়ে আবার সৌদি আরবে ফিরে যান। এরপর ১০ অক্টোবর হুতিদের হামলায় প্রাণ হারান বগুড়ার শাহজাহানপুর উপজেলার মাদলা গ্রামের এই বাসিন্দা।

পরিবারের জন্য গড়া স্বপ্ন ভেঙে গেল এবার সৌদি আরবে ফেরার সময় অনেক আশা ছিল শাহেদের। কহিনুরের ভাষ্য, এক বছর ধরে কাজের সঙ্গে যুক্ত থাকার পর স্বামীর মনে নতুন করে স্বপ্ন তৈরি হয়েছিল। এবার ভালোভাবে কাজ করবেন, পরিবারের জন্য কিছু করবেন, সংসারের হাল ধরবেন—এমন প্রত্যাশা ছিল সবার। কিন্তু সেই স্বপ্ন এখন ভেঙে গেছে। শাহেদের মরদেহ দেশে পৌঁছালে তা গ্রহণ করেন পররাষ্ট্র প্রতিমন্ত্রী শামা ওবায়েদ ইসলাম। পরে তিনি মরদেহ পরিবারের কাছে হস্তান্তর করেন। এ সময় সরকারের পক্ষ থেকে পরিবারকে আর্থিক সহায়তার চেক দেওয়া হয়। ভবিষ্যতেও সহযোগিতা অব্যাহত রাখার আশ্বাস দেন প্রতিমন্ত্রী।

দুই সন্তানকে নিয়ে অনিশ্চিত ভবিষ্যৎ শাহেদ ও কহিনুরের সংসারে দুই ছেলে—জিহাদ ও কাউসার। জিহাদের বয়স মাত্র পাঁচ বছর, আর কাউসারের বয়স ১০ বছর। বাবার মরদেহ নিতে স্বজনদের সঙ্গে বিমানবন্দরে এসেছিল তারাও। কহিনুরের বয়স এখন ২৬ বছর। তাঁর ভাষ্য, ১৩ বছর বয়সে শাহেদের সঙ্গে তাঁর বিয়ে হয়। দুজনের পছন্দের সম্পর্ক থেকেই তাঁদের সংসার জীবনের শুরু। এত অল্প বয়সে স্বামীকে হারিয়ে এখন দুই সন্তানকে নিয়ে কীভাবে সামনে এগোবেন, সেই চিন্তাই ঘুরপাক খাচ্ছে তাঁর মনে। কহিনুর বলেন, ‘আমার দুটি সন্তান। ওদের দায়িত্ব নেওয়ার মতো আর কেউ নেই। আমি চাই, আমার সন্তানদের নিয়ে যেন সারাটা জীবন বেঁচে থাকতে পারি। আমার সন্তানদের ভবিষ্যতের কথা বিবেচনা করে প্রধানমন্ত্রী যেন আমার পাশে দাঁড়ান।’

মধ্যপ্রাচ্যের সংঘাতে প্রাণ গেছে ১১ বাংলাদেশির কর্মসূত্রে বাংলাদেশের বিপুলসংখ্যক মানুষ মধ্যপ্রাচ্যের বিভিন্ন দেশে থাকেন। তাঁদের বড় একটি অংশের কর্মস্থল সৌদি আরব। সম্প্রতি দেশটিতে ইরান-সমর্থিত সশস্ত্র গোষ্ঠী হুতিরা কয়েক দফা হামলা চালিয়েছে। এসব হামলায় হতাহতের ঘটনাও ঘটেছে।

বাংলাদেশের পররাষ্ট্র মন্ত্রণালয় জানিয়েছে, গত ছয় মাসে মধ্যপ্রাচ্যের সংঘাতের কারণে নিহত ১১ বাংলাদেশির মরদেহ দেশে ফিরিয়ে আনা হয়েছে। শাহেদ তাঁদের মধ্যে ১১তম। গত এক মাসে সৌদি আরবে ক্ষেপণাস্ত্র হামলায় তিন বাংলাদেশি নিহত হয়েছেন। তাঁদের একজন শাহেদ, যাঁর মরদেহ আজ দেশে এসেছে। অন্যদের মরদেহও দ্রুত দেশে ফিরিয়ে আনার প্রক্রিয়া চলছে বলে জানিয়েছে পররাষ্ট্র মন্ত্রণালয়।', 'মো. মামুন', 'https://media.prothomalo.com/prothomalo-bangla/2026-10-23/397zpfsk/Shahed-1.jpeg', 'https://www.prothomalo.com/bangladesh/jfnjva46i6', '2026-10-23 14:04:15'),
(1, 'এনসিপিতে পাটওয়ারী-হাসনাত-সারজিস-আসিফের পদোন্নতি, বিলুপ্ত ৭ পদ', 'politics/669vboj19s', 'এনসিপির পক্ষ থেকে দলটির রাজনৈতিক পর্ষদের ১৬ জন সদস্যকে দলটির নেতৃত্বের ‘সুপার সিক্সটিন’ বলা হচ্ছে৷', 'জাতীয় নাগরিক পার্টির (এনসিপি) ১৯৫ সদস্যের পুনর্গঠিত কমিটি প্রকাশ করা হয়েছে৷ কমিটিতে নাসীরুদ্দীন পাটওয়ারী ও হাসনাত আবদুল্লাহকে পদোন্নতি দিয়ে জ্যেষ্ঠ যুগ্ম আহ্বায়ক করা হয়েছে। আর সারজিস আলম ও আসিফ মাহমুদ সজীব ভুঁইয়াকে পদোন্নতি দিয়ে জ্যেষ্ঠ যুগ্ম সদস্যসচিব করা হয়েছে৷ অন্যদিকে আগের কমিটির জ্যেষ্ঠ যুগ্ম আহ্বায়ক সামান্তা শারমিন, আরিফুল ইসলাম আদীব ও জ্যেষ্ঠ যুগ্ম মুখ্য সমন্বয়ক আবদুল হান্নান মাসউদ নতুন কমিটিতে যুগ্ম আহ্বায়ক এবং জ্যেষ্ঠ যুগ্ম সদস্যসচিব নাহিদা সারোয়ার নিভা হয়েছেন যুগ্ম সদস্যসচিব৷ আজ শুক্রবার দুপুর সোয়া ১২টার দিকে এনসিপির ভেরিফায়েড ফেসবুক পেজে পুনর্গঠিত কমিটি প্রকাশ করা হয়৷

এই পুনর্গঠনের মধ্য দিয়ে এনসিপির সাংগঠনিক কাঠামো থেকে সাতটি পদ কার্যত বিলুপ্ত হলো। এগুলো হলো: মুখ্য সমন্বয়ক, উত্তরাঞ্চলের মুখ্য সংগঠক, দক্ষিণাঞ্চলের মুখ্য সংগঠক, মুখপাত্র, জ্যেষ্ঠ যুগ্ম মুখ্য সমন্বয়ক, সংগঠক ও যুগ্ম মুখ্য সমন্বয়ক৷ তবে পুনর্গঠিত কমিটিতেও আগের মতো দুজন করে জ্যেষ্ঠ যুগ্ম আহ্বায়ক ও জ্যেষ্ঠ যুগ্ম সদস্যসচিব থাকছেন। আগের কমিটিতে মুখ্য সমন্বয়ক পদে নাসীরুদ্দীন, উত্তরাঞ্চলের মুখ্য সংগঠক পদে সারজিস, দক্ষিণাঞ্চলের মুখ্য সংগঠক পদে হাসনাত, মুখপাত্র পদে আসিফ ও জ্যেষ্ঠ যুগ্ম মুখ্য সমন্বয়ক পদে হান্নান দায়িত্ব পালন করেছেন। আর উত্তরাঞ্চল ও দক্ষিণাঞ্চলের সংগঠক পদে ৪২ জন এবং যুগ্ম মুখ্য সমন্বয়ক পদে ২৩ জন দায়িত্বপালন করেন। কমিটিতে ২৪ জনকে যুগ্ম আহ্বায়ক ও ৬ জনকে যুগ্ম সদস্যসচিব করা হয়েছে। আগের কমিটিতে কোনো সম্পাদকীয় পদ ছিল না, তবে পুনর্গঠিত কমিটিতে ৩২টি সম্পাদকীয় পদে ৩২ জনকে দায়িত্ব দেওয়া হয়েছে। তাঁদের সঙ্গে এক-দুজন করে সহসম্পাদক আছেন।

এর বাইরেও কমিটিতে ১৯ জন সহসম্পাদক রয়েছেন। ৫৮ জনকে কমিটিতে সদস্য করা হয়েছে। এ ছাড়া কমিটিতে ১১ জনকে সাংগঠনিক সম্পাদকের দায়িত্ব দেওয়া হয়েছে। ২০২৫ সালের ২৮ ফেব্রুয়ারি ২১৭ সদস্যের কমিটি নিয়ে যাত্রা শুরু করেছিল এনসিপি। পরে কমিটিতে কিছু সংযোজন-বিয়োজন হয়েছে। এখন এনসিপির কেন্দ্রীয় কমিটিতে নতুন করে যুক্ত হয়েছেন গত এপ্রিলে দলটিতে যোগ দেওয়া অবিভক্ত বাংলার প্রথম প্রধানমন্ত্রী শেরেবাংলা এ কে ফজলুল হকের নাতনি এ কে ফ্লোরা এবং বিএনপির বহিষ্কৃত নেতা ইসহাক সরকার (তিনি এনসিপির ঢাকা মহানগর দক্ষিণেরও আহ্বায়ক)। দুজনই যুগ্ম আহ্বায়কের পদ পেয়েছেন। এ ছাড়া জাতীয় পার্টির সাবেক উপদেষ্টা তারেক এ আদেলকেও এনসিপির কেন্দ্রীয় কমিটির যুগ্ম আহ্বায়ক করা হয়েছে। তবে কমিটি পুনর্গঠনের মধ্য দিয়ে মূলত নাসীরুদ্দীন পাটওয়ারী, হাসনাত আবদুল্লাহ, সারজিস আলম ও আসিফ মাহমুদ সজীব ভুঁইয়াকে দলে অধিকতর গুরুত্বপূর্ণ জায়গায় স্থান দিল এনসিপি। দল গঠনের পর, গত জাতীয় নির্বাচনে এবং সাম্প্রতিক নানা রাজনৈতিক ইস্যুতে এই নেতাদের ভূমিকা গুরুত্বপূর্ণ হয়ে ওঠে। এরই প্রতিফলন এবার দলীয় পদে ঘটল। কমিটি পুনর্গঠনের ক্ষেত্রে সংশ্লিষ্ট নেতাদের দক্ষতা (পারফরম্যান্স) বিবেচনায় নেওয়া হয়েছে বলে এনসিপির দায়িত্বশীল নেতারা জানিয়েছেন।

পুনর্গঠিত কমিটিতে শীর্ষ ছয়ে এনসিপির আট সংসদ সদস্যের মধ্যে তিনজন রয়েছেন। তাঁরা হলেন আহ্বায়ক নাহিদ ইসলাম, সদস্যসচিব আখতার হোসেন ও জ্যেষ্ঠ যুগ্ম আহ্বায়ক হাসনাত আবদুল্লাহ। দলের অন্য পাঁচ সংসদ সদস্য আবদুল্লাহ আল আমিন, আতিকুর রহমান মোজাহিদ, আবদুল হান্নান মাসউদ, মাহমুদা আলম মিতু ও নুসরাত তাবাসসুম কমিটিতে যুগ্ম আহ্বায়ক পদে রয়েছেন। এনসিপির এর আগের কমিটির ১১টি শীর্ষ পদ দলটির নেতৃত্বের ‘সুপার ইলেভেন’ হিসেবে পরিচিত ছিল। পুনর্গঠনের পর তা ‘সুপার সিক্সে’ রূপ নিল। তবে এনসিপির পক্ষ থেকে দলটির রাজনৈতিক পর্ষদের ১৬ জন সদস্যকে দলটির নেতৃত্বের ''সুপার সিক্সটিন'' বলা হচ্ছে। দলটির সর্বোচ্চ নীতিনির্ধারণী ফোরাম রাজনৈতিক পর্ষদে দলের শীর্ষ ছয় নেতা ছাড়া অন্য ১০ জন হলেন: আবদুল্লাহ আল আমিন, আরিফুল ইসলাম আদীব, আতিকুর রহমান মোজাহিদ, আবদুল হান্নান মাসউদ, আলী আহসান জুনায়েদ, সারোয়ার তুষার, আকরাম হুসাইন, সালেহউদ্দিন সিফাত, মাহমুদা আলম মিতু ও নুসরাত তাবাসসুম।', 'নিজস্ব প্রতিবেদক', 'https://media.prothomalo.com/prothomalo-bangla/2026-10-23/6kk616tc/WhatsApp-Image-2026-10-23-at-2.33.44-PM.jpeg', 'https://www.prothomalo.com/politics/669vboj19s', '2026-10-23 13:55:57'),
(1, 'ইতালি, গ্রিস ও সাইপ্রাস থেকে ৩৫ বাংলাদেশিকে ফেরত পাঠানো হয়েছে', 'bangladesh/v0fngdd2ql', 'ইউরোপের তিন দেশ ৩৫ বাংলাদেশিকে ফেরত পাঠিয়েছে। এর মধ্যে ইতালি থেকে ১৯, গ্রিস থেকে ১০ ও সাইপ্রাস থেকে ছয় বাংলাদেশি দেশে ফিরেছেন।', 'ইউরোপের তিন দেশ ৩৫ বাংলাদেশিকে ফেরত পাঠিয়েছে। এর মধ্যে ইতালি থেকে ১৯, গ্রিস থেকে ১০ ও সাইপ্রাস থেকে ছয় বাংলাদেশি দেশে ফিরেছেন। ইমিগ্রেশন পুলিশ ও বিমানবন্দর সূত্র বলেছে, আজ শুক্রবার ভাড়া করা একটি বিশেষ ফ্লাইটে (পিভিজি ৯৪৪৫) সকাল সোয়া আটটায় ৩৫ বাংলাদেশি হজরত শাহজালাল আন্তর্জাতিক বিমানবন্দরে নামেন। হজরত শাহজালাল আন্তর্জাতিক বিমানবন্দরে সিভিল এভিয়েশন সিকিউরিটি ও প্রবাসীকল্যাণ ডেস্কের সহযোগিতায় ফেরত আসা বাংলাদেশিদের জরুরি সহায়তা, কাউন্সেলিং ও নিজ নিজ বাড়ি পৌঁছানোর জন্য আর্থিক সহায়তা দেয় ব্র্যাকের মাইগ্রেশন প্রোগ্রাম। এ সময় পররাষ্ট্র মন্ত্রণালয় ও ইউরোপীয় ইউনিয়নের প্রতিনিধি উপস্থিত ছিলেন।

৩৫ জনের ফেরত আসার বিষয়ে জানতে চাইলে ব্র্যাকের সহযোগী পরিচালক (মাইগ্রেশন প্রোগ্রাম অ্যান্ড ইয়ুথ প্ল্যাটফর্ম) শরিফুল হাসান প্রথম আলোকে বলেন, একটি বিশেষ বিমানে ইতালি থেকে ১৯, গ্রিস থেকে ১০ ও সাইপ্রাস থেকে ছয় বাংলাদেশি দেশে ফিরছেন। সবাইকে ইউরোপীয় ইউনিয়ন ও ব্র্যাকের যৌথ অর্থায়নে বাস্তবায়িত প্রত্যাশা–২ প্রকল্প থেকে বিমানবন্দরে সহায়তা দেওয়া হয়েছে। পরবর্তী সময় কাউন্সিলিং ও প্রশিক্ষণ শেষে সবাইকে অর্থনৈতিক সহায়তা দেওয়া হবে। ইউরোপ থেকে নথিপত্রহীন বা অনিয়মিত বাংলাদেশিদের ফেরত আনতে বাংলাদেশ সরকার ২০১৭ সালে ইউরোপীয় দেশগুলোর সঙ্গে স্ট্যান্ডার্ড অপারেটিং প্রসিডিউরস (এসওপি) চুক্তি স্বাক্ষর করেছে। এর আওতায় এ পর্যন্ত প্রায় পাঁচ হাজার বাংলাদেশি ফেরত এসেছেন। এর মধ্যে সবচেয়ে বেশি ফেরত এসেছেন সাইপ্রাস, ইতালি, রোমানিয়া ও ফ্রান্স থেকে।

এ বিষয়ে শরিফুল হাসান বলেন, গত কয়েক বছরে ইউরোপ থেকে ফেরত আসা সবচেয়ে বেশি লোক তাঁরা পেয়েছেন ইতালি, গ্রিস ও জার্মানি থেকে। যাঁরা ফেরত এসেছেন, তাদের বিমানবন্দরে জরুরি সহায়তা, কাউন্সেলিং ও পরে অর্থনৈতিক সহায়তা দেওয়া হয়; যাতে তাঁরা আবার ঘুরে দাঁড়াতে পারেন।‌ পাশাপাশি ঝুঁকি নিয়ে যেন লোকজন ইউরোপে না যায়, সে জন্য সারা দেশে সচেতনতা তৈরির কাজ চলছে। এর বাইরে বৈধভাবে বাংলাদেশ থেকে ইউরোপে কর্মী নেওয়ার উদ্যোগ জোরদার করেছে সরকার।', 'নিজস্ব প্রতিবেদক', 'https://media.prothomalo.com/prothomalo-bangla/2026-10-10/jzz6r2jn/ad4a153e_f920_4c2f_9879_f09583c8e0bd.webp', 'https://www.prothomalo.com/bangladesh/v0fngdd2ql', '2026-10-23 12:38:03'),
(1, 'সৌদির কারাগারে সাড়ে ৭ হাজার বন্দী, দুজনের মৃত্যুদণ্ডে রায়ের অনুলিপি চায় সরকার', 'bangladesh/0z7gd3plgv', 'ফিরল শাহেদের মরদেহ', 'সৌদি আরবের বিভিন্ন শহরের কারাগারে সাড়ে সাত হাজারের মতো বাংলাদেশি বন্দী আছেন বলে জানিয়েছেন পররাষ্ট্র প্রতিমন্ত্রী শামা ওবায়েদ ইসলাম। তিনি বলেছেন, সৌদি আরবে দুই বাংলাদেশির মৃত্যুদণ্ড কার্যকরের বিষয়ে বিস্তারিত জানতে দেশটির সরকারের কাছে রায়ের অনুলিপি চেয়ে চিঠি দিয়েছে বাংলাদেশ। ওই দুই বাংলাদেশির বিষয়ে বিস্তারিত তথ্য এখনো পাওয়া যায়নি। আজ শুক্রবার সকালে ঢাকার হজরত শাহজালাল আন্তর্জাতিক বিমানবন্দরে সৌদি আরবের রাজধানী রিয়াদের কিং খালেদ আন্তর্জাতিক বিমানবন্দরে হামলায় নিহত বাংলাদেশি কর্মী মো. শাহেদ আহম্মেদের মরদেহ এসে পৌঁছায়। সেখানে মরদেহ নিতে যান প্রতিমন্ত্রী। এ সময় সাংবাদিকদের প্রশ্নের জবাবে তিনি এ কথা বলেন।

এর আগে সকাল আটটার পর শাহেদ আহম্মদের মরদেহ ঢাকায় পৌঁছায়। পরে মরদেহ ও সরকারের পক্ষ থেকে সহায়তা শাহেদ আহম্মদের স্ত্রী কহিনুর আক্তার কাকলীকে হস্তান্তর করা হয়। পররাষ্ট্র প্রতিমন্ত্রী বলেন, সৌদি আরবে দুই বাংলাদেশির মৃত্যুদণ্ড কার্যকরের বিষয়ে দেশটির রাষ্ট্রদূতকে ডেকে কথা বলেছে বাংলাদেশ। সৌদি সরকারের কাছে আনুষ্ঠানিকভাবে রায়ের অনুলিপি চাওয়া হয়েছে। সেই অনুলিপি পাওয়া গেলে কী ঘটেছিল, সে বিষয়ে বিস্তারিত জানা যাবে।

এক সাংবাদিকের প্রশ্নের জবাবে প্রতিমন্ত্রী বলেন, সৌদি সরকার বিভিন্ন সময়ে বিভিন্ন দণ্ডে দণ্ডিত ও কারাগারে থাকা ব্যক্তিদের তালিকা পাঠায়। সেখানে এই দুজনের নাম আছে নাকি সেটি সরকার খতিয়ে দেখছে। প্রতিটি দেশের নিজস্ব আইনি কাঠামো ও বিচারব্যবস্থা রয়েছে উল্লেখ করে পররাষ্ট্র প্রতিমন্ত্রী বলেন, অন্য দেশের বিচারব্যবস্থায় হস্তক্ষেপ করা বাংলাদেশের উদ্দেশ্য নয়। তবে বিদেশে কোনো বাংলাদেশি নাগরিক দণ্ডিত হলে বা তাঁর মৃত্যুদণ্ড কার্যকর হলে সে বিষয়ে বিস্তারিত জানা বাংলাদেশের জন্য জরুরি। পররাষ্ট্র মন্ত্রণালয় একা এসব বিষয় সমাধান করে না বলেও জানান শামা ওবায়েদ ইসলাম। প্রবাসীকল্যাণ ও বৈদেশিক কর্মসংস্থান মন্ত্রণালয় এবং আইনগত বিষয়গুলোতে স্বরাষ্ট্র মন্ত্রণালয়সহ সংশ্লিষ্ট মন্ত্রণালয়গুলো এসব বিষয়ে একসঙ্গে কাজ করে বলে জানান তিনি। কোনো বাংলাদেশি দণ্ডিত হওয়ার তথ্য পাওয়া গেলে কূটনৈতিক চ্যানেলে সংশ্লিষ্ট দেশের সরকারের সঙ্গে যোগাযোগ করা হয়। সাজা মওকুফের সুযোগ আছে কি না, তা নিয়েও আলোচনা করা হয় বলে জানান প্রতিমন্ত্রী।

শাহেদ ১১তম ১০ অক্টোবর কিং খালেদ আন্তর্জাতিক বিমানবন্দরে সশস্ত্র গোষ্ঠী হুতিদের হামলায় নিহত হন বাংলাদেশি কর্মী মো. শাহেদ আহম্মেদ। তাঁর বাড়ি বগুড়ার শাহজাহানপুরে। প্রতিমন্ত্রী বলেন, সৌদি আরবে বাংলাদেশের ৪০ লাখের বেশি মানুষ কাজ করেন। এ কারণে দেশটিতে যুদ্ধ বা অন্য কোনো দুর্ঘটনা ঘটলে বাংলাদেশি কর্মীদের হতাহত হওয়ার ঝুঁকি থাকে। গত ছয় মাসে মধ্যপ্রাচ্যে সংঘাতের কারণে নিহত ১১ জন বাংলাদেশির মরদেহ দেশে ফিরিয়ে আনা হয়েছে। এর মধ্যে শাহেদ ১১তম। গত এক মাসে সৌদি আরবে ক্ষেপণাস্ত্র হামলায় তিনজন বাংলাদেশি নিহত হয়েছেন বলে জানান প্রতিমন্ত্রী। তাঁদের মধ্যে একজনের মরদেহ আজ দেশে এসেছে। অন্যদের মরদেহ দ্রুত দেশে ফিরিয়ে আনার চেষ্টা চলছে। শামা ওবায়েদ ইসলাম বলেন, সরকার চায় না ভবিষ্যতে আর কোনো বাংলাদেশি নাগরিককে এভাবে প্রাণ হারাতে হোক। মধ্যপ্রাচ্যের যুদ্ধ বন্ধ হোক এবং কোনো দেশের নাগরিকই যেন এমন নৃশংস হামলার শিকার না হন, সে জন্য তিনি দোয়া করেন। মধ্যপ্রাচ্যের সংঘাতের কারণে বাংলাদেশে আটকে পড়া প্রবাসী কর্মীদের ভিসার মেয়াদ বাড়ানো এবং ভিসা নবায়নের বিষয়ে সৌদি আরবের সঙ্গে আলোচনা চলছে বলে জানিয়েছেন পররাষ্ট্র প্রতিমন্ত্রী।

মিশনের বিরুদ্ধে অভিযোগ পেলে ব্যবস্থা বিদেশে বাংলাদেশের দূতাবাস ও মিশন থেকে প্রবাসীরা যথাযথ সহায়তা পান না, এমন অভিযোগের বিষয়ে শামা ওবায়েদ ইসলাম এক প্রশ্নের জবাবে বলেন, বিদেশে বাংলাদেশের প্রতিটি মিশনে শ্রমকল্যাণ উইং রয়েছে। প্রবাসী কর্মীরা সাধারণত সেখানে তাঁদের অভিযোগ জানান। এসব উইংয়ে প্রবাসীকল্যাণ বা শ্রম মন্ত্রণালয়ের দায়িত্বপ্রাপ্ত কর্মকর্তারা কাজ করেন। প্রতিমন্ত্রী বলেন, প্রবাসীদের সহায়তা করা মিশন ও সরকারের দায়িত্ব। কোথাও মিশনের গাফিলতি থাকলে তা খতিয়ে দেখা হবে এবং প্রয়োজনীয় ব্যবস্থা নেওয়া হবে। ১০ অক্টোবর সৌদি আরবের রিয়াদের কিং খালেদ আন্তর্জাতিক বিমানবন্দরে হামলায় নিহত হন শাহেদ আহম্মেদ। তাঁর বাড়ি বগুড়ার শাহজাহানপুর উপজেলার মাদলা গ্রামে। তাঁর বাবা মো. রফিকুল ইসলাম এবং মা শাহেরা বেগম।

শাহেদ সৌদি আরবের একটি ঠিকাদারি প্রতিষ্ঠানের জেদ্দা প্রকল্পে প্লাম্বার হিসেবে কাজ করতেন। দেশটিতে তাঁর কাজের অনুমতিপত্র (ইকামা) ছিল। ভাইয়ের মৃত্যুর পর ছুটি কাটিয়ে দেশে থেকে রিয়াদ হয়ে জেদ্দায় কর্মস্থলে ফিরছিলেন তিনি। রিয়াদ বিমানবন্দরে হামলার সময় সেখানে অবস্থান করছিলেন শাহেদ। ওই হামলায় শাহেদসহ দুজন বাংলাদেশি নিহত হন। অপরজন কুমিল্লার নাঙ্গলকোট উপজেলার বদরপুর গ্রামের মো. নাসরুল্লাহ বদরপুরি। এ ঘটনায় আরও ২৪ বাংলাদেশি আহত হন বলে সে সময় জানিয়েছিল পররাষ্ট্র মন্ত্রণালয়।', 'নিজস্ব প্রতিবেদক', 'https://media.prothomalo.com/prothomalo-bangla/2026-10-23/x8ysrnsq/shama-obaed.jpeg', 'https://www.prothomalo.com/bangladesh/0z7gd3plgv', '2026-10-23 11:50:10'),
(1, 'প্রথমবার যুক্তরাষ্ট্রে চরমোনাই পীর, কী উদ্দেশ্যে এই সফর', 'politics/xl5uietyhu', 'প্রথমবার যুক্তরাষ্ট্র সফরে গেছেন চরমোনাই পীর রেজাউল করীম। দাওয়াতি সফরে দলের আন্তর্জাতিক পরিচিতি বাড়ার আশা নেতাদের। তবে ফয়জুল করীমের পুরোনো বক্তব্য টেনে সমালোচনাও চলছে।', 'প্রথমবারের মতো যুক্তরাষ্ট্র সফরে গেছেন ইসলামী আন্দোলন বাংলাদেশের আমির মুফতি সৈয়দ মুহাম্মাদ রেজাউল করীম। দলের নেতারা বলছেন, এটি দাওয়াতি সফর। তবে এর মধ্য দিয়ে আন্তর্জাতিক পরিসরে দলের পরিচিতি বাড়ানোর সুযোগও দেখছেন তাঁরা। অন্যদিকে কয়েক মাস আগে দলের জ্যেষ্ঠ নায়েবে আমির ফয়জুল করীমের ‘কাফেলা আমেরিকার দিকে’ বক্তব্যের সঙ্গে এই সফরের যোগসূত্র টেনে সামাজিক যোগাযোগমাধ্যমে সমালোচনা করছেন কেউ কেউ। চরমোনাই পীর হিসেবে পরিচিত রেজাউল করীম ১৩ অক্টোবর সন্ধ্যায় এমিরেটস এয়ারলাইনসের একটি ফ্লাইটে যুক্তরাষ্ট্রের উদ্দেশে ঢাকা ছাড়েন। দলীয় সূত্র বলছে, আন নূর ফাউন্ডেশনের আমন্ত্রণে ১৪ দিনের এই সফরে তিনি যুক্তরাষ্ট্রের বিভিন্ন অঙ্গরাজ্যে প্রবাসী বাংলাদেশিদের সঙ্গে মতবিনিময় এবং মসজিদ ও মুসলিম কমিউনিটিতে ধর্মীয় আলোচনা করছেন। ব্যবসায়ী ও বিভিন্ন আন্তর্জাতিক সংগঠনের নেতাদের সঙ্গে মতবিনিময়ের কর্মসূচিও রয়েছে তাঁর।

ইসলামী আন্দোলনের নেতাদের ভাষ্য, যুক্তরাষ্ট্রে দলের আমিরের চেয়ে চরমোনাই পীর হিসেবে রেজাউল করীমের পরিচিতিই বেশি গুরুত্ব পাচ্ছে। বিভিন্ন দেশের সুফিবাদের অনুসারীদের সঙ্গে তাঁর যোগাযোগ তৈরি হচ্ছে। তাঁদের আমন্ত্রণে তিনি ধর্মীয় আলোচনা ও দাওয়াতি কর্মসূচিতেও অংশ নিচ্ছেন। দলটির নেতারা মনে করছেন, এই সফরের মধ্য দিয়ে আন্তর্জাতিক পরিসরে ইসলামী আন্দোলনের পরিচিতি বাড়তে পারে। তাঁদের ভাষ্য, বাংলাদেশের বাইরে, বিশেষ করে পশ্চিমা দেশগুলোতে ধর্মভিত্তিক রাজনৈতিক দল হিসেবে জামায়াতে ইসলামী পরিচিতি পেলেও ইসলামী আন্দোলন তেমন পরিচিতি পায়নি। এই সফর সেই ঘাটতি কাটানোর পাশাপাশি সুফি ইসলামের চর্চা ও দর্শন তুলে ধরার সুযোগ তৈরি করতে পারে বলে তাঁরা আশা করছেন।

ইসলামী আন্দোলনের মহাসচিব গাজী আতাউর রহমান প্রথম আলোকে বলেন, আন নূর ফাউন্ডেশনের আমন্ত্রণে চরমোনাই পীর যুক্তরাষ্ট্রে গেছেন। দেশটিতে এটি তাঁর প্রথম সফর। সেখানে ইসলামী আন্দোলনের অনুসারীদের পাশাপাশি অন্য দলের লোকজনও তাঁর ধর্মীয় আলোচনা শুনতে আসছেন। দলীয় সূত্র জানায়, এর আগে রেজাউল করীম সৌদি আরবসহ বিভিন্ন মুসলিম দেশ সফর করেছেন।

ফয়জুল করীমের বক্তব্য ঘিরে সমালোচনা চরমোনাই পীরের যুক্তরাষ্ট্র সফর নিয়ে সমালোচনায় উঠে এসেছে ইসলামী আন্দোলনের জ্যেষ্ঠ নায়েবে আমির মুফতি সৈয়দ মুহাম্মদ ফয়জুল করীমের একটি বক্তব্য। গত ২২ জুলাই বরিশালের গৌরনদীতে ইসলামী যুব আন্দোলনের প্রতিষ্ঠাবার্ষিকী উপলক্ষে আয়োজিত এক সম্মেলনে তিনি ইসলামের পক্ষে একটি রাজনৈতিক জোট গঠনের প্রসঙ্গ টানেন। ফয়জুল করীম বলেন, ইসলামের পক্ষে একটি বাক্স তৈরির লক্ষ্যে ইসলামী আন্দোলন জোট করেছিল। এর নেতৃত্বে ছিলেন চরমোনাই পীর। ফয়জুল করীম আরও বলেন, ‘আমরা চলতেছিলাম মদিনার দিকে। কিন্তু স্টিয়ারিং ছিনতাই হয়ে গেছে, ডাকাতি হয়ে গেছে। চলতেছিলাম কাফেলা মদিনার দিকে, হঠাৎ দেখি কাফেলা চলতেছে আমেরিকার দিকে। মদিনাওয়ালারা আমেরিকা যেতে পারে না।’

চরমোনাই পীরের যুক্তরাষ্ট্র সফরের পর সামাজিক যোগাযোগমাধ্যমে কেউ কেউ ওই বক্তব্যের সঙ্গে সফরের যোগসূত্র টেনে সমালোচনা করছেন। বাংলাদেশ মাজলিসুল মোফাসসিরিনের কেন্দ্রীয় সহকারী সেক্রেটারি মাওলানা ফখরুদ্দিন আহমদ ১৪ অক্টোবর তাঁর ফেসবুক পেজে লেখেন, ‘চরমোনাইয়ের পীর সাহেব কি সত্যিই আমেরিকা সফরে যাচ্ছেন? তাহলে তিনি কি আমেরিকামুখী হয়ে গেছেন? জামায়াতের বিরুদ্ধে তো তিনি এমন অভিযোগই করেন।’ তবে ইসলামী আন্দোলনের নেতারা এ সমালোচনাকে যথাযথ মনে করেন না। তাঁদের বক্তব্য, যুক্তরাষ্ট্রে যাওয়া বা সেখানে ধর্মীয় কার্যক্রম পরিচালনার অর্থ দেশটির রাষ্ট্রীয় নীতি কিংবা রাজনৈতিক আদর্শ গ্রহণ করা নয়। দলের মহাসচিব গাজী আতাউর রহমান প্রথম আলোকে বলেন, চরমোনাই পীর যুক্তরাষ্ট্রে গেছেন বলে দেশটির নীতি গ্রহণ করেছেন—এমন সিদ্ধান্তে আসার সুযোগ নেই। সেখানে তিনি কোনো রাজনৈতিক বক্তব্য দিচ্ছেন না; ধর্মীয় বিষয়ে মানুষকে উদ্বুদ্ধ করছেন।

সফরে যেসব কর্মসূচি ১৪ অক্টোবর নিউইয়র্কের জন এফ কেনেডি আন্তর্জাতিক বিমানবন্দরে পৌঁছান রেজাউল করীম। সেখানে তাঁকে অভ্যর্থনা জানান দারুল উলুম নিউইয়র্কের প্রেসিডেন্ট সরদার বরকাতুল্লাহ, প্রতিষ্ঠানটির প্রধান ফকিহ মুফতি মিজানুর রহমান সাঈদ এবং বায়তুল আমান জামে মসজিদের প্রধান ইমাম মাওলানা আজির উদ্দিন। সফরসূচি অনুযায়ী, ১৪ অক্টোবর আমেরিকান মুসলিম সেন্টারের অনুষ্ঠানে অংশ নেন চরমোনাই পীর। পরদিন পোর্ট ওয়াশিংটন মসজিদে ইসলাহি বয়ান দেন। ১৬ অক্টোবর নিউ জার্সির জালালাবাদ জামে মসজিদে জুমার নামাজের বয়ান ও ইমামতি করেন। একই দিন বায়তুল আমান ইসলামিক সেন্টারে ওয়াজ মাহফিলেও বক্তব্য দেন তিনি।

এ ছাড়া ব্রঙ্কস মুসলিম সেন্টার, বাংলাদেশ মুসলিম সেন্টার জামে মসজিদ, ব্রুকলিনের মসজিদ আল-আমান ইনক, জ্যাকসন হাইটসের সানাই পার্টি হল, বাফেলো ও মসজিদে কুবায় ইসলাহি বয়ান এবং বিশেষ ওয়াজ ও দোয়া মাহফিলে অংশ নিয়েছেন মুফতি রেজাউল করীম। নিউইয়র্কের দারুল উলুম, মিশিগানের মাসজিদুন নূর এবং আন নূর কালচারাল সেন্টারেও বিভিন্ন ধর্মীয় অনুষ্ঠানে মুফতি রেজাউল করীমের অংশ নেওয়ার কথা রয়েছে।', 'আব্দুল্লাহ আল জোবায়ের', 'https://media.prothomalo.com/prothomalo-bangla/2025-12-03/qk0xvkc6/RangpurDH049420251203IMG-20251203-WA0026.jpg', 'https://www.prothomalo.com/politics/xl5uietyhu', '2026-10-23 11:43:25'),
(1, 'বেপরোয়া গতিতে চলছিল বাস, পিকআপের সঙ্গে সংঘর্ষে প্রাণ গেল দুজনের', 'bangladesh/xi2ygryy24', 'মো. সেলিম মিয়া প্রথম আলোকে বলেন, মাথাসহ শরীরের বিভিন্ন স্থানে গুরুতর জখম হয়ে ওই দুজনের মৃত্যু হয়েছে। বাসটি খুব দ্রুত ও বেপরোয়া গতিতে চালানো হচ্ছিল।', 'কক্সবাজারের চকরিয়ায় যাত্রীবাহী বাসের সঙ্গে সবজিবাহী পিকআপের মুখোমুখি সংঘর্ষ হয়েছে। এ ঘটনায় পিকআপে থাকা দুজন নিহত হয়েছেন। গতকাল বৃহস্পতিবার দিবাগত রাত সোয়া ১২টার দিকে চট্টগ্রাম-কক্সবাজার মহাসড়কের খুটাখালী ইউনিয়নের নয়াপাড়া সবুজ পাহাড় এলাকায় এ দুর্ঘটনা ঘটে। নিহত ব্যক্তিরা হলেন কক্সবাজারের টেকনাফ উপজেলার হ্নীলা ইউনিয়নের ফুলের ডেইল এলাকার আবুল কালামের ছেলে আবদুল্লাহ (২৭) ও চকরিয়া উপজেলার রামপুরা এলাকার মো. দুলালের ছেলে মো. ইয়াছিন (৩০)। দুর্ঘটনার সময় নিহত দুজন পিকআপ ভ্যানটিতে ছিলেন। পিকআপ ভ্যানটি চকরিয়া থেকে টেকনাফের রোহিঙ্গা শিবিরে সবজি নিয়ে যাচ্ছিল।

মালুমঘাট হাইওয়ে থানার পুলিশ সূত্রে জানা গেছে, চকরিয়া থেকে কক্সবাজারগামী পিকআপ ভ্যানটির সঙ্গে চট্টগ্রামগামী শ্যামলী এন আর পরিবহনের একটি বাসের মুখোমুখি সংঘর্ষ হয়। এ ঘটনায় পিকআপে থাকা আবদুল্লাহ ও ইয়াছিন গুরুতর আহত হন। খবর পেয়ে মালুমঘাট হাইওয়ে থানার একদল পুলিশ ঘটনাস্থলে পৌঁছায়। পরে স্থানীয় লোকজনের সহযোগিতায় আহত দুজনকে উদ্ধার করে চকরিয়া উপজেলা স্বাস্থ্য কমপ্লেক্সে নেওয়া হয়। সেখানে চিকিৎসক তাঁদের মৃত ঘোষণা করেন। মালুমঘাট হাইওয়ে থানার উপপরিদর্শক মো. সেলিম মিয়া প্রথম আলোকে বলেন, মাথাসহ শরীরের বিভিন্ন স্থানে গুরুতর জখম হয়ে ওই দুজনের মৃত্যু হয়েছে। বাসটি খুব দ্রুত ও বেপরোয়া গতিতে চালানো হচ্ছিল। দুর্ঘটনাকবলিত গাড়ি দুটি থানায় নেওয়া হয়েছে। এ ঘটনায় প্রয়োজনীয় আইনি ব্যবস্থা নেওয়া হবে।', 'প্রতিনিধি', 'https://media.prothomalo.com/prothomalo-bangla/2026-10-23/ygo3d4lb/50f40285-257f-4626-83dd-7e82cddf4f60.jfif', 'https://www.prothomalo.com/bangladesh/xi2ygryy24', '2026-10-23 10:48:16'),
(1, 'একজন স্পষ্টভাষী লেখক সৈয়দ আবুল মকসুদ', 'bangladesh/zgjl61gjla', '৮০তম জন্মবার্ষিকী', 'কিছু কিছু মৃত্যু অযাচিতভাবে হানা দেয়। একদিন টেলিভিশনের স্ক্রলে দেখলাম, সৈয়দ আবুল মকসুদ আর নেই। তরতাজা মানুষটা হঠাৎ করেই ‘নেই’ হয়ে গেলেন। তখন করোনাকাল। জানতে পারলাম, দুদিন ধরে জ্বরে ভুগছিলেন। তারপর সব শেষ। তাঁর সঙ্গে আমার পরিচয় খুব বেশি দিনের নয়। বড়জোর সাত-আট বছরের। একই পত্রিকায় কলাম লিখি। একসঙ্গে টক শো করি। কাছাকাছি বাসা। তাই আসা-যাওয়া প্রায়ই হয় এক গাড়িতে। গাড়িতে বসে অনেক কথা হয়, যেগুলো টেলিভিশনে বলা যায় না, পত্রিকায় লেখা যায় না। আমি মানুষটাকে নতুন করে আবিষ্কার করি। একবার একটা টক শো করে ফিরছি। রাত নয়টা পেরিয়ে গেছে। গুলশান ২ নম্বরে চৌরাস্তার ট্রাফিক সিগন্যালে আটকা পড়েছি। দায়িত্বরত এক ট্রাফিক কনস্টেবল দৌড়ে এসে জানালার কাচে টোকা দিলেন। মকসুদ ভাই কাচ নামালেন। কনস্টেবল সালাম দিয়ে করমর্দনের জন্য হাত বাড়িয়ে দিলেন। বললেন, ‘আমি আপনাকে খুব ভালোবাসি।’

মকসুদ ভাইয়ের ছিল ‘সিগনেচার পোশাক’। সারা শরীর সাদা কাপড়ে মোড়া। আমরা অনেকেই কৌতুক করে বলি, কাফনের কাপড়। সেই কাফন যে এত তাড়াতাড়ি তাঁর শরীরে উঠবে, ভাবিনি। একদিন তাঁকে বললাম, ভাবছি, আমিও এ রকম পোশাক পরব। তবে সাদা নয়। সাদা হলে সবাই ভাববে আপনাকে নকল করছি। আমি পরব গেরুয়া। বললেন, ‘এ কাজ করবেন না। খুব গরম লাগে। আমি তো আর এখন এটা ছাড়তে পারছি না।’ মকসুদ ভাই প্রতিবাদের প্রতীকী ভাষা হিসেবে পোশাকটা নিয়েছিলেন। এ রকম আর কেউ ছিলেন না এ শহরে। ফলে তাঁকে সহজেই চেনা যেত। সমস্যা হলো, পোশাকে পকেট নেই। টাকাপয়সা বা মোবাইল ফোন রাখা যায় না। মকসুদ ভাই ‘কপর্দকহীন’ অবস্থায় চলাফেরা করতেন।

আমি নতুন লেখক। সবে একটা বই বেরিয়েছে। বইটা ‘হিট’ হয়েছে। তখন একুশে বইমেলা চলছে। দুরু দুরু বুকে গিয়ে প্রকাশকের স্টলে বসলাম। কেউ আমাকে চেনে না। মকসুদ ভাই বললেন, বসেন। সামনে পাঠকের লম্বা লাইন। তাঁরা বই কিনছেন। সবাই মকসুদ ভাইয়ের অটোগ্রাফ চান। কিন্তু বই কিনছেন আমারটা। আমাকে তো কেউ চেনে না! মকসুদ ভাই আমার লেখা বইয়ে নির্বিকার চিত্তে অটোগ্রাফ দিয়ে যাচ্ছেন। হেসে বললেন, ‘এত বছর ধরে লিখছি। কিছুই করতে পারলাম না। অথচ এক বইয়েই আপনি মাত করে দিলেন!’ আমি লজ্জা পেলাম। এক রাতে টক শো করে এক গাড়িতে বাসায় ফিরছি। সরাসরি বাসায় না গিয়ে তিনি আমাকে নিয়ে গেলেন কলাবাগানের একটা বাড়িতে। দোতলায় উঠে একটা কামরায় ঢুকলেন। দেখি, দেয়ালের সঙ্গে দাঁড়িয়ে আছে কয়েকটি বুকশেলফ। তাতে অনেক বই। মকসুদ ভাই বললেন, ‘একটা পাঠাগার বানানোর চেষ্টা করছি। পারলে কিছু বই দিয়েন।’

২. একটা কথা চাউর হয়েছিল যে মাওলানা ভাসানী পঁচাত্তরের আগস্ট অভ্যুত্থানকে সমর্থন করে ঢাকায় টেলিগ্রাম পাঠিয়েছিলেন। এটি প্রচার করে অভ্যুত্থানকারীরা ভাসানীর কাঁধে বন্দুক রেখে তাঁদের কাজের ন্যায্যতা খুঁজেছিলেন। আমি যখন ভাসানীকে নিয়ে লিখতে শুরু করি, তখন তাঁকে এ ব্যাপারে জিজ্ঞেস করেছিলাম, জানি আপনি মাওলানার ভক্ত। তিনি এমন কাজ করতে পারলেন? মকসুদ ভাই বললেন, ‘প্রচারটি সর্বৈব মিথ্যা। মাওলানা তখন টাঙ্গাইলের সন্তোষে, অসুস্থ হয়ে শয্যাশায়ী। তিনি কোথা থেকে কার কাছে করলেন? আমি তো বাসসের গুরুত্বপূর্ণ পদে আছি। এ সংবাদ তো বাসস থেকে যায়নি। এই টেলিগ্রামের গল্প অভ্যুত্থানকারীরা বঙ্গভবনে বসে বানিয়েছে। পত্রিকা সেসব ছেপেছে।’

৩. বাংলাদেশের বুদ্ধিবৃত্তিক পরিমণ্ডলে এমন কিছু মানুষ আছেন, যাঁদের পরিচয় কোনো একটি পেশা বা পরিচয়ের মধ্যে আটকে নেই। তাঁরা একই সঙ্গে লেখক, গবেষক, চিন্তক, সমাজবীক্ষক ও সময়ের বিবেক। সৈয়দ আবুল মকসুদ ছিলেন তেমনই এক বিরল প্রকৃতির মানুষ। তাঁর বহুমাত্রিক পরিচয়—সাংবাদিক, কলামিস্ট, প্রাবন্ধিক, গবেষক। কিন্তু এসব পরিচয়ের চেয়েও বড় ছিল তাঁর সাহসী মন এবং সত্যসন্ধানী দৃষ্টিভঙ্গি। সাহিত্য, ইতিহাস, রাজনীতি ও সংস্কৃতির জটিল প্রশ্নগুলোকে তিনি সহজ অথচ গভীর ভাষায় ব্যাখ্যা করেছেন। তিনি সাংবাদিকতাকে জীবনের কর্মক্ষেত্র হিসেবে বেছে নিয়েছিলেন। কিন্তু সাংবাদিকতার সীমিত পরিসরে আবদ্ধ না থেকে তিনি নিজেকে গড়ে তুলেছিলেন একজন গবেষক-লেখক হিসেবে। তাঁর কলমের প্রধান শক্তি ছিল তথ্য, যুক্তি ও ইতিহাস-সচেতনতা। তাঁর কলামে থাকত সমাজের অসংগতি নিয়ে তীক্ষ্ণ বিদ্রূপ ও স্যাটায়ার। মানিকগঞ্জের নিভৃত গ্রামে তাঁর জন্ম। নদী, মাঠ, বৃক্ষ আর বাংলার জনজীবনের যে সহজ সৌন্দর্যের মধ্যেই শৈশবে তিনি দেশ ও মানুষের প্রতি এক অন্তর্গত টান অনুভব করেছিলেন, শিকড়ের সেই মাটি কোনো দিন তাঁর সত্তা থেকে আলাদা হয়নি। বাংলা ভাষায় গবেষণাধর্মী রচনার ক্ষেত্রে সৈয়দ আবুল মকসুদ একটি স্বতন্ত্র ধারা নির্মাণ করেছিলেন। তিনি রবীন্দ্রনাথ ঠাকুর, বুদ্ধদেব বসু, মোহনদাস গান্ধী, সৈয়দ ওয়ালীউল্লাহ, মাওলানা ভাসানী, স্যার সলিমুল্লাহসহ অনেক ঐতিহাসিক ও সাহিত্যিক ব্যক্তিত্বের জীবন ও কর্ম নিয়ে গভীর গবেষণা করেছেন। তাঁর গবেষণা কেবল তথ্যের সমাবেশ নয়, ইতিহাসের সত্য অনুসন্ধানের চেষ্টা। বিশেষত মাওলানা ভাসানীকে নিয়ে তাঁর কাজ বাংলা ভাষার রাজনৈতিক জীবনী সাহিত্যে এক গুরুত্বপূর্ণ সংযোজন। তিনি ভাসানীকে কোনো পৌরাণিক নায়ক হিসেবে তুলে ধরেননি; বরং একজন রাজনৈতিক নেতা, গণমানুষের প্রতিনিধি এবং ইতিহাস নির্মাতারূপে দেখিয়েছেন।

৪. একজন লেখকের প্রকৃত মূল্য নির্ধারিত হয় তাঁর সময়ের সঙ্গে সম্পর্কের মাধ্যমে। সৈয়দ আবুল মকসুদ তাঁর সময়কে শুধু দেখেননি, প্রশ্নও করেছেন। তিনি ছিলেন সেই বিরল কণ্ঠস্বর, যিনি সমাজের প্রচলিত ভ্রম ও আত্মপ্রবঞ্চনার বিরুদ্ধে কথা বলেছেন। তাঁর কলামগুলোতে তাই দেখা যায় নীরব প্রতিবাদ, নৈতিক ক্ষোভ এবং যুক্তিসম্মত বিশ্লেষণের এক অনন্য সমন্বয়। তিনি আমাদের শিখিয়েছেন, বুদ্ধিজীবীর কাজ ক্ষমতার প্রশংসা করা নয়; বরং সত্যকে অনুসরণ করা, তা যত অপ্রিয়ই হোক না কেন।', 'মহিউদ্দিন আহমদ', 'https://media.prothomalo.com/prothomalo-bangla/2026-10-22/6p3odf96/Capture.PNG', 'https://www.prothomalo.com/bangladesh/zgjl61gjla', '2026-10-23 09:02:38'),
(2, 'বিল নিয়ে সমঝোতার পরও কাটেনি দুই নেতার বিরোধ, অস্বস্তিতে অষ্টগ্রাম বিএনপি', 'bangladesh/district/4lufdolaqm', 'সমঝোতার পরও দুই নেতা একসঙ্গে বসেননি। তাঁদের মধ্যে ফোনে যোগাযোগও নেই। কেউ কেউ এক পক্ষ ছেড়ে অন্য পক্ষে যোগ দিচ্ছেন।', 'কিশোরগঞ্জের অষ্টগ্রামে বিল মাকশার নিয়ন্ত্রণ নিয়ে উপজেলা বিএনপির সভাপতি সৈয়দ সাঈদ আহমেদ ও সাংগঠনিক সম্পাদক এস এম শাহিনের বিরোধে দলের মধ্যে অস্বস্তি বাড়ছে। গত ৩০ সেপ্টেম্বর কিশোরগঞ্জ-৪ (ইটনা, মিঠামইন, অষ্টগ্রাম) আসনের সংসদ সদস্য বীর মুক্তিযোদ্ধা ফজলুর রহমানের মধ্যস্থতায় বিলের নিয়ন্ত্রণ ভাগাভাগির সিদ্ধান্ত হয়। তবে সমঝোতার পরও দুই নেতার দূরত্ব কমেনি। দলীয় সভা, কর্মসূচি ও সাংগঠনিক কার্যক্রমেও গতি ফেরেনি। গত ২৫ সেপ্টেম্বর বিলের নিয়ন্ত্রণ নিয়ে দুই পক্ষের সংঘর্ষে অন্তত ২৫ জন আহত হন। পুলিশ দুই পক্ষের বাড়িতে অভিযান চালিয়ে শতাধিক বল্লমসহ দেশীয় অস্ত্র উদ্ধার করে। তবে এ ঘটনায় কেউ আটক হননি, মামলাও হয়নি। পরদিন জেলা বিএনপি সাঈদ আহমেদকে কারণ দর্শানোর নোটিশ দেয়। পরে তাঁর জবাব সন্তোষজনক বিবেচিত হওয়ায় নোটিশ প্রত্যাহার করা হয়। দলীয় নেতা-কর্মীরা বলেন, সমঝোতার পরও দুই নেতা একসঙ্গে বসেননি। তাঁদের মধ্যে ফোনে যোগাযোগও নেই। কেউ কেউ এক পক্ষ ছেড়ে অন্য পক্ষে যোগ দিচ্ছেন। এতে দলীয় শৃঙ্খলা ও সাংগঠনিক কার্যক্রম ক্ষতিগ্রস্ত হচ্ছে বলে মনে করেন তাঁরা। অষ্টগ্রাম উপজেলা বিএনপির জ্যেষ্ঠ সহসভাপতি গিয়াস উদ্দিন আশরাফী কোনো পক্ষে নেই। তিনি প্রথম আলোকে বলেন, সংসদ সদস্য সমঝোতা করে দিলেও দুই নেতার মধ্যে মনের মিল হয়েছে বলে মনে হয় না। এতে সাধারণ মানুষের কাছে বিএনপির ভাবমূর্তি ক্ষতিগ্রস্ত হচ্ছে। দলীয় আদর্শ ধরে রাখার মধ্যেই এ পরিস্থিতি থেকে উত্তরণের পথ দেখেন তিনি।

হাওরাঞ্চলের অষ্টগ্রামের অর্থনীতি কৃষি ও মৎস্যসম্পদের ওপর নির্ভরশীল। উপজেলার গুরুত্বপূর্ণ জলমহালগুলোর একটি বিল মাকশা। প্রতিবছর জেলা প্রশাসন থেকে বিলটি ইজারা দেওয়া হয়। স্থানীয় লোকজন ও দলীয় নেতা-কর্মীদের ভাষ্য, ২০২৪ সালের ৫ আগস্টের রাজনৈতিক পটপরিবর্তনের পর বিলটির নিয়ন্ত্রণ চলে যায় সাঈদ আহমেদের পক্ষের লোকজনের হাতে। পরে শাহিন তাঁর খালাতো ভাই মো. জাহাঙ্গীর আলমের নামে ৫০ লাখ ১২ হাজার ৫০০ টাকায় বিলটি এক বছরের জন্য ইজারা নেন। তবে ইজারা পেলেও তিনি নিয়ন্ত্রণ নিতে পারেননি বলে অভিযোগ আছে। আর্থিক ক্ষতির মুখে পড়ে ইজারামূল্য ফেরত চেয়ে হাইকোর্টে মামলা করেন শাহিন। মামলাটি এখনো চলছে।

এর পর থেকেই দুই নেতার বিরোধ প্রকাশ্যে আসে। গত ২১ সেপ্টেম্বর নতুন ইজারার বিজ্ঞপ্তি প্রকাশের পর দুজনই অংশ নেন। শাহিন ৫০ লাখ ১৩ হাজার ৭৫০ টাকায় আবারও বিলটি ইজারা পান। কিন্তু নিয়ন্ত্রণ নিতে না পারাকে কেন্দ্র করে ২৫ সেপ্টেম্বর দুপুরে পূর্ব অষ্টগ্রামের আখড়া বাজারে দুই পক্ষ সংঘর্ষে জড়ায়। প্রায় এক ঘণ্টা পর পুলিশ পরিস্থিতি নিয়ন্ত্রণে আনে। কয়েকটি ব্যবসাপ্রতিষ্ঠানে ভাঙচুর ও লুটপাটের ঘটনাও ঘটে। এ ঘটনার পর অষ্টগ্রামে বিএনপির সাংগঠনিক তৎপরতা ঝিমিয়ে পড়ে। স্থানীয় রাজনীতি হয়ে ওঠে দুই নেতাকেন্দ্রিক।

৩০ সেপ্টেম্বর অষ্টগ্রাম উপজেলা মিলনায়তনে দুই পক্ষকে নিয়ে বৈঠক করেন সংসদ সদস্য ফজলুর রহমান। সেখানে উপজেলা বিএনপির অধিকাংশ নেতা উপস্থিত ছিলেন। তাঁদের কেউ কেউ বিরোধের কারণে দলীয় শৃঙ্খলা ও সাংগঠনিক কার্যক্রমে স্থবিরতার কথা তুলে ধরেন। বৈঠকে সিদ্ধান্ত হয় আগের বছরের ইজারামূল্য বাবদ শাহিনকে ৫০ লাখ টাকা পরিশোধ করবেন সাঈদ আহমেদ। চলতি বছরের ইজারামূল্যের অর্ধেক দিয়ে বিলের অর্ধেক লাভ-ক্ষতির অংশীদার হবেন সাঈদ। উপস্থিত সবার সামনে দুই নেতাই এ সিদ্ধান্ত মেনে নেন। দলীয় সূত্র বলছে, সমঝোতায় দুজনই ভেতরে–ভেতরে অসন্তুষ্ট ছিলেন। সাঈদ পক্ষের প্রত্যাশা ছিল, টাকা পরিশোধ না করেই বিলের অর্ধেকের নিয়ন্ত্রণ পাওয়া। অন্যদিকে শাহিন চেয়েছিলেন, আগের বছরের ক্ষতি পুষিয়ে নিতে বিলের একক নিয়ন্ত্রণ। সমঝোতার পর শাহিন বিলের নিয়ন্ত্রণ নিলেও সাঈদ এখনো টাকা পরিশোধ করেননি, বিলেও যাচ্ছেন না। এতে নতুন করে বিরোধের আশঙ্কা করছেন নেতা-কর্মীরা।

শাহিন প্রথম আলোকে বলেন, সংসদ সদস্যের সিদ্ধান্তের পর তিনি বিলে যাচ্ছেন, তবে এখনো টাকা পাননি। গত বুধবার সংসদ সদস্যের এক ঘনিষ্ঠ ব্যক্তির মাধ্যমে সাঈদ তাঁকে জানিয়েছেন, তিনি (সাঈদ) বিলের অংশীদার হতে চান না। সমঝোতার পর দুই নেতার মধ্যে দেখাসাক্ষাৎ বা কথা হয়নি বলেও জানান শাহিন। বিরোধে দলের ক্ষতি হচ্ছে কি না, জানতে চাইলে তিনি বলেন, কমবেশি তো হচ্ছেই। সংসদ সদস্যের সিদ্ধান্ত মেনে নিয়েছেন বলে জানান সাঈদ আহমেদ। তিনি বলেন, বিলে তাঁর ২০ থেকে ৩০ লাখ টাকা বিনিয়োগ আছে। হিসাব-নিকাশ করে টাকা পরিশোধ করবেন, তবে বিলে যাবেন না। তাঁর ভাষ্য, অংশীদারত্বে আবার দ্বন্দ্ব হলে দলের ক্ষতি হবে। শাহিনের সঙ্গে বিরোধের কারণ শুধু বিল নয় বলেও দাবি করেন তিনি।

অষ্টগ্রাম উপজেলা বিএনপির সহসভাপতি মো. শাহ আলম বলেন, অষ্টগ্রামে আগে এ ধরনের সংঘাত হয়নি। দুই নেতার বিরোধে দলের অবস্থা ভালো নেই। তবে দ্রুত পরিস্থিতির উন্নতি হবে বলে তিনি আশাবাদী। উপজেলা বিএনপির সাধারণ সম্পাদক জাকির হোসেন বলেন, দুই নেতার বিরোধে দলীয় সভা, কর্মসূচি ও সাংগঠনিক কার্যক্রমে গতি ফেরানো যাচ্ছে না। তাঁর ভাষ্য, দলের বেশির ভাগ নেতা-কর্মী সুস্থ ধারার রাজনীতিতে আছেন। ছোট একটি অংশের মধ্যে ভোগ, দখল ও বিচারহীনতার প্রবণতা রয়েছে।

গত বৃহস্পতিবার অষ্টগ্রামে প্রেসিডেন্ট জিয়াউর রহমান গোল্ডকাপ ফুটবল খেলায় সংসদ সদস্য ফজলুর রহমান প্রধান অতিথি ছিলেন। খেলা ব্যবস্থাপনা কমিটির সভাপতি ছিলেন শাহিন। দলীয় সূত্রের দাবি, সাঈদকে আমন্ত্রণ জানানো হলেও তিনি অনুষ্ঠানে যাননি। কিশোরগঞ্জ-৪ আসনের সংসদ সদস্য ফজলুর রহমান প্রথম আলোকে বলেন, ‘দুই নেতার বিরোধে দলের ক্ষতি হচ্ছিল। সবকিছু বিবেচনায় নিয়ে শর্তসাপেক্ষে বিলের নিয়ন্ত্রণ ভাগ করে দিয়েছি। এখন সমস্যা থাকলে আবার আলোচনা করে সমাধান করা হবে। তবে ভবিষ্যতে এ নিয়ে নতুন কোনো ঘটনা ঘটলে ছাড় দেওয়া হবে না।’ জেলা বিএনপির সাধারণ সম্পাদক ও কিশোরগঞ্জ সদর আসনের সংসদ সদস্য মো. মাজহারুল ইসলাম বলেন, দুই জ্যেষ্ঠ নেতার দায়িত্বহীন কর্মকাণ্ডে জেলা বিএনপি বিব্রত। এ নিয়ে আবার কোনো ঘটনা ঘটলে বহিষ্কারের মতো সাংগঠনিক ব্যবস্থা নেওয়া হবে।', 'সুমন মোল্লা', 'https://media.prothomalo.com/prothomalo-bangla/2026-10-23/fl9jybrx/KISHORGONJ-2.JPG', 'https://www.prothomalo.com/bangladesh/district/4lufdolaqm', '2026-10-23 17:21:44'),
(2, 'তলব করতে পারে, হাজিরে বাধ্য করতে পারে না সংসদীয় কমিটি', 'politics/5zyn4wzhnp', 'কেউ তলবে সাড়া না দিলে তাঁকে হাজির করা বা নথি দিতে বাধ্য করার পূর্ণাঙ্গ আইনি ক্ষমতা সংসদীয় কমিটির নেই।', 'সংসদীয় কমিটি কাউকে সাক্ষ্য দিতে তলব করতে পারে, চাইতে পারে প্রয়োজনীয় নথিপত্রও। কিন্তু কেউ তলবে সাড়া না দিলে তাঁকে হাজির করা বা নথি দিতে বাধ্য করার পূর্ণাঙ্গ আইনি ক্ষমতা কমিটির নেই। স্বাধীনতার পাঁচ দশকের বেশি সময় পার হলেও এ ঘাটতি দূর করতে কোনো আইন হয়নি। ২০১১ সালে এ বিষয়ে একটি খসড়া তৈরি হলেও তা আইনে পরিণত হয়নি। ফলে সংসদীয় কমিটির তদন্তের ক্ষমতা বাড়ানো এবং জবাবদিহি নিশ্চিত করার উদ্যোগ এখনো অসম্পূর্ণ। সংবিধানের ৭৬ অনুচ্ছেদে সংসদীয় কমিটির গঠন ও দায়িত্বের কথা বলা হয়েছে। কমিটি খসড়া আইন বা বিল পরীক্ষা, আইনের বাস্তবায়ন পর্যালোচনা এবং মন্ত্রণালয়ের কার্যক্রম তদন্ত করতে পারে। এ জন্য সংশ্লিষ্ট মন্ত্রণালয়ের কাছে তথ্য চাইতে পারে এবং অনুমোদিত প্রতিনিধির মাধ্যমে মৌখিক বা লিখিত উত্তর নিতে পারে।

একই অনুচ্ছেদে আরও বলা হয়েছে, আইন করে সংসদীয় কমিটিকে সাক্ষী হাজির করা, শপথে জিজ্ঞাসাবাদ এবং দলিলপত্র দাখিলে বাধ্য করার ক্ষমতা দেওয়া যাবে। জাতীয় সংসদের কার্যপ্রণালি বিধিতেও সংসদীয় কমিটির কাউকে সাক্ষী হিসেবে হাজির হতে বলা এবং প্রয়োজনীয় কাগজপত্র ও নথি তলব করার ক্ষমতা আছে। কিন্তু কেউ সেই তলবে সাড়া না দিলে তাঁকে হাজির করা বা নথি দিতে বাধ্য করার পূর্ণাঙ্গ আইনি ভিত্তি কমিটির নেই। তলব অমান্য করলে কী ব্যবস্থা নেওয়া যাবে, সে বিষয়েও পূর্ণাঙ্গ কোনো বিধান নেই। সংশ্লিষ্ট ব্যক্তিরা বলছেন, এ সীমাবদ্ধতার কারণে সংসদীয় কমিটির তদন্ত ও জবাবদিহি নিশ্চিত করার ক্ষমতা খর্ব হচ্ছে। অতীতে একাধিক ঘটনায় কমিটির তলব উপেক্ষা করার নজিরও রয়েছে।

তলবেও হাজির হননি দুদকের কর্মকর্তারা সংশ্লিষ্ট ব্যক্তিরা বলছেন, নবম জাতীয় সংসদে বিষয়টি গুরুত্বের সঙ্গে আলোচনায় আসে। ২০০৯ সালে জাতীয় সংসদের সরকারি প্রতিষ্ঠান–সম্পর্কিত কমিটি দুর্নীতি দমন কমিশনের (দুদক) সাবেক চেয়ারম্যান হাসান মশহুদ চৌধুরী, দুই কমিশনার ও এক সাবেক সচিবকে তলব করেছিল। কিন্তু তাঁরা কেউই কমিটির বৈঠকে হাজির হননি। সে সময় দুদকের পক্ষ থেকে বলা হয়েছিল, স্বাধীন প্রতিষ্ঠান হিসেবে দুদককে তলব করার ক্ষমতা সংসদীয় কমিটির নেই। এ কারণে বৈঠকে না যাওয়ার সিদ্ধান্ত নেয় কমিশন। দুদকের মতো একটি স্বাধীন প্রতিষ্ঠানকে সংসদীয় কমিটি তলব করতে পারে কি না, তা নিয়েও তখন প্রশ্ন উঠেছিল। একই বছর সংসদীয় একটি তদন্ত কমিটি সাবেক স্পিকার জমির উদ্দিন সরকার, সাবেক ডেপুটি স্পিকার আখতার হামিদ সিদ্দিকী ও সাবেক চিফ হুইপ খোন্দকার দেলোয়ার হোসেনকে তলব করেছিল। তাঁরাও কমিটির সামনে হাজির হননি। খোন্দকার দেলোয়ার হোসেন ওই কমিটির বৈধতা ও এখতিয়ার নিয়ে প্রশ্ন তুলেছিলেন।

খসড়া তৈরি হলেও আইন হয়নি সংশ্লিষ্ট সূত্রে জানা গেছে, এসব ঘটনার পরিপ্রেক্ষিতে ২০১১ সালে আওয়ামী লীগ সরকারের আমলে ‘জাতীয় সংসদের স্থায়ী কমিটির (সাক্ষ্য গ্রহণ ও দলিলপত্র দাখিল) আইন’ নামে একটি খসড়া তৈরি করা হয়েছিল। তবে শেষ পর্যন্ত সেটি আইনে পরিণত হয়নি। এরপর এ বিষয়ে আর কোনো উদ্যোগও নেওয়া হয়নি। ওই খসড়ায় সংসদীয় কমিটিকে অনুসন্ধান ও তদন্তের কাজে দেওয়ানি আদালতের ক্ষমতা দেওয়ার প্রস্তাব ছিল। কোনো সাক্ষী কমিটিকে অসহযোগিতা করলে আর্থিক জরিমানা এবং তাঁর বিরুদ্ধে শাস্তিমূলক ব্যবস্থা নিতে সংশ্লিষ্ট কর্তৃপক্ষকে সুপারিশ করার বিধান রাখারও প্রস্তাব করা হয়েছিল। সূত্রটি আরও জানিয়েছে, কমিটির সুপারিশ বাস্তবায়নের জন্য সংশ্লিষ্ট মন্ত্রণালয় বা সংস্থাকে নির্দিষ্ট সময়সীমা বেঁধে দেওয়ার প্রস্তাব ছিল খসড়ায়। বর্তমানে সংসদীয় কমিটি বিভিন্ন বিষয়ে সংশ্লিষ্ট মন্ত্রণালয়কে সুপারিশ করতে পারে। তবে সেসব সুপারিশ বাস্তবায়নে নির্দিষ্ট সময়সীমা বা আইনি বাধ্যবাধকতা নেই।

কমিটির কার্যকারিতা বাড়াতে আইন প্রয়োজন সংসদ বিষয়ে গবেষক ও চট্টগ্রাম বিশ্ববিদ্যালয়ের সুপারনিউমারারি অধ্যাপক নিজাম উদ্দিন আহমদ প্রথম আলোকে বলেন, নবম জাতীয় সংসদে সুরঞ্জিত সেনগুপ্ত এ বিষয়ে একটি উদ্যোগ নিয়েছিলেন। কিন্তু মন্ত্রিসভায় সংশ্লিষ্ট খসড়াটি নাকচ করা হয়। এরপর কোনো সরকারই এ বিষয়ে উদ্যোগ নেয়নি। নিজাম উদ্দিন আহমদ বলেন, এ আইন অবশ্যই হওয়া উচিত। সংসদীয় কমিটি যদি কোনো সাক্ষীকে হাজির হতে বাধ্য করতে না পারে, তাহলে কমিটির কার্যকর ক্ষমতা থাকে না।', 'রিয়াদুল করিম', 'https://media.prothomalo.com/prothomalo-bangla/2021-02/841c6205-b2cf-4d4a-9e3b-1bff4962f550/0b61a7df-7db9-43bb-a8c9-cce3f71cc3ea.jpg', 'https://www.prothomalo.com/politics/5zyn4wzhnp', '2026-10-23 15:29:02'),
(2, 'পিএসসির সদস্যদের চায়ের দাওয়াত দিয়ে পদত্যাগে বাধ্য করা হচ্ছে: আযাদ', 'politics/hx5m08j6ma', 'সরকার ও ফ্যাসিবাদী শক্তি মিলে নতুন পরিস্থিতি সৃষ্টির ষড়যন্ত্র করছে বলে অভিযোগ করেছেন ১১–দলীয় ঐক্যের সমন্বয়ক হামিদুর রহমান আযাদ।', 'পিএসসির সদস্যদের চায়ের দাওয়াত দিয়ে পদত্যাগে বাধ্য করা হচ্ছে বলে অভিযোগ করেছেন ১১–দলীয় ঐক্যের সমন্বয়ক ও বাংলাদেশ জামায়াতে ইসলামীর সহকারী সেক্রেটারি জেনারেল হামিদুর রহমান আযাদ। মেধার ভিত্তিতে নিয়োগের জন্য, বৈষম্য নির্মূলের জন্যই এ দেশের সন্তানেরা আন্দোলনে নেমেছিল উল্লেখ করে হামিদুর রহমান আযাদ বলেন, সরকার ও ফ্যাসিবাদী শক্তি মিলে নতুন পরিস্থিতি সৃষ্টির ষড়যন্ত্র করছে। জামায়াতের এই নেতা বলেছেন, কোটা সংস্কার আন্দোলন ও জুলাই আন্দোলন স্মরণ করিয়ে দেয়, অতীতের ফ্যাসিবাদী আমলে মেধা হত্যা করা হয়েছে। একই পথে হাঁটছে নব্য ফ্যাসিবাদ। সে কারণে মেধার ভিত্তিতে পদোন্নতি হচ্ছে না, নিয়োগ হচ্ছে না, বদলি হচ্ছে না। দলীয় বিবেচনায় সবকিছু করা হচ্ছে। আজ শুক্রবার দুপুরে রাজধানীর মিন্টো রোডে বিরোধীদলীয় নেতার সরকারি বাসভবনে এক ব্রিফিংয়ে হামিদুর রহমান আযাদ এসব কথা বলেন। এর আগে একই জায়গায় জামায়াতে ইসলামী নেতৃত্বাধীন ১১–দলীয় ঐক্যের লিয়াজোঁ কমিটির বৈঠক অনুষ্ঠিত হয়।

হামিদুর রহমান আযাদ বলেন, জুলাই আন্দোলনে হত্যাকাণ্ড, আহত, পঙ্গুত্ববরণসহ নানা ধরনের মানবতাবিরোধী অপরাধের দৃশ্যমান বিচার এখনো হয়নি। কিছু রায় হয়েছে, কার্যকর হয়নি। বর্তমান সরকার ফ্যাসিবাদী শক্তির সঙ্গে আঁতাত করে আবার নতুন পরিস্থিতি সৃষ্টি করার জন্য ষড়যন্ত্র করছে। বৈঠক শেষে ব্রিফিংয়ে আওয়ামী লীগের সঙ্গে বিএনপির সমঝোতার অভিযোগ তুলে সাবেক সংসদ সদস্য হামিদুর রহমান আযাদ বলেন, বিএনপির বিভিন্ন নেতা সংসদ নির্বাচনে তাঁদের দলের ভোটের ৩০ শতাংশ আওয়ামী লীগের ভোট বলে দাবি করেছেন। আওয়ামী লীগের পক্ষ থেকেও এ বিষয়ে কথা বলা হয়েছে। শেখ হাসিনা ও শামীম ওসমানের ফাঁস হওয়া অডিও কথোপকথনেও এ-সংক্রান্ত তথ্য রয়েছে। থলের বিড়াল বেরিয়ে আসার ভয়ে বিএনপি এসব বক্তব্যের প্রতিবাদ করছে না বলে দাবি করেন তিনি।

জামায়াতে ইসলামীর নেতৃত্বাধীন ১১–দলীয় ঐক্যের সঙ্গে আওয়ামী লীগের আঁতাতের বিষয়ে সরকারের অভিযোগকে ভুয়া ও অসত্য বলে দাবি করে হামিদুর রহমান আযাদ বলেন, সরকারের কাছে এ বিষয়ে গোয়েন্দা তথ্য থাকলে তা প্রকাশ করা হোক। তাঁর দাবি, সরকার গোয়েন্দা সংস্থার তৈরি করা রিপোর্টের ভিত্তিতে রাজনৈতিক বক্তব্য দিচ্ছে। তিনি বলেন, ‘এই রিপোর্ট যে আপনারা বানিয়ে দিয়েছেন—এটা বুঝতে আমাদের আর দেরি নাই।’ আইনশৃঙ্খলা পরিস্থিতির উন্নতি হয়েছে—স্বরাষ্ট্রমন্ত্রীর এমন বক্তব্যের সমালোচনা করে হামিদুর রহমান আযাদ বলেন, দেশে খুন, মাদক, ঘুষ, কালোবাজারি ও দুর্নীতি বেড়েছে। তাঁর দাবি, গত ছয়–সাত মাসে দলীয় কোন্দলে ক্ষমতাসীন দলের ৪০ জন কর্মী নিজেদের দলের লোকজনের হাতে খুন হয়েছেন। এ পরিস্থিতি নিয়ন্ত্রণে সরকারকে কার্যকর পদক্ষেপ নেওয়ার আহ্বান জানান তিনি।

মাগুরার উপনির্বাচনের কথা স্মরণে রাখুন ঠাকুরগাঁওয়ে ১১–দলীয় ঐক্যের প্রার্থী দেলোয়ার হোসেনের পক্ষে জনসমর্থন তৈরি হয়েছে দাবি করে হামিদুর রহমান আযাদ বলেন, সেখানে ১২ ফেব্রুয়ারির নির্বাচনের মতো কারচুপির পরিকল্পনার খবর তাঁরা পেয়েছেন। এ ধরনের কোনো চেষ্টা হলে সরকারকে পরিণতি সম্পর্কে সতর্ক করেন তিনি। আযাদ বলেন, মাগুরার নির্বাচন বাংলাদেশের নির্বাচনী ইতিহাসের একটি কালো অধ্যায়, একটি দৃষ্টান্ত। এখান থেকে সরকার পতনের আন্দোলন চূড়ান্ত রূপ নিয়েছিল। সরকার যদি ক্ষমতায় থাকতে না চায়, তাহলে তারা জোর করে ক্ষমতায় রাখতে পারবেন না। বিরোধী দল ঠাকুরগাঁওয়ে মাগুরার উপনির্বাচনের পুনরাবৃত্তি দেখতে চায় না উল্লেখ করে তিনি বলেন, সরকারের যদি অশুভ পরিকল্পনা থাকে, তারা যেন সরে আসে। নির্বাচনে কারচুপির চেষ্টা হলে তা ঠেকাতে ১১ দল ঐক্যবদ্ধভাবে মাঠে নামবে।

খুলনামুখী লংমার্চ গোপালগঞ্জ হয়ে যাওয়ার ক্ষেত্রে কোনো ধরনের হামলার আশঙ্কা আছে কি না জানতে চাইলে হামিদুর রহমান আযাদ বলেন, ‘আমরা সরকারের জিম্মাদারির কথা এখানে স্মরণ করিয়েছি। প্রতিটি নাগরিকের নিরাপত্তার দায়িত্ব সরকারের, রাষ্ট্রের। দেশে একটা সরকার আছে, এটা দেখার দায়িত্ব তাদের।’ ঢাকা উত্তর সিটি করপোরেশনে ট্রাফিক সিগন্যাল আধুনিকায়নের কাজ আওয়ামী লীগ–সংশ্লিষ্ট ব্যক্তিদের হাতে দেওয়ার বিষয়ে জানতে চাইলে আযাদ বলেন, ‘ভাগ–বাঁটোয়ারার জায়গায় ওনারা এক। যেহেতু ভোটের সুবিধা নিয়েছেন, তাহলে উন্নয়নের সুবিধা, ব্যবসার সুবিধা দেবেন, এটাই স্বাভাবিক।’

১১ দলের ঐক্য অটুট থাকার দাবি ব্রিফিংয়ে কওমি ঘরানার সাত ইসলামি দলের ঐক্য প্রক্রিয়ার বিষয়ে জামায়াতের প্রতিক্রিয়া জানতে চান এক সাংবাদিক। জবাবে আযাদ বলেন, জুলাই সনদ বাস্তবায়ন ও গণভোটের রায় কার্যকর না হওয়া পর্যন্ত তাঁদের ঐক্য অটুট থাকবে। ব্রিফিংয়ে জানানো হয়, ৩১ অক্টোবর সকাল সাতটায় জাতীয় মসজিদ বায়তুল মোকাররমের দক্ষিণ গেট থেকে ঢাকা-খুলনা ও ঢাকা-কুষ্টিয়ামুখী লংমার্চ কর্মসূচির উদ্বোধন হবে। পরে মাদারীপুর-শরীয়তপুরের মাঝামাঝি নাওডোবা, বাগেরহাটের কাটাখালী, খুলনার বাবরী চত্বর ও স্বাধীনতা চত্বর, যশোরের মুড়লি মোড় এবং ঝিনাইদহ-চুয়াডাঙ্গা বাসস্ট্যান্ডে পথসভা হবে। কুষ্টিয়া জেলা হাইস্কুল মাঠে সমাপনী সমাবেশের মধ্য দিয়ে কর্মসূচি শেষ হবে। সংবাদ সম্মেলনে আরও উপস্থিত ছিলেন জামায়াতে ইসলামীর সহকারী সেক্রেটারি জেনারেল মুয়াযযম হোসাইন হেলাল, জাতীয় নাগরিক পার্টির (এনসিপি) মুখ্য সমন্বয়ক নাসীরুদ্দীন পাটওয়ারী, বাংলাদেশ খেলাফত মজলিসের যুগ্ম মহাসচিব আতাউল্লাহ আমিন, লিবারেল ডেমোক্রেটিক পার্টির ভারপ্রাপ্ত মহাসচিব বিল্লাল হোসেন মিয়াজী, বাংলাদেশ লেবার পার্টির চেয়ারম্যান মোস্তাফিজুর রহমান ইরান প্রমুখ।', 'নিজস্ব প্রতিবেদক', 'https://media.prothomalo.com/prothomalo-bangla/2026-10-23/5rcgn47r/3c768731-9e1f-47ec-9001-56a4f2dd0391.jfif', 'https://www.prothomalo.com/politics/hx5m08j6ma', '2026-10-23 15:28:15'),
(2, 'বিসিএসে গেজেটবঞ্চিতদের অনশনে নিষিদ্ধ ছাত্রলীগের চার নেতা, পুলিশে দিল ছাত্রদল', 'bangladesh/capital/d3qevefxdv', 'ছাত্রদল নেতা নাসির উদ্দিন শাওন বলেন, ‘আমরা চারজন নিষিদ্ধ ছাত্রলীগের নেতা–কর্মীকে অনশন থেকে পেয়েছি। তাঁরা বিভিন্ন পদে পোস্টেড ছিলেন। পরে পুলিশ এসে তাঁদের তুলে নিয়ে গেছে।’', 'ঢাকা বিশ্ববিদ্যালয়ের রাজু ভাস্কর্যের সামনে ৪৫তম বিসিএসে গেজেটবঞ্চিতদের অনশন কর্মসূচি থেকে নিষিদ্ধ সংগঠন বাংলাদেশ ছাত্রলীগের চার নেতাকে থানায় নিয়ে যাওয়ার কথা জানিয়েছে পুলিশ। গতকাল বৃহস্পতিবার দিবাগত রাত সোয়া ১২টার দিকে এ ঘটনা ঘটে। পুলিশ বলেছে, আটক ব্যক্তিরা নিজেদের ছাত্রলীগের পদে থাকার বিষয়টি ঘটনাস্থলে স্বীকার করেছেন।

প্রত্যক্ষদর্শী ও পুলিশ বলছে, গত বুধবার বিকেল থেকে ৪৫তম বিসিএসে গেজেটবঞ্চিতরা রাজু ভাস্কর্যে অনশন কর্মসূচি শুরু করেন। তাঁদের মধ্যে নিষিদ্ধ ছাত্রলীগের নেতা–কর্মী রয়েছেন—এমন তথ্য পেয়ে ছাত্রদলের ঢাকা বিশ্ববিদ্যালয়ের জ্যেষ্ঠ যুগ্ম সাধারণ সম্পাদক নাসির উদ্দিন শাওনসহ কয়েকজন নেতা–কর্মী সেখানে যান। ঢাকা বিশ্ববিদ্যালয় প্রক্টরিয়াল দলের উপস্থিতিতে তাঁদের পুলিশের কাছে সোপর্দ করা হয়। আটক ব্যক্তিরা হলেন ঢাকা বিশ্ববিদ্যালয়ের শেখ মুজিবুর রহমান হলের ছাত্রলীগের সাবেক সহসম্পাদক ফেরদৌস খান, অমর একুশে হল শাখা ছাত্রলীগের সাবেক সহসভাপতি একরাম গাজী হৃদয়, বাংলাদেশ কৃষি বিশ্ববিদ্যালয়ের (বাকৃবি) আশরাফুল হক হল শাখা ছাত্রলীগের সাবেক উপসাধারণ সম্পাদক মো. হাবিবুল ইসলাম, বাকৃবির একই হলের ছাত্রলীগের সাবেক শিক্ষা ও পাঠচক্র সম্পাদক মনিরুজ্জামান মনির।

ছাত্রদল নেতা নাসির উদ্দিন শাওন বলেন, ‘আমরা চারজন নিষিদ্ধ ছাত্রলীগের নেতা–কর্মীকে অনশন থেকে পেয়েছি। তাঁরা বিভিন্ন পদে পোস্টেড ছিলেন। পরে পুলিশ এসে তাঁদের তুলে নিয়ে গেছে।’ নীলক্ষেত পুলিশ ফাঁড়ির ইনচার্জ উপপরিদর্শক কামাল উদ্দিন বলেন, ঢাবির প্রক্টরিয়াল টিমের মাধ্যমে পুলিশ ঘটনাস্থলে যায়। চারজন নিষিদ্ধ ছাত্রলীগের পদধারী নেতা নিশ্চিত হওয়ার পর জিজ্ঞাসাবাদের জন্য তাঁদের শাহবাগ থানায় নেওয়া হয়েছে। যাচাই-বাছাই শেষে তাঁদের বিরুদ্ধে আইনানুগ ব্যবস্থা নেওয়া হবে।', 'প্রতিবেদক', 'https://media.prothomalo.com/prothomalo-bangla/2026-10-23/x6t5my85/police-.jpg', 'https://www.prothomalo.com/bangladesh/capital/d3qevefxdv', '2026-10-23 13:24:02'),
(2, 'হেফাজতের ‘মুরব্বিয়ানায়’ কওমি ঘরানার সাত দলের জোট', 'politics/zer6kgtnez', NULL, 'স্থানীয় সরকার নির্বাচনে জোটবদ্ধ হয়ে অংশ নেওয়া যায় কি না, তা নিয়ে আলোচনা করেছে কওমি ঘরানার সাতটি ইসলামি রাজনৈতিক দল। তবে এ বিষয়ে এখনো কোনো সিদ্ধান্ত হয়নি। আগামী ৫ ডিসেম্বর পরবর্তী বৈঠকে বিষয়টি নিয়ে আরও আলোচনা হবে। এর মধ্যে অনানুষ্ঠানিক আলোচনাও চলবে। আজ বৃহস্পতিবার রাজধানীর খিলগাঁওয়ের আল-জামিয়াতুল ইসলামিয়া মাখজানুল উলুম (ঢাকা) মাদ্রাসায় সাত দলের লিয়াজোঁ কমিটির বৈঠকে এ আলোচনা হয়। সাত দলের এই ঐক্য প্রক্রিয়ায় রয়েছে ইসলামী আন্দোলন বাংলাদেশ, জমিয়তে উলামায়ে ইসলাম বাংলাদেশ, খেলাফত মজলিস, বাংলাদেশ খেলাফত মজলিস, বাংলাদেশ খেলাফত আন্দোলন, ইসলামী ঐক্যজোট ও বাংলাদেশ নেজামে ইসলাম পার্টি। বৈঠকে সভাপতিত্ব করেন হেফাজতে ইসলাম বাংলাদেশের মহাসচিব মাওলানা সাজিদুর রহমান। সকাল সাড়ে ১০টায় শুরু হয়ে বেলা একটা পর্যন্ত চলা বৈঠকে সাত দলের লিয়াজোঁ কমিটির সদস্যরা উপস্থিত ছিলেন। হেফাজতের সাংগঠনিক সম্পাদক মুফতি বশির উল্লাহ, নারায়ণগঞ্জ জেলার সভাপতি মাওলানা আবদুল আউয়াল ও হেফাজত আমিরের ছেলে মুফতি আইয়ুব বাবুনগরীও বৈঠকে ছিলেন।

বৈঠক সূত্র জানায়, বৈঠকে সাতদলীয় ঐক্যের কাঠামো, অভিন্ন ব্যানারে কার্যক্রম পরিচালনা, রাজনৈতিক জোটের সঙ্গে সম্পর্ক এবং পরবর্তী কর্মপন্থা নিয়ে আলোচনা হয়। আগামী ৫ ডিসেম্বর পরবর্তী বৈঠকে ঐক্যের নীতিমালা ও কর্মপদ্ধতি নিয়ে আরও আলোচনা হবে। বৈঠকে অংশ নেওয়া নেতারা জানান, জামায়াতে ইসলামী এককভাবে স্থানীয় সরকার নির্বাচনে অংশ নিতে চায়। এ পরিস্থিতিতে জামায়াত নেতৃত্বাধীন ১১–দলীয় নির্বাচনী ঐক্যে থাকা দলগুলো কীভাবে স্থানীয় নির্বাচনে অংশ নেবে, তা নিয়ে আলোচনা শুরু হয়েছে। কওমি ঘরানার সাত দলের ঐক্যপ্রক্রিয়া এগোতে থাকায় ওই ঐক্যে থাকা দলগুলো নতুন এই ব্যানারে নির্বাচনে অংশ নিতে পারে কি না, তা নিয়েও কথা হয়েছে। বাংলাদেশ নেজামে ইসলাম পার্টির মহাসচিব মুসা বিন ইযহার প্রথম আলোকে বলেন, স্থানীয় সরকার নির্বাচনে সাত দল একসঙ্গে অংশ নিতে পারে কি না, সে বিষয়ে বৈঠকে আলোচনা হয়েছে। এ আলোচনাকে তাঁরা ইতিবাচকভাবে দেখছেন এবং স্থানীয় নির্বাচনে সাত দল জোটবদ্ধ হয়ে নির্বাচন করলে তাঁরা এতে থাকবেন। সাত দল স্থানীয় সরকার নির্বাচনে জোটবদ্ধ হয়ে অংশ নিতে পারে কি না, সে বিষয়ে প্রাথমিক আলোচনা হয়েছে বলে জানিয়েছেন ইসলামী আন্দোলন বাংলাদেশের মহাসচিব গাজী আতাউর রহমানও। তিনি প্রথম আলোকে বলেন, এ বিষয়ে আগামী ৫ ডিসেম্বরের বৈঠকে আরও আলোচনা হবে। এর মাঝে অনানুষ্ঠানিক আলোচনাও হতে পারে।

বৈঠকে অংশ নেওয়া নেতারা জানান, সাত ইসলামি দল ‘সমমনা ইসলামী দল’ ব্যানারে একসঙ্গে কাজ করবে। তবে দলগুলো নিজেদের স্বতন্ত্র পরিচয় বজায় রাখবে। হেফাজতে ইসলামের সাংগঠনিক সম্পাদক মুফতি বশির উল্লাহ প্রথম আলোকে বলেন, ‘সমমনা ইসলামী দল’ ব্যানারে দলগুলো ঐক্যবদ্ধ থাকার সিদ্ধান্ত হয়েছে। কিসের ভিত্তিতে ঐক্য হবে, তা নিয়েও আলোচনা হয়েছে। তবে ঐক্যের কর্মপদ্ধতি এখনো ঠিক হয়নি। এ জন্য ৫ ডিসেম্বর আবার বৈঠক ডাকা হয়েছে।

বৈঠক অংশ নেওয়া নেতারা জানান, ‘সমমনা ইসলামী দল’ নামে অভিন্ন ব্যানারে একসঙ্গে কার্যক্রম চালানোর বিষয়ে নীতিগত সিদ্ধান্ত নিলেও অন্য রাজনৈতিক জোটে থাকা দলগুলোকে সেই জোট ছাড়তে হবে কি না, তা নিয়ে মতৈক্য হয়নি। বৈঠক সূত্র জানায়, অন্য রাজনৈতিক জোটে থাকা নিয়ে শর্ত আরোপের বিষয়ে আপত্তি জানিয়েছে বাংলাদেশ খেলাফত মজলিস ও বাংলাদেশ নেজামে ইসলাম পার্টি। তাদের বক্তব্য, এ বিষয়ে আরও আলোচনা প্রয়োজন। বাংলাদেশ খেলাফত মজলিসের যুগ্ম মহাসচিব আতাউল্লাহ আমিন প্রথম আলোকে বলেন, সাতদলীয় ঐক্যে থাকা কোনো দল অন্য কোনো জোটে থাকতে পারবে না মর্মে বৈঠকে আলোচনা হয়েছে। দলগুলোর মধ্যে যারা অন্য জোটে আছে, তাদের ওই জোট ছেড়ে আসতে অনুরোধ করেছে হেফাজতে ইসলাম। এ বিষয়ে চূড়ান্ত সিদ্ধান্ত হয়নি। জামায়াত নেতৃত্বাধীন ১১–দলীয় ঐক্য থেকে কওমি ঘরানার দলগুলোকে বের হয়ে আসতে হেফাজতে ইসলামের নেতারা অনুরোধ করেছেন বলে জানিয়েছেন বাংলাদেশ নেজামে ইসলাম পার্টির মহাসচিব মুসা বিন ইযহারও। তিনি প্রথম আলোকে বলেন, সমমনা ইসলামী দলের ব্যানারে তাঁরা থাকছেন। তবে তাঁরা জুলাই সনদ ও গণভোটের রায় বাস্তবায়নে ১১–দলীয় ঐক্যের আন্দোলনেও শরিক থাকবেন।

হেফাজতে ইসলামের সাংগঠনিক সম্পাদক মুফতি বশির উল্লাহ প্রথম আলোকে বলেন, সাত দল অন্য কোনো জোটে থাকতে পারবে না—এমন সিদ্ধান্ত হয়েছে। তবে কোনো কোনো দল এ বিষয়ে নিজ নিজ দলীয় ফোরামে আলোচনা করে পরে জানাবে বলে জানিয়েছে। বৈঠক সূত্র জানায়, জামায়াতে ইসলামী ও বিএনপির সঙ্গে দলগুলোর সম্পর্ক নিয়েও আলোচনা হয়েছে। জমিয়তে উলামায়ে ইসলাম বাংলাদেশের মহাসচিব এ সময় বলেছেন, সাত দলের এই ঐক্য হলে তাঁরা বিএনপির জোট থেকে বেরিয়ে যাবেন। বৈঠকে অংশ নেওয়া নেতারা আরও জানান, রাজনৈতিক বিষয়ে সিদ্ধান্ত নেওয়ার ক্ষেত্রে দলগুলোর লিয়াজোঁ কমিটিতে আলোচনা করে ঐকমত্যে পৌঁছানোর ওপর গুরুত্ব দিয়েছেন হেফাজতে ইসলামের মহাসচিব মাওলানা সাজিদুর রহমান। অন্য রাজনৈতিক জোটে থাকা নিয়ে শর্ত শিথিল করা যায় কি না, সে বিষয়েও আরও আলোচনা হতে পারে বলে তিনি জানিয়েছেন।

বৈঠক সূত্র জানায়, বাংলাদেশ খেলাফত মজলিসের এক নেতা তাঁদের দলের আমির মাওলানা মামুনুল হককে নিয়ে নেতিবাচক বক্তব্য, সামাজিক যোগাযোগমাধ্যমে প্রচারণা ও বই প্রকাশের বিষয়টি তুলে ধরেন। এ সময় হেফাজতের মহাসচিব এ ধরনের ঘটনা ও কাজের নিন্দা জানান। এ ছাড়া হেফাজত নেতা হারুন আজিজীর সামাজিক যোগাযোগমাধ্যমে বাংলাদেশ খেলাফত মজলিসের নেতাদের নিয়ে আপত্তিকর স্ট্যাটাসের বিষয়টি বৈঠকে তোলা হয়। বিষয়টি খতিয়ে দেখার দায়িত্ব দেওয়া হয় হেফাজত আমিরের ছেলে মুফতি আইয়ুব বাবুনগরীকে। বৈঠকে জুলাই জাতীয় সনদ বাস্তবায়ন এবং সাম্প্রতিক দুর্গাপূজার সময় কয়েকজন রাজনৈতিক নেতার বক্তব্য নিয়েও আলোচনা–সমালোচনা হয়।', 'নিজস্ব প্রতিবেদক', NULL, 'https://www.prothomalo.com/politics/zer6kgtnez', '2026-10-22 18:54:31'),
(2, 'নিজ নাগরিকদের জীবন রক্ষায় সরকার উদ্যোগ নিতে ব্যর্থ হয়েছে: সিপিবি', 'bangladesh/capital/8p2g6brdzy', 'সৌদিতে দুই বাংলাদেশির মৃত্যুদণ্ড কার্যকর', 'সৌদি আরবের মক্কায় দুই বাংলাদেশি নাগরিকের মৃত্যুদণ্ড কার্যকরের ঘটনায় গভীর উদ্বেগ জানিয়েছে বাংলাদেশের কমিউনিস্ট পার্টি (সিপিবি)। দলটি অভিযোগ করে বলেছে, নিজ দেশের নাগরিকদের জীবন রক্ষায় সরকার উদ্যোগ নিতে ব্যর্থ হয়েছে। এমনকি মৃত্যুদণ্ড কার্যকরের পর তাঁদের নিয়ে অবমাননাকর মন্তব্যও করা হয়েছে। এর প্রতিবাদ জানায় সিপিবি। আজ বৃহস্পতিবার বেলা সাড়ে ১১টার দিকে রাজধানীর জাতীয় প্রেসক্লাবের সামনে আয়োজিত এক বিক্ষোভ সমাবেশে সিপিবির নেতারা এই প্রতিবাদ জানান। একই সঙ্গে দলটির নেতারা বিদেশে প্রবাসী মৃত্যুর প্রতিটি ঘটনার পূর্ণাঙ্গ তদন্তের দাবি জানিয়েছেন। বিদেশে কারাবন্দী বাংলাদেশিদের মুক্তির ব্যবস্থা নিতে সরকারের প্রতি আহ্বান জানিয়েছেন।

সমাবেশে সিপিবির সাধারণ সম্পাদক আবদুল্লাহ ক্বাফী রতন বলেন, মক্কায় দুই বাংলাদেশির মৃত্যুদণ্ড কার্যকরের ঘটনা গভীর উদ্বেগজনক। তাঁদের বিরুদ্ধে আনা অভিযোগ, বিচারপ্রক্রিয়া ও রায়ের বিস্তারিত তথ্য সরকারের কাছে থাকা দরকার ছিল। অথচ পররাষ্ট্র মন্ত্রণালয় জানিয়েছে, এসব বিষয়ে তারা কিছুই জানত না। বিদেশে বাংলাদেশের নাগরিকদের বিচার, কারাবাস ও মৃত্যুর মতো গুরুতর ঘটনায় সরকারের কার্যকর ভূমিকা রাখা দরকার ছিল বলে মন্তব্য করেন আবদুল্লাহ ক্বাফী। তিনি বলেন, কিন্তু সরকার নিজ নাগরিকদের জীবন রক্ষায় উদ্যোগ নিতে ব্যর্থ হয়েছে। মৃত্যুর পর তাঁদের নিয়ে অবমাননাকর মন্তব্য করা হয়েছে। প্রবাসী শ্রমিকদের পাঠানো রেমিট্যান্সে দেশের অর্থনীতি সচল থাকে বলে উল্লেখ করেন সিপিবির সাধারণ সম্পাদক। তিনি বলেন, অথচ তাঁদের জীবন, নিরাপত্তা ও মর্যাদা রক্ষায় সরকারের কার্যকর উদ্যোগ নেই। রেমিট্যান্সের অর্থে মন্ত্রী-এমপি ও আমলাদের বিলাসীজীবন নিশ্চিত হলেও প্রবাসী শ্রমিকদের নিরাপত্তা উপেক্ষিত থাকছে।

বিদেশে কর্মরত বাংলাদেশিদের অধিকার রক্ষায় কার্যকর কূটনৈতিক উদ্যোগ, আইনি সহায়তা ও জবাবদিহি নিশ্চিত করার দাবি জানান আবদুল্লাহ ক্বাফী। সমাবেশের সভাপতিত্ব করেন সিপিবির প্রেসিডিয়াম সদস্য রাগীব আহসান মুন্না। বিদেশে আটক বা কারাবন্দী বাংলাদেশিদের তালিকা তৈরি করতে সরকারের কাছে দাবি জানান তিনি। রাষ্ট্রীয় খরচে প্রবাসীদের আইনি সহায়তা দেওয়ার পাশাপাশি নিয়মিত কারাগার পরিদর্শন ও বন্দীদের পরিবারের সঙ্গে যোগাযোগের কার্যকর ব্যবস্থা গড়ে তোলার দাবিও জানান তিনি।

রাগীব আহসান বলেন, সৌদি আরবসহ বিভিন্ন দেশে কারাবন্দী বাংলাদেশিদের মুক্ত করতে সরকারকে জরুরি কূটনৈতিক উদ্যোগ নিতে হবে। সমাবেশে আরও বক্তব্য দেন সিপিবির প্রেসিডিয়াম সদস্য জলি তালুকদার, দলের কেন্দ্রীয় কমিটির সদস্য অধ্যাপক ফজলুর রহমান। কর্মসূচি পরিচালনা করেন সিপিবির ঢাকা মহানগর দক্ষিণ জেলা কমিটির সাধারণ সম্পাদক মঞ্জুর মঈন। সমাবেশ শেষে একটি বিক্ষোভ মিছিল নগরীর গুরুত্বপূর্ণ সড়ক প্রদক্ষিণ করে।', 'নিজস্ব প্রতিবেদক', 'https://media.prothomalo.com/prothomalo-bangla/2026-10-22/l9r8i8n5/CPB.jpeg', 'https://www.prothomalo.com/bangladesh/capital/8p2g6brdzy', '2026-10-22 16:05:20'),
(2, 'নারায়ণগঞ্জে রাতে বাড়ি ফেরার পথে যুবদল নেতাকে কুপিয়ে হত্যার অভিযোগ', 'bangladesh/district/4ugtzguetp', 'জহির রাতে ফার্মেসি বন্ধ করে বাসায় ফিরছিলেন। পথে ১৫-২০ জনের একটি দল পথ আটকে তাঁকে ধারালো অস্ত্র দিয়ে এলোপাতাড়ি কুপিয়ে জখম করে ফেলে যায়।', 'নারায়ণগঞ্জের সোনারগাঁয়ে এক যুবদল নেতাকে কুপিয়ে হত্যার অভিযোগ পাওয়া গেছে। গতকাল বুধবার রাত ১০টার দিকে উপজেলার চরকিশোরগঞ্জ এলাকায় নিজের ফার্মেসি বন্ধ করে বাসায় ফেরার পথে তিনি হামলার শিকার হন। পরে হাসপাতালে নেওয়া হলে সেখানে তাঁর মৃত্যু হয়। নিহত জহির ফকির (৪৫) আড়াইহাজার উপজেলার কালাপাহাড়িয়া ইউনিয়ন যুবদলের সভাপতি ছিলেন। তিনি মুন্সিগঞ্জে বসবাস করতেন এবং সোনারগাঁয়ের চরকিশোরগঞ্জ এলাকায় একটি ফার্মেসি চালাতেন। চরকিশোরগঞ্জ এলাকাটি মুন্সিগঞ্জের কাছাকাছি।

স্থানীয় ও পুলিশ সূত্র জানায়, প্রতিদিনের মতো বুধবার রাতেও জহির ফার্মেসি বন্ধ করে বাসায় ফিরছিলেন। পথে ১৫-২০ জনের একটি দল পথ আটকে তাঁকে ধারালো অস্ত্র দিয়ে এলোপাতাড়ি কুপিয়ে জখম করে ফেলে যায়। স্থানীয় লোকজন আহত অবস্থায় তাঁকে মুন্সিগঞ্জ জেনারেল হাসপাতালে নিয়ে গেলে সেখানে তাঁর মৃত্যু হয়। জহিরের ভাগনে ইসমাইল হোসেন ও বিল্লাল হোসেন অভিযোগ করেন, আসন্ন কালাপাহাড়িয়া ইউনিয়ন পরিষদ নির্বাচনে চেয়ারম্যান পদে প্রার্থিতা নিয়ে জহিরের সঙ্গে উপজেলা ছাত্রদলের সাবেক সদস্যসচিব মোবারক হোসাইনের দীর্ঘদিন ধরে বিরোধ চলছিল। এর আগেও মোবারক তাঁর লোকজন নিয়ে কয়েকবার জহিরের ওপর হামলা করেছিলেন। বুধবার রাতে মোবারক ও তাঁর লোকজন আড়াইহাজার থেকে এসে পূর্বপরিকল্পিতভাবে জহিরকে কুপিয়ে হত্যা করে পালিয়ে যান বলে অভিযোগ তাঁদের। তাঁরা এ হত্যাকাণ্ডে জড়িত ব্যক্তিদের শনাক্ত করে গ্রেপ্তার এবং দৃষ্টান্তমূলক শাস্তির দাবি জানিয়েছেন।

অভিযোগের বিষয়ে মোবারক হোসাইনের বক্তব্য জানতে তাঁর মুঠোফোনে যোগাযোগের চেষ্টা করা হয়। তবে ফোনটি বন্ধ থাকায় তাঁর বক্তব্য পাওয়া যায়নি। এ বিষয়ে আড়াইহাজার উপজেলা যুবদলের সদস্যসচিব খোরশেদ আলম প্রথম আলোকে বলেন, জহির যুবদলের একজন ত্যাগী নেতা ছিলেন। তাঁর বাড়ি কালাপাহাড়িয়া এলাকায় হলেও তিনি মুন্সিগঞ্জে বসবাস করতেন। তিনি জানতে পেরেছেন, ১৫ থেকে ২০ জনের একটি দল জহিরকে হত্যা করেছে। তিনি বলেন, ‘জহির প্রায়ই আমাকে বলতেন, তাঁকে মেরে ফেলা হতে পারে। তবে কার সঙ্গে তাঁর বিরোধ ছিল, তা জানি না।’

নিহত ব্যক্তির মরদেহ ময়নাতদন্তের জন্য মুন্সিগঞ্জ জেনারেল হাসপাতালের মর্গে রাখা হয়েছে বলে জানান সোনারগাঁ থানার ভারপ্রাপ্ত কর্মকর্তা (ওসি) আবদুল বারিক। তিনি বলেন, হত্যাকাণ্ডে জড়িত ব্যক্তিদের শনাক্ত ও গ্রেপ্তারে পুলিশের একাধিক দল কাজ করছে।', 'প্রতিনিধি', 'https://media.prothomalo.com/prothomalo-bangla/2026-10-22/ht5w4pyu/NARAYANGANJMurder.JPG', 'https://www.prothomalo.com/bangladesh/district/4ugtzguetp', '2026-10-22 13:57:17'),
(2, 'ইশরাককে পুনর্বহাল করা না হলে জুলাই শহীদ পরিবারের কিংবা আহত ব্যক্তিদের কাউকে প্রতিমন্ত্রী করার দাবি', 'bangladesh/71f4o6lyeq', 'তাঁকে পুনর্বহাল করা সম্ভব না হলে শহীদ পরিবার বা আহতদের মধ্য থেকে যোগ্য কাউকে প্রতিমন্ত্রীর দায়িত্ব দেওয়ার দাবি জানিয়েছেন তাঁরা। বুধবার জাতীয় প্রেসক্লাবে এক সংবাদ সম্মেলনে এসব দাবি জানানো হয়।', 'মুক্তিযুদ্ধবিষয়ক প্রতিমন্ত্রীর পদে ইশরাক হোসেনকে পুনর্বহাল করার দাবি জানিয়েছেন জুলাই শহীদ পরিবারের সদস্য ও আহত ব্যক্তিরা। তাঁকে পুনর্বহাল করা সম্ভব না হলে শহীদ পরিবার ও আহত ব্যক্তিদের মধ্য থেকে যোগ্য কাউকে প্রতিমন্ত্রীর দায়িত্ব দেওয়ারও দাবি তাঁদের। আজ বুধবার দুপুরে জাতীয় প্রেসক্লাবে ‘জুলাই গণ-অভ্যুত্থানের শহীদ পরিবার, আহত ও যোদ্ধাবৃন্দ’র ব্যানারে আয়োজিত সংবাদ সম্মেলনে এসব দাবি জানানো হয়।

সংবাদ সম্মেলনে লিখিত বক্তব্যে বলা হয়, ইশরাক হোসেন প্রতিমন্ত্রীর দায়িত্ব নেওয়ার পর থেকে জুলাই গণ-অভ্যুত্থানের শহীদ পরিবার ও আহতদের কল্যাণ, অধিকার সংরক্ষণ এবং ন্যায্য দাবি আদায়ে সক্রিয় ভূমিকা পালন করছিলেন। তাঁর পদত্যাগের ঘটনায় শহীদ পরিবার ও আহতদের মধ্যে উদ্বেগ তৈরি হয়েছে। ইশরাক হোসেনের মাধ্যমে যে কার্যক্রম এগিয়ে যাচ্ছিল, তা যেন কোনোভাবেই স্থবির না হয়ে যায়। লিখিত বক্তব্যে ইশরাক হোসেনকে প্রতিমন্ত্রী পদে পুনর্বহালের দাবি জানানো হয়। এতে বলা হয়, সেটি সম্ভব না হলে শহীদ পরিবার বা আহতদের মধ্য থেকে যোগ্য ব্যক্তিকে প্রতিমন্ত্রীর দায়িত্ব দেওয়া হোক। এ ক্ষেত্রে জুলাই স্মৃতি ফাউন্ডেশনে দায়িত্ব পালন করা অভিজ্ঞ ব্যক্তিদের মধ্য থেকেও কাউকে মনোনীত করা যেতে পারে।

সংবাদ সম্মেলনের আয়োজকেরা জানান, সেখানে শহীদ পরিবার ও আহত ব্যক্তিদের প্রায় ৪০ জন উপস্থিত ছিলেন। তবে ১১ জনের নাম-পরিচয় জানা গেছে। সংবাদ সম্মেলনে জুলাই শহীদ রমিজ উদ্দিন আহমেদের বাবা এ কে এম রকিবুল আহমেদ বলেন, ইশরাক হোসেনের কাছ থেকে শহীদ পরিবারগুলো সহযোগিতা পেয়েছে। তাঁদের কিছু অমীমাংসিত বিষয় তাঁর কাছে তুলে ধরলে তিনি দ্রুত সমাধানের চেষ্টা করেছেন। শহীদদের কবরস্থানের জায়গা স্থায়ী করার উদ্যোগও তিনি এগিয়ে নিয়েছিলেন। ইশরাক হোসেনকে পুনরায় দায়িত্ব গ্রহণের অনুরোধ জানিয়ে রকিবুল আহমেদ বলেন, সেটি সম্ভব না হলে জুলাইয়ের আন্দোলন ও পরবর্তী সময়ে শহীদ পরিবার, আহত ব্যক্তি এবং জুলাইকে নিয়ে কাজ করেছেন—এমন শিক্ষিত, নীতিমান, নিষ্ঠাবান ও অভিজ্ঞ কাউকে প্রতিমন্ত্রী করা হোক।

আহত জুলাই যোদ্ধা ওবায়দুল হক বলেন, ইশরাক তাঁদের সঙ্গে যোগাযোগ রাখতেন এবং তাঁদের জন্য কাজ করার পরিকল্পনা ছিল। তাঁকে পুনরায় দায়িত্ব দেওয়া সম্ভব হলে শহীদ পরিবার ও আহত ব্যক্তিরা উপকৃত হবেন। তা সম্ভব না হলে শহীদ পরিবারের মধ্য থেকে যোগ্য ব্যক্তিকে প্রতিমন্ত্রী করার দাবি জানান তিনি। সংবাদ সম্মেলনে আরও উপস্থিত ছিলেন জুলাই যোদ্ধা ইমরান হোসেন, শহীদ নুর হোসেনের মা নুরন্নাহার প্রমুখ।', 'নিজস্ব প্রতিবেদক', 'https://media.prothomalo.com/prothomalo-bangla/2026-10-21/daf5kfmw/July-Joddha.jpeg', 'https://www.prothomalo.com/bangladesh/71f4o6lyeq', '2026-10-21 15:11:42'),
(2, 'চট্টগ্রামে বিএনপির নেতা-কর্মীদের যে বার্তা দিয়ে এলেন প্রধানমন্ত্রী তারেক রহমান', 'politics/g02n8935rj', 'মঙ্গলবার রাতে র‍্যাডিসন ব্লু চট্টগ্রাম বে-ভিউয়ে বিএনপির নেতা–কর্মীদের সঙ্গে সভায় প্রধান অতিথির বক্তব্য দেন দলের চেয়ারম্যান ও প্রধানমন্ত্রী তারেক রহমান।', 'আসন্ন স্থানীয় সরকার নির্বাচনে বর্তমান সরকার অতীতের ফ্যাসিস্ট সরকারের মতো কোনো হস্তক্ষেপ করবে না। তাই নেতা–কর্মীদের ঐক্যবদ্ধ হয়ে যে প্রার্থীর গ্রহণযোগ্যতা আছে, জনগণের ভোটে জয়ী হবেন এমন প্রার্থীকে বেছে নিতে হবে। মঙ্গলবার রাতে র‍্যাডিসন ব্লু চট্টগ্রাম বে-ভিউয়ে বিএনপির এক সাংগঠনিক সভায় প্রধান অতিথির বক্তব্যে নেতা–কর্মীদের এই বার্তা দেন দলের চেয়ারম্যান ও প্রধানমন্ত্রী তারেক রহমান। সভায় চট্টগ্রাম মহানগর, উত্তর ও দক্ষিণ বিএনপি ও এর অঙ্গসংগঠনের সাড়ে ৪০০ নেতা–কর্মী অংশগ্রহণ করেন।

আইনশৃঙ্খলা পরিস্থিতি নিয়ন্ত্রণে সমাজের গণ্যমান্য ব্যক্তিদের নিয়ে আইনশৃঙ্খলা রক্ষাকারী বাহিনীকে সহযোগিতার জন্য নেতা–কর্মীদের আহ্বান জানান প্রধানমন্ত্রী। তিনি বলেন, আইনশৃঙ্খলা পরিস্থিতি নিয়ন্ত্রণে নেতা–কর্মীদের আরও সজাগ থাকতে হবে। সবাই যার যার দায়িত্ব সঠিকভাবে পালন করলে ৫০ ভাগ অপরাধ কমে যাবে। নিজেদেরও কোনো অপরাধে জড়ানো যাবে না। এ ক্ষেত্রে কোনো ছাড় নেই। নগর বিএনপির আহ্বায়ক এরশাদ উল্লাহর সভাপতিত্বে সভা সঞ্চালনা করেন নগর বিএনপির সদস্যসচিব নাজিমুর রহমান। জানতে চাইলে তিনি প্রথম আলোকে বলেন, প্রধানমন্ত্রী সাংগঠনিক সভায় নেতা–কর্মীদের আগামী স্থানীয় নির্বাচনে সবাইকে ঐক্যবদ্ধ হয়ে গ্রহণযোগ্যতা আছে, জিতে আসতে পারে এমন প্রার্থী বাছাইয়ের জন্য নির্দেশ দিয়েছেন। নির্বাচনে সরকার অতীতের ফ্যাসিস্ট সরকারের মতো কোনো হস্তক্ষেপ করবে না।

সভায় উপস্থিত চট্টগ্রাম উত্তর জেলা বিএনপির সাবেক যুগ্ম আহ্বায়ক ও চট্টগ্রাম উন্নয়ন কর্তৃপক্ষের চেয়ারম্যান বেলায়েত হোসেন প্রথম আলোকে বলেন, আইনশৃঙ্খলা পরিস্থিতি নিয়ন্ত্রণে আইনশৃঙ্খলা বাহিনীকে সহযোগিতার জন্য নেতা–কর্মীদের নির্দেশ দিয়েছেন প্রধানমন্ত্রী। এ ছাড়া কার্যক্রম নিষিদ্ধ আওয়ামী লীগ ও জামায়াতে ইসলামের বর্তমান সরকারের নামে ছড়ানো নানা গুজব ও ষড়যন্ত্র মোকাবিলায় নেতা–কর্মীদের ঐক্যবদ্ধ থাকার নির্দেশ দিয়েছেন। সরকারের ভালো কাজগুলো মানুষের কাছে তুলে ধরতে বলেছেন প্রধানমন্ত্রী। বিরোধী দল বলে বেড়াচ্ছে সরকারের পায়ের নিচে মাটি নেই; কিন্তু প্রধানমন্ত্রী যেখানেই যাচ্ছেন সেখানে মানুষের উপচে পড়া ভিড়। দেশের মানুষ বর্তমান সরকারের কাজে সন্তুষ্ট। এর আগে প্রধানমন্ত্রী তারেক রহমান শারদীয় দুর্গোৎসবে পূজামণ্ডপ পরিদর্শন ও বাঙালি সনাতন ধর্মাবলম্বীদের সবচেয়ে বড় ধর্মীয় অনুষ্ঠান শারদীয় দুর্গোৎসবের শুভেচ্ছা জানাতে রংপুর, রাজশাহী ও চট্টগ্রামের জে এম সেন হলে আসেন। সামরিক বিমানযোগে আজ সন্ধ্যা ৭টা ৪০ মিনিটে রাজশাহী থেকে চট্টগ্রাম শাহ আমানত আন্তর্জাতিক বিমানবন্দরে অবতরণ করেন তিনি। সেখান থেকে জেএম সেন হল পূজামণ্ডপ পরিদর্শন করেন প্রধানমন্ত্রী।

এদিকে প্রধানমন্ত্রীর আগমনকে ঘিরে নগরের জেএম সেন হল ও র‍্যাডিসন ব্লু চট্টগ্রাম বে-ভিউ হোটেলের সামনে উৎসুক লোকজন ও নেতা–কর্মীরা ভিড় জমান। রাতে প্রধানমন্ত্রী চট্টগ্রাম ছেড়ে যান। উল্লেখ্য, প্রধানমন্ত্রী হিসেবে শপথ নেওয়ার পর তারেক রহমান গত ৯ আগস্ট প্রথমবারের মতো চট্টগ্রাম সফরে এসেছিলেন। ওই সফরে তিনি চট্টগ্রামের বাঁশখালী, ফটিকছড়ি, হাটহাজারী ও চট্টগ্রাম মহানগরের বিভিন্ন কর্মসূচিতে অংশ নেন। পরে হোটেল র‍্যাডিসনে নেতা–কর্মীদের সঙ্গে মতবিনিময় করেছিলেন।', 'নিজস্ব প্রতিবেদক', 'https://media.prothomalo.com/prothomalo-bangla/2026-09-05/a8tcon2o/WhatsApp-Image-2026-09-05-at-11.32.33-PM.jpeg', 'https://www.prothomalo.com/politics/g02n8935rj', '2026-10-21 02:22:13'),
(2, 'জনদুর্ভোগ নিরসন ও অপকর্ম দমনের পরিবর্তে সরকার বিরোধী দলের চরিত্র হননে ব্যস্ত: শফিকুর রহমান', 'politics/q6qugd1gjv', NULL, 'পুলিশের অতিরিক্ত উপমহাপরিদর্শক (অতিরিক্ত ডিআইজি) আবদুল্লাহ আল জহিরের মালিকানাধীন বাড়ি থেকে ৮৪ জন নারী-পুরুষ গ্রেপ্তার ও মাদক উদ্ধারের ঘটনায় দেশের আইনশৃঙ্খলা পরিস্থিতির চরম অবনতির অভিযোগ তুলেছেন জামায়াতে ইসলামীর আমির শফিকুর রহমান। মঙ্গলবার রাতে নিজের অফিশিয়াল ফেসবুক পেজে দেওয়া এক স্ট্যাটাসে শফিকুর রহমান দ্রব্যমূল্যের ঊর্ধ্বগতি এবং গ্যাস-বিদ্যুৎ সমস্যার কথাও তুলে ধরেন। তাঁর অভিযোগ, জনদুর্ভোগ নিরসন ও অপকর্ম দমনের পরিবর্তে সরকার এখন বিরোধী দলের চরিত্র হননে ব্যস্ত।

ফেসবুক স্ট্যাটাসে জামায়াতের আমির লেখেন, ‘বাংলাদেশ পুলিশে কর্মরত একজন অতিরিক্ত ডিআইজির মালিকানাধীন একটি বাড়ি থেকে অসামাজিক কাজে লিপ্ত থাকার দায়ে ৮৪ জন নারী-পুরুষকে গ্রেপ্তার করেছে ডিবি পুলিশ। একই সঙ্গে বাসা থেকে বিপুল পরিমাণ নিষিদ্ধ পণ্য (মাদক) উদ্ধার করা হয়েছে।’ তিনি আরও লেখেন, ‘এখান থেকেই বোঝা যায়, দেশের আইনশৃঙ্খলা পরিস্থিতির কতটা অবনতি হয়েছে। দেশের সর্বত্র আইনশৃঙ্খলাবিরোধী ও অসামাজিক কার্যকলাপের পাশাপাশি চাঁদাবাজির মহোৎসব, ছিনতাই, লুণ্ঠন ও ডাকাতি মারাত্মক আকার ধারণ করেছে।’ পুলিশের ঊর্ধ্বতন কর্মকর্তার বাড়িতে এমন ঘটনা প্রসঙ্গে শফিকুর রহমান লেখেন, ‘স্বয়ং পুলিশের একজন ঊর্ধ্বতন কর্মকর্তার মালিকানাধীন বাড়িতে এ ধরনের অপকর্ম সংঘটিত হওয়ায় জনমনে উদ্বেগ ও আতঙ্ক তৈরি হয়েছে।’ স্ট্যাটাসের শেষাংশে তরুণদের জাগার আহ্বান জানিয়ে তিনি লেখেন, ‘হায় সেলুকাস! আমাদের এই বাংলাদেশ! তরুণদের আরেকবার জাগতে হবে।’

বিভাগীয় তদন্তের দাবি এদিকে জামায়াতে ইসলামীর প্রচার ও মিডিয়া বিভাগের সেক্রেটারি এহসানুল মাহবুব জুবায়ের এক বিবৃতিতে একই ঘটনার নিন্দা ও প্রতিবাদ জানিয়েছেন। তিনি ঘটনার সুষ্ঠু তদন্ত, দায়ীদের শাস্তি এবং বাড়ির মালিক অতিরিক্ত ডিআইজি আবদুল্লাহ আল জহিরের বিরুদ্ধে বিভাগীয় তদন্তের দাবি জানান। বিবৃতিতে এহসানুল মাহবুব বলেন, পুলিশের একজন ঊর্ধ্বতন কর্মকর্তার মালিকানাধীন বাড়িতে এ ধরনের ঘটনা উদ্বেগজনক ও লজ্জাজনক। ঘটনার নেপথ্যে যাঁরা জড়িত এবং এ ধরনের অপরাধের যাঁরা পৃষ্ঠপোষকতা করেন, তাঁদেরও খুঁজে বের করে বিচারের মুখোমুখি করার দাবি জানান তিনি। এ ছাড়া মাদকের বিস্তার রোধে সরকার, আইনশৃঙ্খলা রক্ষাকারী বাহিনীর সব বিভাগ ও দেশবাসীকে এগিয়ে আসার আহ্বান জানান জামায়াতের এই নেতা।', 'নিজস্ব প্রতিবেদক', 'https://media.prothomalo.com/prothomalo-bangla/2026-09-27/yd97tyqv/Shafiqur-Rahman.avif', 'https://www.prothomalo.com/politics/q6qugd1gjv', '2026-10-20 23:37:33'),
(3, 'ইউরোপের বাইরেও তরুণদের বিক্ষোভ ছড়াচ্ছে, নতুন করে যোগ হচ্ছে জার্মানি', 'world/qpcldfhynu', 'বিভিন্ন দেশে জীবনযাত্রার ব্যয়, বাড়িভাড়া, শিক্ষা খাতে বিনিয়োগ ও সামাজিক অবিচার নিয়ে ক্ষোভ বাড়ছে। কোথাও বিক্ষোভ শান্তিপূর্ণ থাকলেও কোথাও তা সংঘর্ষ, ভাঙচুর ও আটকের ঘটনায় গড়িয়েছে।', 'বিশ্বের দেশে দেশে নানা দাবিতে রাজপথে বেশ কয়েক দিন ধরেই বিক্ষোভ হচ্ছে। কোথাও জীবনযাত্রার ব্যয় ও আবাসনসংকটের প্রতিবাদ, কোথাও দুর্নীতির বিরুদ্ধে আন্দোলন, আবার কোথাও শিক্ষাব্যবস্থার দুরবস্থা ও রাজনৈতিক অধিকারের দাবিতে আওয়াজ তুলছে মানুষ। আন্তর্জাতিক সংবাদমাধ্যমগুলোয় সবশেষ গতকাল বৃহস্পতিবার ও ফ্রান্স, সার্বিয়া, তিউনিসিয়া, কলম্বিয়া ও ভেনেজুয়েলায় বিক্ষোভের খবর প্রকাশিত হয়েছে। এ ছাড়া জার্মানিতে ৩১ অক্টোবর আন্দোলনের ডাক দিয়েছে তরুণদের একটি সংগঠন। ফ্রান্সে শিক্ষার্থীদের ক্ষোভ থেকে শুরু হওয়া আন্দোলন এখন ভয়াবহ সহিংস রূপ নিয়েছে। সার্বিয়ায় তরুণদের নেতৃত্বে দুর্নীতিবিরোধী আন্দোলনের সামনে এখন সংসদ নির্বাচন। ভেনেজুয়েলায় বিরোধী নেত্রীর দেশে ফেরা ও অবাধ নির্বাচনের দাবি উঠেছে। তিউনিসিয়ায় পুলিশি হেফাজতে মৃত্যুর অভিযোগ ঘিরে সংঘর্ষ হয়েছে। আর কলম্বিয়ায় বিক্ষোভের খবর সংগ্রহ করতে গিয়ে সাংবাদিকদের ওপর পুলিশের হামলার অভিযোগ উঠেছে। এ ছাড়া ইউরোপের বিভিন্ন দেশে জীবনযাত্রার ব্যয়, বাড়িভাড়া, শিক্ষা খাতে বিনিয়োগ ও সামাজিক বৈষম্য নিয়ে ক্ষোভ বাড়ছে। কোথাও বিক্ষোভ শান্তিপূর্ণ থাকলেও কোথাও তা সংঘর্ষ, ভাঙচুর ও আটকের ঘটনায় গড়িয়েছে।

ফ্রান্স ফ্রান্সে চলমান বিক্ষোভের সূত্রপাত গত ১৭ সেপ্টেম্বর প্যারিসের দক্ষিণ-পূর্বে ক্রেতেই শহরের একটি উচ্চবিদ্যালয়ে। শিক্ষকসংকট ও জরাজীর্ণ ভবনের প্রতিবাদে শিক্ষকেরা সেখানে আন্দোলন শুরু করেন। পরে শিক্ষার্থীরাও যোগ দেন। ধীরে ধীরে শিক্ষাপ্রতিষ্ঠানের সমস্যা ছাড়িয়ে জীবনযাত্রার ব্যয় বৃদ্ধি ও সরকারি সেবার মান নিয়ে অসন্তোষ ছড়িয়ে পড়ে দেশজুড়ে। গত সপ্তাহান্তে বিক্ষোভের একাংশ সহিংস হয়ে ওঠে। বিভিন্ন শহরে দোকানপাটে লুটপাট, সরকারি ভবনে ভাঙচুর ও অগ্নিসংযোগের ঘটনা ঘটে। লিমোজ শহরের ঐতিহাসিক টাউন হল আগুনে পুড়িয়ে দেওয়া হয়। কর্তৃপক্ষের হিসাবে, গত সপ্তাহান্ত থেকে এ পর্যন্ত প্রায় ২ হাজার ৫০০ জনকে আটক করা হয়েছে। তাঁদের মধ্যে ১৭৪ জনকে বিচারিক হেফাজতে পাঠানো হয়েছে এবং ৯০০ জনের বেশি মানুষের বিরুদ্ধে বিচারপ্রক্রিয়া চলছে। বিক্ষোভের নতুন কর্মসূচি সামনে রেখে প্রেসিডেন্ট এমানুয়েল মাখোঁ গতকাল বলেছেন, অনুমতি ছাড়া কোনো ব্যক্তি বা গোষ্ঠীর জন্য বিক্ষোভ নিষিদ্ধ করা হয়েছে। স্বীকৃত সংগঠন ও ট্রেড ইউনিয়নগুলোকে বিক্ষোভের অনুমতি দেওয়া যেতে পারে। তবে নিরাপত্তার স্বার্থে বিক্ষোভের স্থান পরিবর্তন করা হতে পারে। লিওঁসহ কয়েকটি শহরে আগামীকাল শনিবারের বিক্ষোভের ওপর নিষেধাজ্ঞা জারি করা হয়েছে।

ভেনেজুয়েলা ভেনেজুয়েলার রাজধানী কারাকাসসহ বিভিন্ন শহরে গতকাল হাজারো মানুষ বিক্ষোভ করেন। তাঁদের প্রধান দাবি, প্রেসিডেন্ট নির্বাচন আয়োজন এবং বিরোধী নেত্রী মারিয়া কারিনা মাচাদোকে দেশে ফেরানো। শান্তিতে নোবেল পুরস্কারজয়ী মাচাদো বর্তমানে নির্বাসনে আছেন। বার্তা সংস্থা এএফপির প্রতিবেদন অনুযায়ী, গতকাল দেশটির রাজধানী কারাকাসে প্রায় দুই হাজার মানুষ শান্তিপূর্ণভাবে সমবেত হন। দেশের অন্য এলাকাতেও বিক্ষোভ হয়েছে।

৪৩ বছর বয়সী বিরোধী দলীয় সমর্থক এরিকা সেদেনো এএফপিকে বলেন, ‘আমরা প্রেসিডেন্ট নির্বাচন দেওয়া এবং আমাদের নেত্রী মারিয়া কারিনা মাচাদোকে ফিরিয়ে আনার দাবি জানাচ্ছি।’ ৫৩ বছর বয়সী দরজি মায়রিম বেলত্রান বলেন, ‘আমি ক্লান্ত। আমরা সত্যিই পরিবর্তন চাই, যথেষ্ট হয়েছে।’ কলম্বিয়া সীমান্তবর্তী তাচিরা শহর এবং উত্তর-পূর্বাঞ্চলের বলিভারেও বিক্ষোভ হয়েছে। তাচিরায় বিক্ষোভকারীরা যেখানে সমাবেশ করতে চেয়েছিলেন, সেখানে যাওয়ার সড়ক বন্ধ করে দেওয়ায় তাঁরা প্রতিবাদ জানান।

সার্বিয়া সার্বিয়ার রাজধানী বেলগ্রেডে গতকাল সরকারবিরোধী শিক্ষার্থী আন্দোলনের সমর্থনে বিশাল বিক্ষোভ সমাবেশ হয়েছে। আগামী রোববারের আগাম পার্লামেন্ট নির্বাচন সামনে রেখে আয়োজিত এই সমাবেশে লাখো মানুষ অংশ নেন। তাঁদের লক্ষ্য, আলেকসান্দার ভুসিচের নেতৃত্বাধীন সার্বিয়ান প্রগ্রেসিভ পার্টিকে পরাজিত করা। প্রায় দুই বছর ধরে চলা শিক্ষার্থী আন্দোলনের চাপে গত ২৭ সেপ্টেম্বর প্রেসিডেন্টের পদ থেকে পদত্যাগ করেন ভুসিচ। ২০২৪ সালের নভেম্বরে নোভি সাদ শহরের রেলস্টেশনের ছাউনির একটি অংশ ধসে ১৬ জন নিহত হওয়ার পর দুর্নীতির তদন্ত ও জবাবদিহির দাবিতে এই আন্দোলন শুরু হয়েছিল। পরে আন্দোলনকারীরা আগাম নির্বাচনের দাবি তোলেন। শেষ পর্যন্ত সেই দাবির মুখেই আগাম নির্বাচনের ঘোষণা আসে। তবে পদত্যাগ করলেও রাজনীতি ছাড়েননি ভুসিচ। এবার নিজের দলের নেতৃত্ব দিয়ে প্রধানমন্ত্রী হওয়ার লক্ষ্যে নির্বাচনে লড়ছেন তিনি।

শিক্ষার্থীদের সমর্থিত ‘স্টুডেন্টস লিস্ট’ এবারের নির্বাচনে ভুসিচের দলের সঙ্গে প্রায় সমানতালে প্রতিদ্বন্দ্বিতা করছে বলে জনমত জরিপে আভাস পাওয়া যাচ্ছে। তবে দেশটির মূলধারার সংবাদমাধ্যম ও বিভিন্ন প্রতিষ্ঠানের ওপর ক্ষমতাসীন দলের ব্যাপক নিয়ন্ত্রণ রয়েছে। বিশ্লেষকদের মতে, দুই পক্ষের মধ্যে ব্যবধান খুব কম হলে নির্বাচনের ফলাফল নিয়ে অনিশ্চয়তা তৈরি হতে পারে। ভোট শেষে উভয় পক্ষ নিজেদের বিজয়ী দাবি করলে নির্বাচন-পরবর্তী অস্থিরতার আশঙ্কাও রয়েছে। বিক্ষোভে অংশ নেওয়া ৪৭ বছর বয়সী মারিয়া নেদেলকোভিচ রাদিচ বলেন, ‘আমি স্টুডেন্ট লিস্টকে সমর্থন জানাতে এসেছি। তরুণেরা আমাকে নতুন করে আশা দেখিয়েছেন, একটি দেশে স্বাভাবিকভাবে বেঁচে থাকা সম্ভব।’

তিউনিসিয়া তিউনিসিয়া পুলিশের হেফাজতে এক ব্যক্তির মৃত্যুর প্রতিবাদে দেশটির রাজধানী তিউনিসের উপকণ্ঠে ইততাদামেন এলাকায় গতকাল বিক্ষোভ হয়। ওই ব্যক্তিকে মাদক ব্যবসায়ী সন্দেহে আটক করা হয়েছিল। পরিবারের অভিযোগ, আটকের পর পুলিশি নির্যাতনে তাঁর মৃত্যু হয়েছে। তাঁরা ঘটনার তদন্ত এবং দায়ীদের জবাবদিহি দাবি করেছেন। তবে স্থানীয় সংবাদমাধ্যমের ভাষ্য, মাদকদ্রব্য গিলে ফেলার পর তাঁর মৃত্যু হয়। বিক্ষোভকারীরা সড়ক অবরোধ করেন, টায়ারে আগুন দেন এবং পুলিশের দিকে পাথর ছুড়ে মারেন। পুলিশ কাঁদানে গ্যাস ছুড়ে তাঁদের ছত্রভঙ্গ করার চেষ্টা করে। নিরাপত্তা বাহিনী এলাকার একটি ন্যাশনাল গার্ড স্টেশন সুরক্ষিত রাখারও চেষ্টা করেছে।

দেশটির দক্ষিণাঞ্চলের স্ফাক্স গভর্নরেটের জেবিনিয়ানা শহরেও এক ব্যক্তির মৃত্যু ঘিরে বিক্ষোভ হয়েছে। তাঁর স্বজনদের দাবি, নিরাপত্তা বাহিনীর ধাওয়া খেয়ে তিনি মারা যান। সেখানে বিক্ষোভকারীরা একটি গাড়িতে আগুন দেন। পুলিশের সঙ্গে সেখানেও বিক্ষোভকারীদের সংঘর্ষ হয়েছে।

স্ফ্যাক্স শহরে এক শিক্ষার্থীর মৃত্যুর ঘটনায় বিক্ষোভ করেছেন তাঁর সহপাঠীরা। হৃদ্‌যন্ত্রের সমস্যায় আক্রান্ত ওই শিক্ষার্থীকে হাসপাতালে নিতে দেরিতে অ্যাম্বুলেন্স আসায় তাঁর মৃত্যু হয়েছে বলে অভিযোগ সহপাঠীদের। তাঁরা চিকিৎসাসেবার ঘাটতির কথা তুলে ধরে বিশ্ববিদ্যালয়ের বিভিন্ন অনুষদে ধর্মঘটের ডাক দিয়েছেন। তিউনিসিয়ায় এমন এক সময়ে এসব বিক্ষোভ হচ্ছে, যখন জীবনযাত্রার মান, সরকারি সেবা ও রাজনৈতিক স্বাধীনতা নিয়ে অসন্তোষ বাড়ছে। এর আগে ১৭ অক্টোবর দেশটির প্রেসিডেন্ট কাইস সাঈদের পদত্যাগের দাবিতে কয়েক বছরের মধ্যে সবচেয়ে বড় বিক্ষোভ হয়েছিল।

জার্মানি জার্মানির ২১টি শহরে বিক্ষোভের ডাক দিয়েছেন তরুণেরা। ৩১ অক্টোবর এসব কর্মসূচি পালনের কথা রয়েছে। শিক্ষা খাতে ব্যয় সংকোচন, জীবনযাত্রার ক্রমবর্ধমান ব্যয়, সামাজিক বৈষম্য ও বাধ্যতামূলক সামরিক নিয়োগের বিরুদ্ধে তাঁরা বিক্ষোভ করবেন। ‘জেন জেড রেগেল্ট’ নামের তরুণদের একটি সংগঠন এ বিক্ষোভের ডাক দিয়েছে। আয়োজকদের প্রত্যাশা, এতে হাজারো মানুষ অংশ নেবেন। সম্ভাব্য বিক্ষোভ ঘিরে দেশটির নিরাপত্তা সংস্থাগুলো পরিস্থিতি পর্যবেক্ষণ করছে। পুলিশের আশঙ্কা, উগ্রপন্থী গোষ্ঠী বিক্ষোভকে সহিংসতার দিকে ঠেলে দেওয়ার চেষ্টা করতে পারে। অন্যদিকে আয়োজকেরা জানিয়েছেন, তাঁরা মানুষ বা সম্পত্তির বিরুদ্ধে সব ধরনের সহিংসতার বিরোধী।', 'প্রথম আলো ডেস্ক', 'https://media.prothomalo.com/prothomalo-bangla/2026-10-17/tm9x8vx5/French-riot-police.jpg', 'https://www.prothomalo.com/world/qpcldfhynu', '2026-10-23 15:22:49'),
(3, 'মাইক্রোসফটের সিইও বললেন, ‘ দীর্ঘ সময়ে এমন ঘটনা দেখিনি’', 'world/617bzjvr5r', 'পিএইচপির ত্রুটিতে বিশ্বজুড়ে জরুরি অবস্থা', 'ওয়েবসাইট তৈরি ও পরিচালনায় বহুল ব্যবহৃত প্রোগ্রামিং ল্যাঙ্গুয়েজ পিএইচপিতে দুটি গুরুতর নিরাপত্তা ত্রুটি ধরা পড়ার পর জরুরি ব্যবস্থা নিয়েছে বিভিন্ন দেশের সরকার। ত্রুটি ধরা পড়ার খবর সামনে আসার পর বুধবার রাত থেকে বিশ্বজুড়ে বিভিন্ন দেশের সরকার ও বাণিজ্যিক প্রতিষ্ঠান তাদের ওয়েবসাইট বন্ধ করে দিয়েছে। এরপরও লাখ লাখ হ্যাকিংয়ের চেষ্টা হয়েছে বলে জানা গেছে। এইচটিএমএল ও পাইথনের মতো পিএইচপি একটি গুরুত্বপূর্ণ প্রোগ্রামিং ল্যাঙ্গুয়েজ। এর ডেভেলপাররা বুধবার দুটি নিরাপত্তাত্রুটি ঠিক করার জন্য হালনাগাদ সংস্করণ প্রকাশ করেন। কৃত্রিম বুদ্ধিমত্তা (এআই) ব্যবহার করে পিএইচপিতে থাকা এসব ত্রুটি শনাক্ত করা হয়। ব্যবহারকারীদের তা দ্রুত হালনাগাদ করার আহ্বান জানানো হয়।

বেলজিয়ামের সাইবার নিরাপত্তা প্রতিষ্ঠান আইকিডো সিকিউরিটির সহপ্রতিষ্ঠাতা ম্যাডেলিন লরেন্স বলেন, ত্রুটিগুলো সংশোধন করে পিএইচপির হালনাগাদ সংস্করণ আসার আগেই ত্রুটিগুলো–সম্পর্কিত বিস্তারিত তথ্য সামনে চলে আসে। এরপর থেকে এসব ত্রুটি কাজে লাগিয়ে ওয়েবসাইটের নিয়ন্ত্রণ নেওয়ার জন্য সাইবার হামলার চেষ্টার খবর পাওয়া যাচ্ছে। হামলাকারীদের এসব ত্রুটির সুযোগ নেওয়া ঠেকাতে প্রতিষ্ঠানগুলো দ্রুত ওয়েবসাইট হালনাগাদ করছে। তবে ওয়েবসাইট হালনাগাদ করার প্রচেষ্টার মধ্যেই লাখ লাখ হ্যাকিংয়ের চেষ্টা হয়েছে বলে জানিয়েছে ক্লাউড সেবাদাতা প্রতিষ্ঠান ক্লাউডফ্লেয়ার। বুধবার প্রতিষ্ঠানটির প্রধান নির্বাহী কর্মকর্তা ম্যাথিউ প্রিন্স বলেন, ‘নিরাপত্তা ত্রুটির বিষয়টি প্রকাশ্যে আসার পরের ৪৫ মিনিটে সাইবার হামলার চেষ্টা বেড়ে কয়েক হাজার হয়ে যায়। দুই ঘণ্টার মধ্যে সংখ্যাটি কয়েক লাখে পৌঁছায়। এখন তা আরও বেশি।’

জাপানের কয়েকটি প্রতিষ্ঠান আজ বৃহস্পতিবার জানিয়েছে, জরুরি নিরাপত্তাব্যবস্থার অংশ হিসেবে তারা সাময়িকভাবে কিছু অনলাইন সেবা বন্ধ রেখেছে। এসব প্রতিষ্ঠানের মধ্যে রয়েছে আর্থিক প্রতিষ্ঠান মিতসুবিশি ইউএফজে ফাইন্যান্সিয়াল গ্রুপ, উড়োজাহাজ পরিবহন সংস্থা এএনএ ও ইস্ট জাপান রেলওয়ে। জাপানের অর্থ মন্ত্রণালয় ও আবহাওয়া সংস্থাও অনলাইন সেবা সীমিত করেছে। এদিকে ফ্রান্সের টেলিযোগাযোগ প্রতিষ্ঠান অরেঞ্জ জানিয়েছে, সতর্কতামূলক ব্যবস্থা হিসেবে তাদের কয়েকটি সহযোগী প্রতিষ্ঠানে পিএইচপিভিত্তিক ওয়েবসাইট ও সফটওয়্যারে প্রবেশ সাময়িকভাবে বন্ধ রাখা হয়েছে। চীনের অন্যতম বড় ক্লাউড কম্পিউটিং সেবাদাতা প্রতিষ্ঠান টেনসেন্ট ক্লাউডও গ্রাহকদের পিএইচপির হালনাগাদ সংস্করণ ব্যবহার করার পরামর্শ দিয়েছে।

পিএইচপিতে এই নিরাপত্তাত্রুটির কারণে যে দুর্ভোগ দেখা দিয়েছে, তা ইন্টারনেট সচল রাখতে ব্যবহৃত প্রোগ্রামিং প্রযুক্তির জন্য বড় একটি পরীক্ষা বলে উল্লেখ করেছেন বিশেষজ্ঞরা। এ বিষয়ে মাইক্রোসফটের প্রধান নির্বাহী কর্মকর্তা (সিইও) সত্য নাদেলা বুধবার বলেন, ‘দীর্ঘ সময়ের মধ্যে এমন ঘটনা কখনো দেখিনি।’ তিনি বলেন, নিরাপত্তা বজায় রেখে রক্ষণাবেক্ষণ করা যায়, এমন ডিজিটালব্যবস্থা তৈরির গুরুত্ব এই ঘটনা আবারও তুলে ধরেছে। একে গত দুই বছরের মধ্যে সবচেয়ে গুরুতর ঘটনাগুলোর অন্যতম হিসেবে উল্লেখ করেছেন জার্মানির সাইবার সিকিউরিটিবিষয়ক প্রতিষ্ঠান ফ্রাউনহোফের ইনোভেশন প্ল্যাটফর্মের সায়েন্টিফিক পরিচালক হায়া শ্কুলম্যান। এসব ঝুঁকিকে বাস্তব উল্লেখ করে ত্রুটি সংশোধনের আহ্বান জানিয়েছেন তিনি।', 'রয়টার্স', 'https://media.prothomalo.com/prothomalo-bangla/2026-10-22/7d2yv1i4/php.jfif', 'https://www.prothomalo.com/world/617bzjvr5r', '2026-10-22 23:11:49'),
(3, 'পিএইচপির ত্রুটি ঠিক করতে বিশ্বজুড়ে দৌড়ঝাঁপ, লাখ লাখ হ্যাকিংয়ের চেষ্টা', 'world/vt0owxi65w', 'প্রোগ্রামিং ল্যাঙ্গুয়েজ পিএইচপির দুটি গুরুতর ত্রুটি শনাক্ত হওয়ার পর টোকিও থেকে হেলসিঙ্কি পর্যন্ত ব্যাংক, বিমান সংস্থা, রেল, কর ও বিভিন্ন সরকারি সেবা সাময়িকভাবে বন্ধ রাখা হয়েছে।', 'ওয়েবসাইট তৈরি ও পরিচালনায় বহুল ব্যবহৃত প্রোগ্রামিং ল্যাঙ্গুয়েজ পিএইচপিতে গুরুতর নিরাপত্তা ত্রুটি ধরা পড়ার পর বিশ্বজুড়ে বিভিন্ন দেশের সরকার ও বিভিন্ন কোম্পানি দ্রুত সেগুলো ঠিক করার চেষ্টা করছে। অপর দিকে এই ত্রুটির কথা প্রকাশের পর লাখ লাখ সাইবার হামলার চেষ্টা হয়েছে বলে জানিয়েছে একটি সাইবার নিরাপত্তা কোম্পানি। এর আগে বুধবার ইউরোপসহ বিভিন্ন অঞ্চলের বিভিন্ন দেশের সরকার সতর্কতামূলক ব্যবস্থা হিসেবে বহু ওয়েবসাইট বন্ধ করে দেয়। একই সময়ে ওয়েবসাইটের অপারেটররা পিএইচপির ত্রুটি ঠিক করার চেষ্টা করেন। এই পরিস্থিতিতে টোকিও থেকে হেলসিঙ্কি পর্যন্ত ব্যাংক, বিমান সংস্থা, রেল, কর ও বিভিন্ন সরকারি সেবা সাময়িকভাবে বন্ধ রাখার ঘটনায় দেখা যায় সরকারি ও বেসরকারি ব্যবস্থায় পিএইচপি কতটা ব্যাপকভাবে ব্যবহৃত হয়। এ ধরনের ত্রুটির কথা প্রকাশ্যে আসার পর দ্রুত তা ঠিক করাও কত কঠিন, সেটিও স্পষ্ট হয়ে ওঠে।

জার্মানির কোলোনে আজ বৃহস্পতিবার এক অনুষ্ঠানে মাইক্রোসফটের প্রধান নির্বাহী সত্য নাদেলা বলেন, ‘আইটি ও নিরাপত্তা খাতের সবার জন্য এই দিন ও রাতটি খুব দীর্ঘ ছিল—আমি তা জানি। অনেক দিন ধরে এমন কিছু দেখিনি।’ তিনি বলেন, নিরাপত্তা বজায় রেখে রক্ষণাবেক্ষণ করা যায়, এমন ডিজিটালব্যবস্থা তৈরির গুরুত্ব এই ঘটনা আবারও তুলে ধরেছে। কৃত্রিম বুদ্ধিমত্তা বা এআই ব্যবহার করে বহু বছর ধরে পিএইচপিতে থাকা ত্রুটিগুলো শনাক্ত করা হয়। এরপর বুধবার পিএইচপির নির্মাতারা জরুরি সংশোধনী প্রকাশ করেন এবং ব্যবহারকারীদের দ্রুত সফটওয়্যার হালনাগাদ করতে বলেন। বেলজিয়ামভিত্তিক সাইবার নিরাপত্তা প্রতিষ্ঠান আইকিডো সিকিউরিটির সহপ্রতিষ্ঠাতা ম্যাডেলিন লরেন্স বলেন, সংশোধনী প্রস্তুত হওয়ার আগেই ত্রুটিগুলোর বিস্তারিত প্রকাশ্যে আসে। এর পর থেকে হামলার চেষ্টা হচ্ছে। তিনি বলেন, তাই প্রতিষ্ঠানগুলো এখন হামলাকারীদের আগেই ব্যবস্থা হালনাগাদ করতে দৌড়াচ্ছে। এটাই এখনকার প্রতিযোগিতা। বিভিন্ন দেশের সরকার ও কোম্পানিগুলো যখন ত্রুটি ঠিক করছে এবং সতর্কতামূলক ব্যবস্থা হিসেবে ওয়েবসাইট বন্ধ রাখছে, তার মধ্যে লাখ লাখ হ্যাকিংয়ের চেষ্টা হয়েছে বলে জানিয়েছে ক্লাউড সেবা প্রতিষ্ঠান ক্লাউডফ্লেয়ার। এই প্রতিষ্ঠানের প্রধান নির্বাহী ম্যাথু প্রিন্স বুধবার রাতে সামাজিক যোগাযোগমাধ্যম এক্সে লেখেন, ‘ত্রুটির কথা প্রকাশ্যে আসার আগের ১০ ঘণ্টায় আমাদের নেটওয়ার্কে এটি কাজে লাগানোর হাজারো চেষ্টা আমরা দেখেছি।’ তিনি আরও লেখেন, ঘোষণার পরের ৪৫ মিনিটে সেই চেষ্টা কয়েক হাজার থেকে ১০ হাজারে পৌঁছায়। দুই ঘণ্টার মধ্যে তা কয়েক লাখ হয়, আর এখন সংখ্যাটি লাখ ছাড়িয়ে গেছে।

জাপানের কয়েকটি কোম্পানি আজ জানিয়েছে, জরুরি ব্যবস্থার অংশ হিসেবে তারা সাময়িকভাবে কিছু অনলাইন সেবা বন্ধ রেখেছে। এসব প্রতিষ্ঠানের মধ্যে আছে ব্রোকারেজ প্রতিষ্ঠান নোমুরা, ঋণদাতা মিতসুবিশি ইউএফজে ফাইন্যানশিয়াল গ্রুপ, বিমান সংস্থা এএনএ এবং ইস্ট জাপান রেলওয়ে। বিমা কোম্পানি টোকিও মেরিন হোল্ডিংস জানায়, তারা নিজেদের একটি সহযোগী প্রতিষ্ঠানের ওয়েবসাইট বন্ধ রেখেছে। নিরাপত্তাব্যবস্থা নিতে জাপানের অর্থ মন্ত্রণালয় ও আবহাওয়া সংস্থা অনলাইন সেবার কিছু অংশ সাময়িকভাবে বন্ধ করে। দেশটির জাতীয় কর সংস্থাও সাময়িকভাবে তাদের অনলাইন সেবা বন্ধ রাখে। সতর্কতামূলক এই পদক্ষেপগুলো জাপানে সাইবার নিরাপত্তা নিয়ে বাড়তে থাকা উদ্বেগের ইঙ্গিত দেয়। ট্রেন্ডএআইয়ের তথ্য অনুযায়ী, চলতি বছরের প্রথম ৯ মাসে জাপানে গত বছরের পুরো সময়ের চেয়েও বেশি সাইবার হামলার ঘটনা ঘটেছে। ফ্রান্সের টেলিযোগাযোগ প্রতিষ্ঠান অরেঞ্জ জানায়, সতর্কতামূলক ব্যবস্থা হিসেবে তারা কয়েকটি সহযোগী প্রতিষ্ঠানের পিএইচপিভিত্তিক ওয়েবসাইট ও অ্যাপে প্রবেশ সাময়িকভাবে বন্ধ রেখেছে।

চীনের অন্যতম বড় ক্লাউড সেবা প্রতিষ্ঠান টেনসেন্ট ক্লাউড গ্রাহকদের পিএইচপির হালনাগাদ সংস্করণ ইনস্টল করতে বলেছে। তবে তারা ব্যাপকভাবে ওয়েবসাইট বন্ধ রাখার পরামর্শ দেয়নি। ফিনল্যান্ডের সরকারি তথ্যপ্রযুক্তি সেবা প্রদানকারী প্রতিষ্ঠান ভালতোরি জানায়, তারা রাতভর পিএইচপির নিরাপত্তা সংশোধনী বসিয়েছে। এক দিন আগে সরকারি ওয়েব সেবাগুলো বন্ধ রাখার পর এখন ধীরে ধীরে সেগুলোতে দেওয়া সাময়িক বাধা তুলে নেওয়া হচ্ছে। ভালতোরির মহাপরিচালক হান্নু নাউমানেন এক বিবৃতিতে বলেন, সেবা আবার চালু করতে কয়েক দিন, এমনকি কয়েক সপ্তাহও লাগতে পারে। হালনাগাদের পাশাপাশি ব্যবস্থাগুলো সতর্কভাবে পরীক্ষা করতে হবে। পিএইচপির ত্রুটি ঘিরে আজ এশিয়ার কয়েকটি দেশের সরকার সাইবার নিরাপত্তা পরীক্ষা চালানোর নির্দেশ দিয়েছে। চীনের শিল্প মন্ত্রণালয় প্রতিষ্ঠান ও ব্যবহারকারীদের নিজেদের ব্যবস্থা দ্রুত পরীক্ষা করে পিএইচপির সর্বশেষ নিরাপদ সংস্করণ ইনস্টল করতে বলেছে। প্রয়োজন অনুযায়ী সাইবার নিরাপত্তা পর্যবেক্ষণ জোরদার এবং অ্যাকাউন্ট, পাসওয়ার্ড ও নিরাপত্তা পাসওয়ার্ড পরিবর্তনেরও পরামর্শ দিয়েছে মন্ত্রণালয়। হ্যাকিংয়ের ঝুঁকি বাড়তে পারে—এমন উদ্বেগ জানিয়ে দক্ষিণ কোরিয়া বেসরকারি খাতের সাইবার নিরাপত্তা সতর্কতার মাত্রা বাড়িয়েছে এবং জরুরি সাড়াদানের ব্যবস্থা চালু করেছে।', 'রয়টার্স', 'https://media.prothomalo.com/prothomalo-bangla/2026-10-22/i51bk11m/PHP-3.PNG', 'https://www.prothomalo.com/world/vt0owxi65w', '2026-10-22 19:44:15'),
(3, 'ইরানের বাইরে কোথাও যাবে না সমৃদ্ধ ইউরেনিয়াম, নতুন মার্কিন হামলার আশঙ্কার মধ্যেও অনড় তেহরান', 'world/middle-east/fgmnk4zake', 'ইরান তাদের আগের অবস্থানেই অনড়। দেশটি বলছে, যুক্তরাষ্ট্র তাদের শর্ত মেনে না নিলে তারা হরমুজ প্রণালি খুলবে না এবং যুদ্ধের অবসানও হবে না।', 'ইরানের বিরুদ্ধে যুক্তরাষ্ট্র ও ইসরায়েলের যুদ্ধ বন্ধে মধ্যপ্রাচ্যে কূটনৈতিক তৎপরতা বাড়ছে। তবে এখনো সমঝোতার কোনো লক্ষণ দেখা যাচ্ছে না। ইরান যুদ্ধ ও ইয়েমেনের সাম্প্রতিক উত্তেজনা নিয়ে আলোচনা করতে পাকিস্তানের সেনাপ্রধান আসিম মুনির গতকাল বুধবার তেহরান সফর করেছেন। এমন এক সময়ে তিনি দেশটি সফরে গেলেন, যখন মধ্যপ্রাচ্যে আবারও সংঘাত ছড়িয়ে পড়ার আশঙ্কা তৈরি হয়েছে। কিন্তু ইরান তাদের আগের অবস্থানেই অনড়। দেশটি বলছে, যুক্তরাষ্ট্র তাদের শর্ত মেনে না নিলে তারা হরমুজ প্রণালি খুলবে না এবং যুদ্ধের অবসানও হবে না।

ইরানের সুপ্রিম ন্যাশনাল সিকিউরিটি কাউন্সিলের সেক্রেটারি মোহসেন রেজায়ি গত মঙ্গলবার রাতে আসিম মুনিরের সঙ্গে বৈঠকের পর বলেন, ‘সমৃদ্ধ ইউরেনিয়ামের এক গ্রামও ইরান থেকে সরানো হবে না।’ তবে মোহসেন রেজায়ি ইউরেনিয়াম সমৃদ্ধকরণের মাত্রা কমানোর সম্ভাবনা নাকচ করেননি। আন্তর্জাতিক পর্যবেক্ষকদের তত্ত্বাবধানে ইরানের ভেতরেই এ কাজ করা যেতে পারে। এর আগে তেহরান এমন প্রস্তাব দিয়েছিল।

গত ২৮ ফেব্রুয়ারি ইরানে মার্কিন প্রেসিডেন্ট ডোনাল্ড ট্রাম্পের প্রশাসনের যুদ্ধ শুরুর অন্যতম কারণ ছিল দেশটির বিতর্কিত পারমাণবিক কর্মসূচি। ট্রাম্প যুদ্ধ শুরুর পর থেকে বারবার বলেছেন, তিনি ইরানের পারমাণবিক কর্মসূচি পুরোপুরি শেষ করে দিতে চান। তবে চলতি মাসের শুরুতে যুক্তরাষ্ট্রের ভাইস প্রেসিডেন্ট জেডি ভ্যান্স ইঙ্গিত দেন, ইউরেনিয়াম সমৃদ্ধকরণের সক্ষমতা উল্লেখযোগ্য হারে কমানো হলে ওয়াশিংটন সন্তুষ্ট হতে পারে।

ইরানের শাসকগোষ্ঠী কয়েক দশকের পুরোনো পারমাণবিক কর্মসূচিকে দেশের সার্বভৌম অধিকার ও অর্জন হিসেবে তুলে ধরছে। চলমান যুদ্ধ এবং এর আগে বিভিন্ন হামলা ও হত্যাকাণ্ডের মধ্যেও এ কর্মসূচি বন্ধ হয়নি। গত মঙ্গলবার মোহসেন রেজায়ি এটিকে ‘জাতীয় সম্পদ’ বলে বর্ণনা করেন। ইরান কম মাত্রায় সমৃদ্ধ ইউরেনিয়াম বেসামরিক কাজেও ব্যবহার করে। এর মধ্যে রয়েছে ওষুধ তৈরি এবং রাশিয়ার সহযোগিতায় বুশেহর বিদ্যুৎকেন্দ্রে বিদ্যুৎ উৎপাদন। ইরানের শাসকগোষ্ঠী বলছে, সামরিক চাপের মুখে পারমাণবিক কর্মসূচি বন্ধ করে দেওয়া আত্মসমর্পণের শামিল হবে। তা ছাড়া কর্মসূচি বন্ধ করলে ভবিষ্যতে হামলা না হওয়ার নিশ্চয়তাও নেই।

২০২৫ সালের জুনে ইরানের পারমাণবিক স্থাপনায় ইসরায়েল ও যুক্তরাষ্ট্র যৌথভাবে আগ্রাসন শুরু চাকরে। এর আগে আন্তর্জাতিক পারমাণবিক শক্তি সংস্থা (আইএইএ) ধারণা করেছিল, তেহরানের কাছে ৬০ শতাংশ পর্যন্ত সমৃদ্ধ ৪৪০ কেজি ইউরেনিয়াম আছে। পারমাণবিক বোমা তৈরির জন্য ইউরেনিয়ামকে ৯০ শতাংশের বেশি সমৃদ্ধ করতে হয়। ২০২৫ সালের ওই হামলার পর চলতি বছরও যুক্তরাষ্ট্র ও ইসরায়েল ইরানের পারমাণবিক স্থাপনাগুলোয় হামলা চালায়। এতে দেশটির পারমাণবিক অবকাঠামো মারাত্মকভাবে ক্ষতিগ্রস্ত হয়। আইএইএ গুরুত্বপূর্ণ স্থাপনাগুলো পরিদর্শন করতে না পারায় বর্তমানে ইরানের কাছে কতটুকু সমৃদ্ধ ইউরেনিয়াম আছে, সেগুলোর কী অবস্থা এবং কোথায় রাখা হয়েছে—এসব তথ্য যাচাই করা সম্ভব হচ্ছে না। যুদ্ধ শুরুর পর থেকে ইরান আইএইএকে তাদের পারমাণবিক স্থাপনা পরিদর্শনের অনুমতি দেয়নি। তেহরানের অভিযোগ, সংস্থাটি মূলত পশ্চিমা দেশগুলোর স্বার্থে কাজ করছে।

ইরানের কর্মকর্তারা বলে আসছেন, তাঁরা পারমাণবিক বোমা তৈরির চেষ্টা করছেন না। তবে মোহসেন রেজায়ির মতো জ্যেষ্ঠ কর্মকর্তারা প্রকাশ্যে প্রশ্ন তুলেছেন, ইরানের পারমাণবিক স্থাপনা ও অন্যান্য অবকাঠামোয় হামলা অব্যাহত থাকলে আন্তর্জাতিক পারমাণবিক অস্ত্র বিস্তার রোধ চুক্তির (এনপিটি) সদস্য হিসেবে থাকার যৌক্তিকতা কী। চলতি সপ্তাহে ইরানের কর্মকর্তারা একাধিক দেশের কূটনীতিকদের সঙ্গে বৈঠক করেছেন। রাশিয়ার পররাষ্ট্রমন্ত্রী সের্গেই লাভরভ সোমবার তেহরান সফর করেন। এর আগের দিন তিনি উপসাগরীয় সহযোগিতা পরিষদের (জিসিসি) সদস্য দেশগুলোর সঙ্গে বৈঠকে অংশ নিয়েছিলেন। অন্য আরব কর্মকর্তাদেরও তেহরান সফরের ইঙ্গিত পাওয়া গেছে। যুক্তরাষ্ট্রের প্রতিরক্ষামন্ত্রী পিট হেগসেথ চলতি সপ্তাহের শুরুতে ইসরায়েলের নিরাপত্তা কর্মকর্তাদের সঙ্গে বৈঠক করেছেন বলে খবর প্রকাশিত হয়েছে। তবে এসব বৈঠকের পরও নতুন করে যুদ্ধ শুরুর আশঙ্কা কমেছে বলে মনে হচ্ছে না। গতকাল তেহরানে ইরানি রপ্তানিকারকদের এক সম্মেলনে পররাষ্ট্রমন্ত্রী আব্বাস আরাগচি বলেন, দেশটির ওপর নতুন করে হামলা এবং আরও কঠোর অর্থনৈতিক নিষেধাজ্ঞা আরোপের হুমকি রয়েছে।

আরাগচি বলেন, ‘বাস্তবতা হলো, ইরান এখন সত্যিকার অর্থেই যুদ্ধের মধ্যে আছে এবং যুদ্ধ চলছে। আমরা শান্তির পরিস্থিতিতে পৌঁছাইনি; বরং তা থেকে এখনো অনেক দূরে। তাই, সব সিদ্ধান্তই নিতে হবে যুদ্ধের পরিস্থিতি বিবেচনায় নিয়ে।’ ইরানের পার্লামেন্টের স্পিকার ও প্রধান মধ্যস্থতাকারী মোহাম্মদ বাঘের গালিবাফ পাকিস্তানের সেনাপ্রধান আসিম মুনিরকে বলেছেন, ইরানের কাছে যুক্তরাষ্ট্রকে বলার মতো নতুন কিছুই নেই। গত মাসে দেওয়া শর্তগুলো বাস্তবায়ন করতে হবে। ওই শর্ত মানলে সাত দিনের মধ্যে হরমুজ প্রণালি খুলে দেওয়া সম্ভব। চলতি সপ্তাহে ইরানের কাছে মধ্যস্থতাকারীরা কী প্রস্তাব দিয়েছেন, তা প্রকাশ্যে জানানো হয়নি। তবে তাঁদের বলা হয়েছে, ইরানের শর্ত মেনে নিয়ে যুক্তরাষ্ট্রকে আস্থা তৈরি করতে হবে। এসব শর্তের মধ্যে রয়েছে জুন মাসের সমঝোতা স্মারকে ফিরে যাওয়া এবং হরমুজ প্রণালি দিয়ে সাময়িকভাবে জাহাজ চলাচল নিয়ে ইরান ও ওমানের চুক্তিকে স্বীকৃতি দেওয়া।

পারমাণবিক কর্মসূচি নিয়ে বৃহত্তর সমঝোতার বিষয়ে অবিলম্বে আলোচনা শুরুর প্রতিশ্রুতিও ওই সমঝোতা স্মারকে ছিল। পাশাপাশি ইরানের বন্দরগুলোয় যুক্তরাষ্ট্রের নৌ অবরোধ তুলে নেওয়া, তেল রপ্তানির ওপর নিষেধাজ্ঞায় ছাড় দেওয়া, জব্দ করা ইরানি সম্পদ অবমুক্ত করা এবং লেবাননসহ মধ্যপ্রাচ্যের অন্যান্য সংঘাতপূর্ণ এলাকায় সামরিক অভিযান বন্ধ করার বিষয়ও এতে অন্তর্ভুক্ত ছিল। ইউরোপীয় কাউন্সিল অন ফরেন রিলেশনসের মধ্যপ্রাচ্য ও উত্তর আফ্রিকা কর্মসূচির জ্যেষ্ঠ নীতিবিষয়ক গবেষক ও উপপ্রধান এলি গেরানমায়েহ মনে করেন, নিষেধাজ্ঞা প্রত্যাহারের নিশ্চয়তা ছাড়া ইরান সমৃদ্ধ ইউরেনিয়াম ছাড়তে রাজি হবে না।

আল–জাজিরাকে এলি গেরানমায়েহ বলেন, ‘ইরানিরা স্পষ্ট করে দিয়েছে, উচ্চমাত্রায় সমৃদ্ধ ইউরেনিয়ামের ভবিষ্যৎ কিংবা আন্তর্জাতিক পর্যবেক্ষকদের প্রবেশাধিকার নিয়ে তারা আলোচনা করতে রাজি। কিন্তু এর সঙ্গে যুক্তরাষ্ট্রের নিষেধাজ্ঞা প্রত্যাহারের একটি সুস্পষ্ট বাস্তবায়ন প্রক্রিয়া সরাসরি যুক্ত থাকতে হবে। এ ধরনের আলোচনা শুরু হতে এখনো অনেক পথ বাকি।’

গত মঙ্গলবার মার্কিন সংবাদমাধ্যমগুলো দেশটির কয়েকজন কর্মকর্তার বরাত দিয়ে জানিয়েছে, পেন্টাগন ইউএসএস থিওডর রুজভেল্ট বিমানবাহী রণতরি ও একটি মেরিন ইউনিট মধ্যপ্রাচ্যে পাঠাচ্ছে। বিষয়টিকে ৩ নভেম্বর যুক্তরাষ্ট্রের মধ্যবর্তী নির্বাচনের পর ইরানে হামলা চালানোর প্রস্তুতি হিসেবে দেখা হচ্ছে। গত কয়েক সপ্তাহে ট্রাম্প ও তাঁর কর্মকর্তারা ইরানে সম্ভাব্য বিভিন্ন সামরিক অভিযানের বিষয় নিয়েও আলোচনা করেছেন। এর মধ্যে রয়েছে ইরানের পিক্যাক্স মাউন্টেন এলাকায় হামলা চালিয়ে পাহাড়ের ভেতরে থাকা পারমাণবিক স্থাপনা ক্ষতিগ্রস্ত করা এবং ‘মাদার অব অল বম্বস’ নামে পরিচিত শক্তিশালী বোমা নিক্ষেপ করা। এর আগে হরমুজ প্রণালির কাছে ইরানের দক্ষিণাঞ্চলীয় দ্বীপগুলো দখল এবং আরও ইরানি কর্মকর্তাকে হত্যার সম্ভাবনা নিয়েও আলোচনা হয়েছিল। ইরানের রাষ্ট্রীয় সংবাদমাধ্যম প্রেস টিভি গতকাল এক নিরাপত্তা কর্মকর্তার বরাত দিয়ে জানিয়েছে, যুক্তরাষ্ট্র ও ইসরায়েল আবার হামলা চালালে বা কাউকে হত্যা করলে তেহরানের নীতিনির্ধারকেরা কোনো সংযম না দেখিয়েই লড়াই চালিয়ে যাওয়ার সিদ্ধান্ত নিয়েছেন।', 'আল–জাজিরা', 'https://media.prothomalo.com/prothomalo-bangla/2026-09-05/6kmrpu16/uimage-2.jpg', 'https://www.prothomalo.com/world/middle-east/fgmnk4zake', '2026-10-22 12:09:12'),
(3, 'তথ্যের গোপনীয়তা নিয়ে বিভ্রান্তি, মেটাকে ২ হাজার ৫০০ কোটি ডলার জরিমানা', 'world/rx7bp02bzh', 'ব্যবহারকারীদের ব্যক্তিগত তথ্যের গোপনীয়তা ও ফেসবুকের নীতি সম্পর্কে বিভ্রান্তিকর তথ্য দেওয়ার দায়ে মেটাকে ২৫ বিলিয়ন (২ হাজার ৫০০ কোটি) ডলার জরিমানা দেওয়ার নির্দেশ দিয়েছেন যুক্তরাষ্ট্রের নিউ মেক্সিকোর এক বিচারক।', 'ব্যবহারকারীদের ব্যক্তিগত তথ্যের গোপনীয়তা নিয়ে বিভ্রান্ত করার দায়ে বুধবার মেটাকে ২৫ বিলিয়ন (২ হাজার ৫০০ কোটি) ডলার জরিমানা দেওয়ার নির্দেশ দিয়েছেন যুক্তরাষ্ট্রের নিউ মেক্সিকোর এক বিচারক। বড় কোনো প্রযুক্তিপ্রতিষ্ঠানকে সবচেয়ে বেশি জরিমানার ঘটনার মধ্যে এটি অন্যতম। নিউ মেক্সিকো কর্তৃপক্ষ ২০২১ সালে মেটার বিরুদ্ধে এ মামলা করেছিল। রাজনৈতিক পরামর্শক প্রতিষ্ঠান কেমব্রিজ অ্যানালিটিকার তথ্য ফাঁসের একটি বিতর্কিত ঘটনাকে কেন্দ্র করে মামলাটি করা হয়। মামলায় অভিযোগ করা হয়, ব্যবহারকারীদের তথ্যের ব্যবহার ও গোপনীয়তা এবং ফেসবুকের বিভিন্ন নীতি নিয়ে মেটা বিভ্রান্তিকর বক্তব্য দিয়েছিল।

দুই সপ্তাহের শুনানি শেষে গত মাসে সান্তা ফে স্টেট ডিস্ট্রিক্ট কোর্টের বিচারক মেটার বিরুদ্ধে আদেশ দেন। বিচারক বলেন, মেটা নিউ মেক্সিকোর ভোক্তা অধিকার সুরক্ষা আইন অন্তত ৪ কোটি ৩০ লাখ বার লঙ্ঘন করেছে। আইন অনুযায়ী, প্রতিটি লঙ্ঘনের জন্য সর্বোচ্চ ৫ হাজার ডলার পর্যন্ত জরিমানার বিধান রয়েছে। সান্তা ফে স্টেট ডিস্ট্রিক্ট কোর্টের বিচারক ফ্রান্সিস জে ম্যাথিউ বুধবার মেটাকে এই ঐতিহাসিক জরিমানা দেওয়ার নির্দেশ দেন।

আদালতের এই সিদ্ধান্ত ফেসবুক, ইনস্টাগ্রাম ও হোয়াটসঅ্যাপের মূল প্রতিষ্ঠান মেটার জন্য বড় একটি ধাক্কা। এসব প্ল্যাটফর্মের কারণে ব্যবহারকারীদের ক্ষতি হয়েছে—এমন অভিযোগে একের পর এক মামলায় হেরে মেটা এখন চাপে পড়েছে। বিভিন্ন অঙ্গরাজ্যের কর্তৃপক্ষ ও ব্যবহারকারীরা মেটার বিরুদ্ধে হাজারো মামলা করেছেন। এসব মামলায় ফেসবুক ও ইনস্টাগ্রামের মাধ্যমে শিশুদের নিরাপত্তা বিঘ্নিত করা, সামাজিক যোগাযোগমাধ্যমে আসক্তি বাড়ানো, বিনা অনুমতিতে মানুষের তথ্য ব্যবহার এবং গোপনীয়তা লঙ্ঘনের অভিযোগ আনা হয়।

বর্তমানে মেটার বিরুদ্ধে আইনি লড়াইয়ে নিউ মেক্সিকো নেতৃত্ব দিচ্ছে এবং উল্লেখযোগ্য সাফল্যও পেয়েছে। শিশু-কিশোরদের ক্ষতি করার জন্য আলাদা একটি মামলায় নিউ মেক্সিকোর এক বিচারক গত আগস্টে মেটাকে আরও ৫৬ কোটি ৭০ লাখ ডলার জরিমানা করেন। এর আগে গত মার্চে একই মামলায় মেটাকে ৩৭ কোটি ৫০ লাখ ডলার জরিমানা করা হয়েছিল।', 'নিউইয়র্ক টাইমস', 'https://media.prothomalo.com/prothomalo-bangla/2025-10-04/1phzs1xb/meta.jpg', 'https://www.prothomalo.com/world/rx7bp02bzh', '2026-10-22 02:45:37'),
(3, 'সাইবার হামলার শঙ্কায় বিশ্বজুড়ে বহু ওয়েবসাইট বন্ধ', 'world/48c8bk3g4s', 'সাইবার হামলার আশঙ্কায় সতর্কতামূলক ব্যবস্থা হিসেবে বিশ্বজুড়ে বিভিন্ন সরকারি সংস্থা ও প্রতিষ্ঠান তাদের ওয়েবসাইট সাময়িকভাবে বন্ধ রেখেছে।', 'সাইবার হামলার ঝুঁকি এড়াতে বিশ্বজুড়ে বিভিন্ন সরকারি সংস্থা ও বাণিজ্যিক প্রতিষ্ঠান তাদের ওয়েবসাইট সাময়িকভাবে বন্ধ রেখেছে। ওয়েবসাইট তৈরি ও পরিচালনায় বহুল ব্যবহৃত প্রোগ্রামিং ল্যাঙ্গুয়েজ পিএইচপিতে দুটি গুরুতর নিরাপত্তা ত্রুটি ধরা পড়ার পর এই সতর্কতা নেওয়া হয়েছে। এসব ত্রুটিকে সুযোগ হিসেবে কাজে লাগিয়ে সাইবার হামলাকারীরা কোনো পাসওয়ার্ড ছাড়াই সার্ভারে প্রবেশের সুযোগ পেতে পারে বলে বিশেষজ্ঞরা সতর্ক করেছেন। গত বুধবার পিএইচপি প্রকল্পের ডেভেলপাররা ত্রুটি সংশোধনের আপডেট প্রকাশ করেছেন। ব্যবহারকারীদের দ্রুত সেই আপডেট ইনস্টল করার পরামর্শ দেওয়া হয়েছে। অনেক জনপ্রিয় ওয়েবডিজাইন প্ল্যাটফর্মে পিএইচপি ব্যবহার করা হয়। ফলে এই নিরাপত্তা ত্রুটির কারণে অনলাইন মার্কেটপ্লেস, সংবাদমাধ্যম, সরকারি সেবাসহ বিভিন্ন ধরনের ওয়েবসাইট ঝুঁকির মুখে পড়তে পারে।

সাইবার নিরাপত্তা প্রতিষ্ঠান উইজও এসব ত্রুটি শনাক্ত করেছে। প্রতিষ্ঠানটির হিসাবে, বিশ্বের প্রায় ৭০ শতাংশ ওয়েবসাইটে পিএইচপি ব্যবহৃত হয়। উইজের ভাষ্য, পিএইচপিতে এ যাবৎ শনাক্ত হওয়া সবচেয়ে গুরুতর নিরাপত্তা ত্রুটি ধরা পড়ার ঘটনাগুলোর অন্যতম এটি। এমনকি সফটওয়্যারের ইতিহাসেও একে অন্যতম দুর্বলতা বলা যেতে পারে। যুক্তরাষ্ট্রের জাতীয় নিরাপত্তা সংস্থা (এনএসএ) সংশ্লিষ্ট প্রতিষ্ঠানগুলোকে দ্রুত নিরাপত্তা আপডেট করার পরামর্শ দিয়েছে। অবিলম্বে আপডেট করা সম্ভব না হলে ঝুঁকিপূর্ণ সিস্টেমে ইন্টারনেট সংযোগ বিচ্ছিন্ন রাখার পরামর্শ দিয়েছে তারা। সামাজিক যোগাযোগমাধ্যম এক্সে (সাবেক টুইটার) এক বিবৃতিতে এনএসএ জানিয়েছে, এসব ত্রুটি কাজে লাগিয়ে হামলাকারীরা সরাসরি সার্ভারের ফাইল বা ডেটাবেজে প্রবেশের সুযোগ পেতে পারে। তা ছাড়া হামলাকারীরা কোনো পাসওয়ার্ড ছাড়াই এসব দুর্বলতার সুযোগ নিয়ে সার্ভারের পূর্ণ নিয়ন্ত্রণ নিতে পারে। পিএইচপি ফাউন্ডেশনের নিরাপত্তা প্রকৌশলী ভলকার ডুশ ওয়াল স্ট্রিট জার্নালকে বলেছেন, গত এক দশকের বেশি সময়ের মধ্যে পিএইচপি এবারই সবচেয়ে গুরুতর নিরাপত্তা সমস্যার মুখে পড়েছে। তিনি এর সঙ্গে ২০১৪ সালের আলোচিত ‘হার্টব্লিড’ ত্রুটির তুলনা করেছেন। সে সময়ও বিশ্বজুড়ে সফটওয়্যার আপডেট করার হিড়িক পড়েছিল।

সাইবার নিরাপত্তা প্রতিষ্ঠান ‘ক্যালিফ’ গত আগস্টে ওপেনএআইয়ের তৈরি ‘জিপিটি-৫.৬ সল মডেল ব্যবহার করে এসব ত্রুটি খুঁজে পায়। ওপেনএআইয়ের অর্থায়নে পিএইচপির কোড পর্যালোচনার সময় তারা এটি শনাক্ত করেছিল। গুগলের মালিকানাধীন সাইবার নিরাপত্তা প্রতিষ্ঠান ‘উইজ’ বলেছে, কয়েক সপ্তাহ পর তারাও নিজস্ব উদ্যোগে এসব ত্রুটি শনাক্ত করে। এ কাজে তারা গুগলের ‘জেমিনি ৪ আর্গন’ ও ‘জিপিটি-৫.৬ সল’ মডেলের সাহায্য নিয়েছিল। ওপেনএআই এক্সে লিখেছে, তারা এটিকে সাম্প্রতিক সময়ের সবচেয়ে বড় নিরাপত্তা ত্রুটিগুলোর একটি হিসেবে বিবেচনা করছে। প্রতিষ্ঠানটি বলছে, এর মধ্য দিয়ে প্রযুক্তিতে নতুন এক ধাপ উন্মোচিত হলো। এখন পুরো ইন্টারনেটে প্রভাব ফেলতে পারে, এমন বড় ত্রুটিও এআই নিজে খুঁজে বের করতে পারছে। এ ত্রুটি সংশোধনের উদ্দেশ্যে পিএইচপি প্রকল্পের ডেভেলপাররা বুধবার একটি আপডেট প্রকাশ করেছেন। পিএইচপি ডেভেলপারদের তহবিল দেওয়া প্রতিষ্ঠান পিএইচপি ফাউন্ডেশন এক ব্লগ পোস্টে বলেছে, ‘আপনারা পিএইচপি ব্যবহার করলে এখনই আপডেট করা জরুরি।’

ফ্রান্সের স্বরাষ্ট্র মন্ত্রণালয় জানিয়েছে, দেশটির জাতীয় সাইবার নিরাপত্তা সংস্থার অনুরোধে স্থানীয় প্রশাসনের ওয়েবসাইটগুলো বুধবার বিকেল থেকে বন্ধ রাখা হয়েছে। এর মধ্যে প্যারিস পুলিশের ওয়েবসাইটও রয়েছে। নেদারল্যান্ডসের জাতীয় সম্প্রচারমাধ্যম এনওএস জানিয়েছে, দেশটির ডিজিটাল পরিচয় যাচাই সেবা ‘ডিজিডি’, প্রতিনিধি পরিষদের ওয়েবসাইট এবং জাতীয় সাইবার নিরাপত্তা কেন্দ্রের ওয়েবসাইট সতর্কতামূলক ব্যবস্থা হিসেবে অফলাইনে রাখা হয়েছে। বেলজিয়ামের পররাষ্ট্র মন্ত্রণালয় সতর্কতার অংশ হিসেবে সাময়িকভাবে তাদের ওয়েবসাইট বন্ধ রাখার কথা এক্সে জানিয়েছে। তবে দেশটির জাতীয় সাইবার নিরাপত্তা কেন্দ্র জানিয়েছে, তখন পর্যন্ত বেলজিয়ামের কোনো ওয়েবসাইটে হামলার তথ্য নথিভুক্ত হয়নি। অস্ট্রেলিয়ার জাতীয় সম্প্রচারমাধ্যম এবিসি জানিয়েছে, পিএইচপির ত্রুটি যেসব ওয়েবসাইট আক্রান্ত হয়েছে, সেগুলোর মধ্যে দেশটির সাইবার নিরাপত্তা সংস্থা অস্ট্রেলিয়ান সিগন্যালস ডিরেক্টরেটের নিজস্ব ওয়েবসাইট সাইবার ডট গভ ডট এইউ রয়েছে।', 'এএফপি', 'https://media.prothomalo.com/prothomalo-bangla/2026-10-21/dnz7bose/৩.avif', 'https://www.prothomalo.com/world/48c8bk3g4s', '2026-10-22 02:39:58'),
(3, 'মেলবোর্ন বিশ্ববিদ্যালয়ের স্কলারশিপ, মিলবে টিউশন ফি ও জীবনযাত্রার ভাতা', 'education/scholarship/q1exyyc9os', 'মেলবোর্ন গ্র্যাজুয়েট রিসার্চ স্কলারশিপের মাধ্যমে মেলবোর্ন বিশ্ববিদ্যালয়ে টিউশন ফি মওকুফসহ বিভিন্ন আর্থিক সুবিধা প্রদান করা হচ্ছে। আন্তর্জাতিক আবেদনকারীরা স্নাতকোত্তর ও পিএইচডি প্রোগ্রামে আবেদন করতে পারবেন।', 'অস্ট্রেলিয়ার মেলবোর্ন বিশ্ববিদ্যালয়ে গবেষণাভিত্তিক স্নাতকোত্তর ও পিএইচডি প্রোগ্রামে পড়ার সুযোগ দিচ্ছে মেলবোর্ন গ্র্যাজুয়েট রিসার্চ স্কলারশিপ। এ বৃত্তির আওতায় নির্বাচিত শিক্ষার্থীরা টিউশন ফি, জীবনযাত্রার ব্যয়, যাতায়াত ও স্বাস্থ্যবিমাসহ বিভিন্ন আর্থিক সুবিধা পাবেন।

মেলবোর্ন বিশ্ববিদ্যালয়ের বিভিন্ন অনুষদ ও গবেষণা ক্ষেত্রে এ বৃত্তির সুযোগ রয়েছে। এর মধ্যে আছে কলা, মানবিক ও সামাজিক বিজ্ঞান, কৃষি, স্থাপত্য, ব্যবসায় শিক্ষা, অর্থনীতি, প্রকৌশল, শিক্ষা, পরিবেশ, খাদ্যবিজ্ঞান, স্বাস্থ্য, কম্পিউটারবিজ্ঞান, তথ্যপ্রযুক্তি, আইন, চারুকলা ও পরিবেশনশিল্প, সংগীত, বিজ্ঞান এবং ভেটেরিনারি বিজ্ঞান।

জাতীয়তার ভিত্তিতে এ বৃত্তিতে আবেদনের ক্ষেত্রে কোনো বিধিনিষেধ নেই। অস্ট্রেলিয়ার নাগরিকদের পাশাপাশি বিশ্বের অন্যান্য দেশের শিক্ষার্থীরাও আবেদন করতে পারবেন। আবেদনকারীকে মেলবোর্ন বিশ্ববিদ্যালয়ের গবেষণাভিত্তিক স্নাতকোত্তর বা পিএইচডি প্রোগ্রামে ভর্তির জন্য আবেদন করতে হবে এবং সংশ্লিষ্ট প্রোগ্রামের যোগ্যতা পূরণ করতে হবে। আবেদনকারীর পূর্ববর্তী শিক্ষাগত যোগ্যতা ও গবেষণার সম্ভাবনা মূল্যায়ন করা হবে। স্নাতকোত্তর পর্যায়ে আবেদনের জন্য স্নাতক ডিগ্রি বা সমমানের যোগ্যতা এবং পিএইচডির জন্য প্রাসঙ্গিক স্নাতকোত্তর ডিগ্রি বা সমমানের যোগ্যতা প্রয়োজন হতে পারে। নির্দিষ্ট প্রোগ্রাম অনুযায়ী শিক্ষাগত ফলাফল ও অন্যান্য শর্ত ভিন্ন হতে পারে।

নির্বাচিত শিক্ষার্থীরা গবেষণাভিত্তিক স্নাতকোত্তর ডিগ্রির জন্য সর্বোচ্চ দুই বছর এবং পিএইচডির জন্য সর্বোচ্চ চার বছর পর্যন্ত টিউশন ফি মওকুফের সুবিধা পেতে পারেন। এ ছাড়া ২০২৬ সালের পূর্ণকালীন অধ্যয়নের হারে বছরে ৩৯ হাজার ৫০০ অস্ট্রেলীয় ডলার (প্রায় ৩৩ লাখ ৯৬ হাজার টাকা) পর্যন্ত জীবনযাত্রার ভাতা দেওয়ার কথা উল্লেখ করা হয়েছে।

শিক্ষাগত যোগ্যতার সনদ ও একাডেমিক ট্রান্সক্রিপ্ট হালনাগাদ জীবনবৃত্তান্ত (সিভি) দুটি সুপারিশপত্র গবেষণা প্রস্তাব, যদি সংশ্লিষ্ট বিভাগ চায় গবেষণার দক্ষতা তুলে ধরার জন্য প্রকাশিত প্রবন্ধ বা গবেষণাপত্র, যদি থাকে ইংরেজি ভাষায় দক্ষতার প্রমাণ, প্রযোজ্য ক্ষেত্রে নির্দিষ্ট প্রোগ্রামের জন্য প্রয়োজন হলে লেখার নমুনা, সৃজনশীল কাজের নমুনা অথবা জিআরই বা জিম্যাট পরীক্ষার ফলাফল

আবেদনের শেষ তারিখ ৩১ অক্টোবর ২০২৬। তবে কারণ গবেষণাভিত্তিক প্রোগ্রামে ভর্তির আবেদন ও বৃত্তির বিবেচনার নিয়ম প্রোগ্রামভেদে আলাদা হতে পারে। বিস্তারিত তথ্য ও আবেদনের জন্য ওয়েবসাইটে ভিজিট করুন।', 'তথ্যসূত্র:', 'https://media.prothomalo.com/prothomalo-bangla/2026-09-08/snc2k2qj/33.jpeg', 'https://www.prothomalo.com/education/scholarship/q1exyyc9os', '2026-10-21 08:24:02'),
(3, '‘পারিবারিক বন্ধু’ কেন এই হামলা করলেন, সেই রহস্য খুঁজছে পুলিশ', 'world/v9xgm73lts', 'অস্ট্রেলিয়ায় গাড়িচাপায় পা হারালেন নারী এমপি', 'অস্ট্রেলিয়ায় ফেডারেল পার্লামেন্টের স্বতন্ত্র নারী সদস্য (এমপি) হেলেন হেইন্সকে (৬৫) নিজের কার্যালয়ের সামনে গাড়িচাপা দিয়ে হত্যাচেষ্টার ঘটনায় সবচেয়ে বড় বিস্ময়ের জন্ম দিয়েছে হামলাকারীর পরিচয়। সন্দেহভাজন ওই হামলাকারী এমপির ২০ বছরের পুরোনো পারিবারিক বন্ধু। ঠিক কী কারণে দীর্ঘদিনের চেনা একজন মানুষ এমন ভয়াবহ হামলা চালালেন, এখন সে প্রশ্নেরই উত্তর খুঁজছে পুলিশ। গ্রেপ্তার ওই ব্যক্তির বাবা জানিয়েছেন, ওই এমপি তাঁদের পারিবারিক বন্ধু। ২০ বছরের পুরোনো এই সম্পর্ক। ৪৩ বছর বয়সী ব্রেন্ডন নিউজান্ট নামের ওই ব্যক্তি কেন এমন ভয়ংকর হামলা চালালেন, তা নিয়ে সবাই অবাক। কারণ, ব্রেন্ডন সব সময় এমপি হেলেনের কাজের প্রশংসা করতেন এবং তাঁকে দারুণ সমর্থন করতেন। পুলিশ তাঁকে একজন পরিবেশকর্মী হিসেবে শনাক্ত করেছে। ব্রেন্ডন মেলবোর্ন বিশ্ববিদ্যালয় থেকে পরিবেশবিজ্ঞানে স্নাতকোত্তর পাস করেছেন। তিনি এর আগে সামাজিক যোগাযোগমাধ্যমে ইসরায়েলকে সমর্থনের কারণে ব্রিটেনের সমালোচনা করেছিলেন। ইন্ডি আসনের স্বতন্ত্র এমপি হেলেন হেইন্স পরিবেশের পক্ষে কথা বলতেন এবং গাজায় ইসরায়েলি ধ্বংসযজ্ঞ নিয়ে অস্ট্রেলিয়া সরকারের নীরবতার নিন্দা জানাতেন। এসব কারণে ব্রেন্ডন আগে তাঁর প্রশংসাও করেছিলেন।

হেলেন এমপি হওয়ার পর ফেসবুকে সমর্থন জানিয়ে পোস্ট শেয়ার করেছিলেন ব্রেন্ডন। এমনকি তাঁর নির্বাচনী এলাকায় কনজারভেটিভ দলের অর্থায়নে হওয়া ‘স্বতন্ত্র-বিরোধী প্রচারণার’ সমালোচনা করে একটি পোস্ট এমপি হেলেনকেও ট্যাগ করেছিলেন তিনি। ব্রেন্ডনের বাবা রড নিউজান্ট একটি বিবৃতি প্রকাশ করে বলেছেন, তাঁর পরিবার ২০ বছর ধরে মিসেস হেইন্সের বন্ধু। তিনি এই ‘ভয়াবহ অপরাধের’ তদন্তে পুলিশকে সাহায্য করার প্রতিশ্রুতি দিয়েছেন। তিনি বলেন, কয়েক মাস ধরে ব্রেন্ডনের আচরণে অস্বাভাবিকতা দেখা যাচ্ছিল। রড নিউজান্ট বিবৃতিতে বলেন, ‘হেলেন হেইন্স আমাদের স্থানীয় সমাজের একজন গভীরভাবে সম্মানিত, মূল্যবান এবং অনেক প্রিয় সদস্য।’ তিনি বলেন, ‘হেলেন ২০ বছরের বেশি সময় ধরে আমাদের বন্ধু এবং গতকাল তাঁর সঙ্গে যা ঘটেছে, তা চরম ধ্বংসাত্মক এবং ভাবনার অতীত। আমাদের সব ভালোবাসা ও প্রার্থনা হেলেন এবং তাঁর পরিবার ও বন্ধুদের সঙ্গে রয়েছে।’ এত ভালো সম্পর্ক থাকা সত্ত্বেও কেন তিনি এই হামলা করলেন? মঙ্গলবার গোয়েন্দারা ব্রেন্ডনকে জিজ্ঞাসাবাদ করেছেন। তবে পুলিশ জানিয়েছে হামলার আসল উদ্দেশ্য এখনো অস্পষ্ট। পুলিশ ধারণা করছে, ব্রেন্ডনের মানসিক সমস্যা থাকতে পারে। তিনি সামাজিক মাধ্যমে ‘দীর্ঘস্থায়ী ব্যথায়’ ভোগার কথাও বলেছিলেন এবং জানিয়েছিলেন যে তিনি ‘নিঃস্ব’ বা আর্থিকভাবে কষ্টে আছেন। ধারণা করা হচ্ছে, পুলিশের জিজ্ঞাসাবাদের আগে ব্রেন্ডনকে একবার মানসিক স্বাস্থ্য পরীক্ষার মধ্য দিয়ে যেতে হবে।

অনলাইনে খুব রাগ দেখাতেন ব্রেন্ডন ব্রেন্ডন অনলাইনে রাজনীতি নিয়ে অনেক সরব ছিলেন। ২০২৪ সালের একটি পোস্টে গাজায় যুদ্ধ বন্ধের জন্য ইসরায়েলকে আহ্বান জানানোর পর তিনি সাবেক ব্রিটিশ প্রধানমন্ত্রী স্যার কিয়ার স্টারমারেরও সমালোচনা করেছিলেন। তিনি লিখেছিলেন, ‘ইসরায়েল যে রাফায় নির্দোষ মানুষের ওপর বোমা বর্ষণ করছে, তার একমাত্র কারণ হলো, আপনাদের মতো মানুষ তাদের এটা করার জন্য কূটনৈতিক ঢাল এবং সামরিক সহায়তা দেয়।’ আরেকটি পোস্টে ব্রেন্ডন অস্ট্রেলিয়ার পররাষ্ট্রমন্ত্রী পেনি ওংকে আক্রমণ করেন এবং তাঁর বিরুদ্ধে ‘হাজার হাজার শিশু হত্যার জন্য ইসরায়েলকে দায়মুক্তি দেওয়ার’ অভিযোগ তোলেন। এমপি হেলেনের চিন্তাভাবনাও ব্রেন্ডনের মতোই ছিল। একজন সাবেক ধাত্রী মিসেস হেইন্স স্বাস্থ্যবিষয়ক প্ল্যাটফর্মে প্রচার চালিয়েছিলেন এবং ২০১৯ সালে নির্বাচিত হওয়ার পর ‘শক্তিশালী পরিবেশ সুরক্ষার পক্ষে জোরালো কণ্ঠস্বর’ হওয়ার প্রতিশ্রুতি দিয়েছিলেন। পরিবেশ ধ্বংসকারীদের কঠোর শাস্তির বিধান রেখে অস্ট্রেলিয়ার সংরক্ষণ আইন সংস্কারের প্রস্তাবে হেইন্স সমর্থন জানিয়েছিলেন। এমনকি ফিলিস্তিনিদের দুর্দশা নিয়েও তিনি বারবার কথা বলেছেন।

ভয়ংকর সেই ঘটনা সোমবার মেলবোর্নের উত্তর-পূর্বে ওয়াঙ্গারাট্টায় নিজ নির্বাচনী কার্যালয়ের বাইরে হেলেন হেইন্সের ওপর ব্রেন্ডন নিউজান্ট তাঁর টয়োটা ল্যান্ড ক্রুজারটি দুবার তুলে দেন বলে অভিযোগ উঠেছে। হেইন্স তাঁর নির্বাচনী এলাকায় একটি ডগ পার্কের উদ্বোধনে অংশ নিয়েছিলেন। তিনি কার্যালয়ের বাইরে নিজের গাড়ির পেছন থেকে জিনিসপত্র নামাচ্ছিলেন, ঠিক সে সময় গাড়িটি তাঁর দিকে ধেয়ে আসে। প্রত্যক্ষদর্শীরা জানান, তাঁরা সাদা রঙের ল্যান্ড ক্রুজারটিকে ওয়াঙ্গারাট্টার পূর্বে ৪০০ মানুষের শহর টারাউইনগির প্রধান সড়কে ইউটার্ন নিতে দেখেন। এরপর এটি কার পার্কে ঢুকে তাঁকে (হেইন্স) ধাক্কা দেয় এবং পরে উল্টো দিকে (রিভার্স) গিয়ে তাঁকে দ্বিতীয়বার ধাক্কা দেয়। আরেকজন প্রত্যক্ষদর্শী সিডনি মর্নিং হেরাল্ডকে বলেছেন, তাঁরা গাড়িটিকে হেলেন হেইন্সকে কয়েকবার ধাক্কা দিতে দেখেছেন।

এই ভয়াবহ হামলার কারণে ৬৫ বছর বয়সী হেইন্সের একটি পা কেটে ফেলতে হয়েছে। মেলবোর্নের আলফ্রেড হাসপাতালে চিকিৎসকেরা তাঁর অন্য পা বাঁচানোর জন্য চেষ্টা চালিয়ে যাচ্ছেন। সাহায্য করতে এগিয়ে আসা পথচারীরা জানান, সন্দেহভাজন ওই ব্যক্তির কাছে একটি ছুরি ছিল এবং তাঁকে এলোমেলো কথা বলতে দেখা যায়। রিকি জেফরিস নামের একজন সেলুনকর্মী গাড়ির দিকে দৌড়ে যান। তিনি ব্রেন্ডনকে গাড়ি থেকে টেনে বের করেন এবং পুলিশ আসা পর্যন্ত তাঁকে শক্ত করে ধরে রাখেন। একটি দোকানের কর্মী কোডি লাপোইদেভিনও এ সময় দ্রুত এগিয়ে এসে তাঁকে সাহায্য করেন। জেফরিস বলেন, ‘তার কাছে একটি ছুরি ছিল। সে এটি বের করেনি। আমি তার নড়াচড়া দেখে ভরসা পাচ্ছিলাম না, তাই আমি কেবল তার পকেট থেকে ওটা বের করে ছুড়ে ফেলে দিই।’ পথচারীরা হেইন্সের পায়ে সাময়িক ব্যান্ডেজ লাগিয়ে দেন এবং পুলিশকে ডাকেন। কিছুক্ষণের মধ্যেই পুলিশ কর্মকর্তারা ব্রেন্ডনকে আটক করেন। হেইন্সকে প্রথমে স্থানীয় হাসপাতালে এবং পরে এয়ার অ্যাম্বুলেন্সে করে মেলবোর্নে উড়িয়ে নেওয়া হয়।', 'দ্য টেলিগ্রাফ', 'https://media.prothomalo.com/prothomalo-bangla/2026-10-20/j79he1sz/Aus-MP-Attacked-1.jpg', 'https://www.prothomalo.com/world/v9xgm73lts', '2026-10-20 23:34:42'),
(3, 'সরবরাহসংকটে বিশ্বজুড়ে খাদ্যের আরও মূল্যবৃদ্ধির আশঙ্কা বাড়ছে', 'world/p4makivpm2', NULL, 'বিশ্ববাজারে জ্বালানি তেলের অব্যাহত মূল্যবৃদ্ধি ঘটছে, যুদ্ধের কারণে পণ্য পরিবহন ব্যাহত হচ্ছে এবং এল নিনোর প্রভাবে খরায় শস্য উৎপাদন কমে গেছে। এসব কারণে আন্তর্জাতিক বাজারে খাদ্যের আরও মূল্যবৃদ্ধির আশঙ্কা দেখা দিয়েছে। বিশেষজ্ঞরা বলছেন, খাদ্যে মূল্যস্ফীতির এ ধারা আগামী মাসগুলোয় আরও তীব্র হতে পারে এবং তা ২০২৭ সাল পর্যন্ত স্থায়ী হতে পারে। ফলে এশিয়া, মধ্যপ্রাচ্য ও উত্তর আফ্রিকার নিম্ন ও মধ্যম আয়ের দেশগুলোর সাধারণ ভোক্তারা সবচেয়ে বেশি সংকটে পড়বেন। জাতিসংঘের খাদ্য ও কৃষি সংস্থার (এফএও) প্রধান অর্থনীতিবিদ মাক্সিমো তোরেরো বলেন, খাদ্য সরবরাহব্যবস্থার ওপর এখন বড় ধরনের চাপ তৈরি হয়েছে। চলতি বছরের শেষ দিকে, আগামী বছরের শুরুতে, এমনকি আগামী বছরজুড়েই এর বড় প্রভাব দেখা যাবে। মধ্যপ্রাচ্য, উত্তর আফ্রিকা ও এশিয়ার নিম্ন ও মধ্যম আয়ের দেশগুলোয় খাদ্যপণ্যের দাম দ্রুত বাড়ছে। এসব দেশের পরিবারগুলো আয়ের বড় অংশ খাবার কিনতে ব্যয় করে। ফলে মূল্যবৃদ্ধির সবচেয়ে বড় ধাক্কা সামলাতে হচ্ছে দরিদ্র মানুষকে। বিশ্বব্যাংক ১৫০টি দেশের তথ্য বিশ্লেষণ করে দেখেছে, এসব দেশের ২২ শতাংশ দেশে চলতি বছরের তৃতীয় প্রান্তিকে (জুলাই-সেপ্টেম্বর) খাদ্যপণ্যের মূল্যবৃদ্ধির হার সামগ্রিক মূল্যস্ফীতির চেয়ে বেশি ছিল। আগের প্রান্তিকে (এপ্রিল-জুলাই) এ হার ছিল ১৪ শতাংশ। বিশ্বব্যাংকের তথ্য অনুযায়ী, খাদ্যপণ্যের মূল্যবৃদ্ধির এ গতি অনেক দেশে সাধারণ মূল্যস্ফীতিকে ছাড়িয়ে গেছে। গত সেপ্টেম্বরে খাদ্যপণ্যের বৈশ্বিক মূল্যসূচক বেড়ে গড়ে ১৩৬ পয়েন্টে পৌঁছেছে, যা ২০২২ সালের নভেম্বরের পর সর্বোচ্চ। খাদ্যপণ্যের দাম বাড়লে সামাজিক অস্থিরতার ঝুঁকি তৈরি হয়। পরিস্থিতি সামাল দিতে প্রধান খাদ্য রপ্তানিকারক দেশগুলো রপ্তানিতে নিষেধাজ্ঞা দিতে পারে। এতে বাজারে সরবরাহ আরও কমে যাওয়ার আশঙ্কা রয়েছে।

বহুমাত্রিক সরবরাহসংকট কৃষ্ণসাগর অঞ্চলে শস্য রপ্তানিসংশ্লিষ্ট অবকাঠামোতে হামলার কারণে বিশ্বজুড়ে গম সরবরাহ ব্যাহত হচ্ছে। ফলে মিসর ও ইন্দোনেশিয়ার মতো বড় আমদানিকারক দেশগুলো বিকল্প বাজার খুঁজতে বাধ্য হচ্ছে। লোহিত সাগরে নিরাপত্তাহীনতার কারণে পণ্যবাহী জাহাজগুলোকে আফ্রিকা ঘুরে দীর্ঘ ও ব্যয়বহুল পথ ব্যবহার করতে হচ্ছে। যুক্তরাষ্ট্র ও ইসরায়েল ইরানে যুদ্ধ চালিয়ে যাওয়ায় বিশ্ববাজারে অব্যাহতভাবে বাড়ছে জ্বালানির দাম। হরমুজ প্রণালি দিয়ে সার রপ্তানিও ব্যাহত হচ্ছে। এতে কৃষি উৎপাদনের খরচ বাড়ছে। অন্যদিকে, এল নিনোর প্রভাবে শুষ্ক আবহাওয়ার কারণে ভারত ও দক্ষিণ-পূর্ব এশিয়ায় ফসলের উৎপাদন কমে যাচ্ছে। চলতি বছর বিশ্ববাজারে গমের দাম আগের বছরের তুলনায় ৩০ শতাংশের বেশি বেড়েছে। এশিয়ার প্রধান রপ্তানিকারক দেশগুলোয় চালের পর্যাপ্ত মজুত থাকা সত্ত্বেও দাম বেড়েছে ১০ থেকে ১৩ শতাংশ। ইরান যুদ্ধের শুরুর দিকে সারের দাম সর্বোচ্চ পর্যায়ে উঠেছিল। সেখান থেকে কিছুটা কমলেও দাম এখনো বেশি। নেসলে ইন্ডিয়ার চেয়ারম্যান ও ব্যবস্থাপনা পরিচালক মনীশ তিওয়ারি বলেন, পণ্যের বাড়তি দামের কারণে ব্যবসার পরিবেশ কঠিন হয়ে উঠেছে। বিশেষ করে খাদ্যপণ্যের মূল্যস্ফীতি এখন এক কঠিন বাস্তবতার নাম।

মিসরে ভর্তুকি ছাড়া বড় আকারের একেকটি রুটির দাম জুলাইয়ের ৪ মিসরীয় পাউন্ড থেকে বেড়ে এখন প্রায় ৫ পাউন্ড হয়েছে। সংযুক্ত আরব আমিরাতে রান্নার তেলের দাম বেড়েছে প্রায় ৪০ শতাংশ। বিশ্বের সবচেয়ে বড় পাম তেল উৎপাদক দেশ ইন্দোনেশিয়াতেও এ বছর ভোজ্যতেলের দাম বেড়েছে ৭ শতাংশ। ভারতে উৎপাদন কমে যাওয়ায় সেপ্টেম্বরে চিনি, পেঁয়াজ ও ডালের দাম আগের মাসের তুলনায় ১০ শতাংশের বেশি বেড়েছে। মিসরের রাজধানী কায়রোর কেন্দ্রস্থলে বেকারি চালান সাঈদ আবদেল হামিদ মোহাম্মদ। তাঁর ভাষ্য, শুধু ময়দার দামই বাড়েনি। তিনি বলেন, দক্ষ শ্রমিক নিয়োগ দিতেও এখন অনেক টাকা খরচ হয়। বিদ্যুৎ, পানি, ইস্ট ও রুটি তৈরিতে ব্যবহৃত সব উপকরণের দাম বেড়েছে। জ্বালানি তেলের মূল্যবৃদ্ধি ও যুদ্ধের কারণে পরিবহন খরচও বেড়েছে। কৃষ্ণসাগর থেকে দক্ষিণ-পূর্ব এশিয়ায় পণ্য পৌঁছে দিতে গুরুত্বপূর্ণ কয়েকটি আন্তর্জাতিক নৌপথে পণ্য পরিবহনের ভাড়া প্রায় ৫০ শতাংশ বেড়েছে।

মূল্যস্ফীতি আরও বৃদ্ধির শঙ্কা ২০২৫ সালের শেষ দিক থেকেই খাদ্যপণ্যের দাম বাড়ছিল। এখন স্থানীয় বাজারে সরবরাহ কমে আসা এবং উৎপাদন ব্যয় বৃদ্ধির প্রভাব ভোক্তাদের ওপর পড়তে থাকায় মূল্যস্ফীতি আরও দ্রুত বৃদ্ধির আশঙ্কা তৈরি হয়েছে। মধ্যপ্রাচ্য ও আফ্রিকার কয়েকটি বড় আমদানিকারক দেশ স্থানীয়ভাবে ভালো ফসল উৎপাদিত হওয়ায় এত দিন আন্তর্জাতিক বাজার থেকে খাদ্যপণ্য কেনা কমিয়ে রেখেছিল। এখন তাদের আবার বিশ্ববাজারে ফিরতে হবে। এতে আন্তর্জাতিক বাজারে চাহিদা হঠাৎ বেড়ে যেতে পারে। লন্ডনভিত্তিক আন্তর্জাতিক শস্য কাউন্সিলের জ্যেষ্ঠ অর্থনীতিবিদ আলেক্সান্ডার কারাভাইতসেভ বলেন, কয়েক মাসের মধ্যে আমদানিকারকেরা বাজারে ফিরলে চাহিদার নতুন ঢেউ তৈরি হতে পারে। এফএওর তোরেরো বলেন, বিশ্বজুড়ে শস্যের রেকর্ড মজুত এত দিন বাজারকে কিছুটা সুরক্ষা দিয়েছে। তবে সে সুরক্ষা ক্রমেই কমে আসছে। খাদ্য প্রক্রিয়াজাতকারী প্রতিষ্ঠানগুলো সাধারণত তিন থেকে ছয় মাসের চুক্তিতে কাঁচামাল কেনে। এখন এসব চুক্তি নবায়ন করতে গিয়ে তাদের বেশি দাম দিতে হচ্ছে। স্থানীয় মুদ্রার মান কমে যাওয়ায় আমদানির খরচ আরও বাড়ছে।

ইন্দোনেশিয়ার সবচেয়ে বড় খাদ্য কোম্পানি পিটি ইন্দোফুডের পরিচালক ফ্রান্সিসকুস ওয়েলিরাং বলেন, পণ্য পরিবহনের খরচও বেড়েছে। ইন্দোনেশিয়ার মুদ্রা রুপিয়ার মান কমে যাওয়ায় রুপিয়ায় হিসাব করলে এ ব্যয়ের প্রভাব আরও বেশি হচ্ছে। ব্যবসায়ীরা জানিয়েছেন, বেশি দাম দেওয়ার পাশাপাশি খাদ্য প্রক্রিয়াজাতকারী প্রতিষ্ঠানগুলো প্রয়োজনীয় কাঁচামাল সংগ্রহ করতেও সমস্যায় পড়ছে। জাকার্তার একটি আটা উৎপাদনকারী প্রতিষ্ঠানের এক জ্যেষ্ঠ কর্মকর্তা নাম প্রকাশ না করার শর্তে বলেন, রাশিয়া-ইউক্রেন যুদ্ধের কারণে গমের চালান কমে যাওয়ায় ইন্দোনেশিয়ার কয়েকটি গমকল তাদের উৎপাদনক্ষমতার চেয়ে কম উৎপাদন করছে। গবেষণা প্রতিষ্ঠান কেপলারের তথ্য অনুযায়ী, ইন্দোনেশিয়ায় সেপ্টেম্বরে গম আমদানি আগের বছরের একই সময়ের তুলনায় ৪১ শতাংশ কমে ৪ লাখ ৯১ হাজার টনে দাঁড়িয়েছে। তবে আপাতত সয়াবিন ও ভুট্টার পর্যাপ্ত মজুত রয়েছে। ভবিষ্যতে এ দুটি শস্যের সরবরাহ নির্ভর করবে যুক্তরাষ্ট্র ও দক্ষিণ আমেরিকার উৎপাদনের ওপর। জৈব জ্বালানি তৈরিতে এসব শস্যের ব্যবহার বেড়েছে।', 'রয়টার্স', 'https://media.prothomalo.com/prothomalo-bangla/2026-10-19/4dmuucjc/uimage-8.jpg', 'https://www.prothomalo.com/world/p4makivpm2', '2026-10-19 18:17:16'),
(3, 'কানাডায় সামরিক ঘাঁটিতে ভয়াবহ আগুন, অনেকে হতাহত, প্রকৃত ঘটনা নিয়ে ধোঁয়াশা', 'world/nhmztbecj5', 'এডমন্টন শহরের একটি হাসপাতালের একজন চিকিৎসক বলেছেন, চিকিৎসা নিতে আসা রোগীর সংখ্যা এত বেশি যে এখানকার স্বাস্থ্যসেবা ব্যবস্থা পুরোপুরি চাপের মুখে পড়েছে।', 'কানাডার পশ্চিমাঞ্চলের একটি সামরিক ঘাঁটিতে গতকাল শনিবার বড় ধরনের আগুন ছড়িয়ে পড়েছে। এতে বেশ কয়েকজন হতাহত হওয়ার খবর নিশ্চিত করেছে দেশটির সরকার। কানাডার প্রধানমন্ত্রী মার্ক কার্নি সামাজিক যোগাযোগমাধ্যম এক্সে দেওয়া এক পোস্টে বলেন, পশ্চিমাঞ্চলীয় আলবার্টা প্রদেশে ‘কানাডিয়ান ফোর্সেস বেজ ওয়েনরাইট’ ঘাঁটিতে ‘একটি গুরুতর ঘটনায় বড় ধরনের আগুন ছড়িয়ে পড়েছে’। এ ঘটনায় বেশ কয়েকজন হতাহত হয়েছেন বলে এক সংবাদ সম্মেলনে জানান কানাডার প্রতিরক্ষামন্ত্রী ডেভিড ম্যাকগিনটি।

অটোয়ায় সাংবাদিকদের ডেভিড ম্যাকগিনটি বলেন, ‘দুঃখের সঙ্গে জানাচ্ছি, কানাডিয়ান ফোর্সেস বেজ ওয়েনরাইটে এক ঘটনায় কয়েকজন নিহত ও আহত হয়েছেন।’

তবে ঠিক কতজন হতাহত হয়েছেন বা কী ধরনের ঘটনা ঘটেছে, কী কারণে ঘটেছে, সেসব বিষয়ে প্রধানমন্ত্রী ও প্রতিরক্ষামন্ত্রীর কেউ কোনো তথ্য দেননি। ম্যাকগিনটি বলেন, ‘আগামী কয়েক ঘণ্টায় এবং কয়েক দিনে এ বিষয়ে আমরা আরও বিস্তারিত জানাব।’ তবে সামরিক বাহিনীর সূত্রের বরাতে কানাডার টেলিভিশন নেটওয়ার্ক গ্লোবাল নিউজ জানিয়েছে, এ ঘটনায় অন্তত সাতজন নিহত এবং আরও বেশ কয়েকজন আহত হয়েছেন। তাজা গুলি ছোড়ার প্রশিক্ষণ চলাকালে গুলি গ্যাসের পাইপলাইন বা গ্যাসকূপে আঘাত হানলে অগ্নিকাণ্ডের সূত্রপাত হয়। ঘাঁটি থেকে প্রায় ২০০ কিলোমিটার উত্তর-পশ্চিমে এডমন্টন শহরের একটি হাসপাতালের একজন চিকিৎসক কানাডার সরকারি সম্প্রচারমাধ্যম সিবিসিকে বলেন, চিকিৎসা নিতে আসা রোগীর সংখ্যা এত বেশি যে ওয়েনরাইটের স্বাস্থ্যসেবার ব্যবস্থা ‘পুরোপুরি চাপের মুখে পড়েছে’।

চিকিৎসক ওয়ারেন থার্স্ক বলেন, ‘এ মুহূর্তে আমাদের যে কারও ধারণার চেয়ে অনেক বেশি রোগী এসেছে। ১৫ থেকে ২৫ বছরে এমন ঘটনা একবারই ঘটে।’ ওয়েনরাইটের স্থানীয় কর্তৃপক্ষ সামাজিক যোগাযোগমাধ্যমে জানায়, প্রবল বাতাসে আগুন দ্রুত ছড়িয়ে পড়ে।

গতকালই ‘আগুন নিয়ন্ত্রণে থাকার’ কথা জানায় স্থানীয় কর্তৃপক্ষ। তবে অগ্নিনির্বাপক বাহিনীর কর্মীরা এলাকাটি এখনো পর্যবেক্ষণ করছেন। মার্ক কার্নি বলেন, সরকার আলবার্টার প্রাদেশিক কর্তৃপক্ষ ও স্থানীয় প্রশাসনের সঙ্গে ঘনিষ্ঠভাবে কাজ করছে। তিনি এক্সে বলেন, ‘এ ঘটনায় ক্ষতিগ্রস্ত সব নারী-পুরুষের প্রতি আমাদের সমবেদনা।’

আলবার্টার প্রাদেশিক নির্বাচন পরিচালনার দায়িত্বে থাকা দপ্তর জানিয়েছে, ওয়েনরাইটের আগাম ভোটকেন্দ্র বন্ধ করে দেওয়া হয়েছে। ২০২১ সালের আদমশুমারির তথ্য অনুযায়ী, কানাডিয়ান ফোর্সেস বেজ ওয়েনরাইটে সামরিক ও বেসামরিক মিলিয়ে ১ হাজার ৩১০ জন কর্মী ছিলেন। ঘাঁটির ঠিক উত্তরে ওয়েনরাইট শহরের অবস্থান। শহরটির জনসংখ্যা প্রায় ৬ হাজার ৬০০।', 'এএফপি', 'https://media.prothomalo.com/prothomalo-bangla/2026-10-18/5kci53x7/canada-alberta-fire.jpg', 'https://www.prothomalo.com/world/nhmztbecj5', '2026-10-18 14:35:04'),
(4, 'রাজধানীতে উচ্চ মূল্যে বিক্রি 
হচ্ছে ব্রয়লার মুরগি ও ডিম', 'business/gd6h13wfee', 'বাজার ঘুরে দেখা যায়, বর্তমানে খুচরা পর্যায়ে প্রতি কেজি ব্রয়লার মুরগি ১৯০ থেকে ২০০ টাকায় বিক্রি হচ্ছে। আর সোনালি মুরগি বিক্রি হচ্ছে ৩২০-৩৫০ টাকা কেজি।', 'প্রায় তিন মাস ধরে বাজারে উচ্চ মূল্যে বিক্রি হচ্ছে ব্রয়লার মুরগি ও ডিম। সরবরাহ মোটামুটি ঠিক থাকলেও দাম কমছে না। সম্প্রতি সরু চালের দাম কেজিতে ২ টাকা ও পেঁয়াজের দাম কেজিতে ৫ টাকার মতো বৃদ্ধি পেয়েছে। এ দিকে দুর্গাপূজা উপলক্ষে টানা পাঁচ দিনের ছুটি চলছে। ছুটি কাটাতে অনেক মানুষ ঢাকা ছেড়েছেন। এতে বাজারে ক্রেতার উপস্থিতি কিছুটা কম। গতকাল বৃহস্পতিবার রাজধানীর মোহাম্মদপুর কৃষি মার্কেট, টাউন হল বাজার ও তেজতুরী বাজার ঘুরে এবং ক্রেতা-বিক্রেতাদের সঙ্গে কথা বলে এসব তথ্য জানা গেছে।

বাজার ঘুরে দেখা যায়, বর্তমানে খুচরা পর্যায়ে প্রতি কেজি ব্রয়লার মুরগি ১৯০ থেকে ২০০ টাকায় বিক্রি হচ্ছে। আর সোনালি মুরগি বিক্রি হচ্ছে ৩২০-৩৫০ টাকা কেজি। এ ছাড়া ফার্মের মুরগির বাদামি রঙের এক ডজন ডিমের দাম ১৫০ টাকার আশপাশে। বিক্রেতারা জানান, গত কয়েক মাসের মধ্যে একাধিকবার মুরগির খাদ্যের দাম, বিদ্যুৎ বিল, গাড়িভাড়া প্রভৃতি খরচ বেড়েছে। এ কারণে মুরগি ও ডিমের দাম কমছে না। গত এক মাসের মধ্যে বাজারে সাবান, ডিটারজেন্টের মতো বেশ কিছু মোড়কজাত পণ্যের দামও বেড়েছে; কোনো কোনো পণ্যের ওজন কমেছে। যেমন পরিচিত একটি ব্র্যান্ডের ১ কেজির ডিটারজেন্টের প্যাকেটের দাম এ মাসের শুরুতে ছিল ১৯৫ টাকা, যা গতকাল ২২০ টাকায় বিক্রি হয়েছে। মাসখানেক আগে ১০০ গ্রাম ওজনের বহুল ব্যবহৃত একটি গায়ে মাখা সাবানের দাম ছিল ৫৫ টাকা। এখন সেই সাবানের ওজন কমিয়ে ৯০ গ্রাম করা হয়েছে, সেই সঙ্গে দাম বাড়িয়ে করা হয়েছে ৬৫ টাকা।

রাজধানীর মোহাম্মদপুরের বাসিন্দা সোহেল মিয়া বলেন, ‘বিভিন্ন মোড়কজাত পণ্যের দাম লাফিয়ে লাফিয়ে বাড়ছে। বাজার খরচের বড় একটি অংশই চলে যায় এই বাড়তি ব্যয় সামলাতে।’', 'নিজস্ব প্রতিবেদক', 'https://media.prothomalo.com/prothomalo-bangla/2024-09-16/kksf23ly/WhatsApp-Image-2024-09-16-at-6.34.11-PM.jpeg', 'https://www.prothomalo.com/business/gd6h13wfee', '2026-10-23 15:55:00'),
(4, 'টানা দুই দিনে সোনার দাম কমল 
ভরিতে ৩ হাজার ৮৪৯ টাকা', 'business/87b7sxysl3', NULL, 'দেশের বাজারে টানা দুই দিন সোনার দাম কমল। আজ শুক্রবার ভরিতে কমেছে সর্বোচ্চ ২ হাজার ১৫৮ টাকা। গতকাল বৃহস্পতিবার সোনার দাম কমেছিল ভরিতে ১ হাজার ৬৯১ টাকা। তার মানে দুই দিনে সোনার দাম কমল ভরিতে সর্বোচ্চ ৩ হাজার ৮৪৯ টাকা। বাংলাদেশ জুয়েলার্স সমিতি আজ সকালে সোনার দাম কমার বিষয়টি জানিয়েছে। বলা হয়, দেশের বাজারে তেজাবি সোনার দাম কমেছে। তাই সোনার দাম সমন্বয় করা হয়েছে। তবে বৈশ্বিক বাজারে সোনার দরপতনই হচ্ছে মূল কারণ। আজ সকাল ১০টায় সোনার নতুন দর কার্যকর হয়েছে।

নতুন দর অনুযায়ী, আজ ২২ ক্যারেটের এক ভরি সোনার দাম ২ হাজার ১৫৮ টাকা কমে হয়েছে ২ লাখ ২৪ হাজার ১৮২ টাকা। এ ছাড়া ২১ ক্যারেটের দাম ভরিতে ২ হাজার ১০০ টাকা কমে দাঁড়িয়েছে ২ লাখ ১৪ হাজার ৯৩ টাকা। এদিকে ১৮ ক্যারটের সোনার দাম ভরিতে ১ হাজার ৮০৮ টাকা কমে হয়েছে ১ লাখ ৮৩ হাজার ৮৮৩ টাকা। আর সনাতন পদ্ধতির সোনার দাম ১ হাজার ৪৫৮ টাকা কমে দাঁড়িয়েছে ১ লাখ ৫০ হাজার ২৩২ টাকা।

সোনার পাশাপাশি রুপার দামও কিছুটা কমেছে। ২২ ক্যারেটের এক ভরি রুপার দাম ভরিতে ১৭৫ টাকা কমে ৩ হাজার ৮৪৯ টাকা হয়েছে। এ ছাড়া ২১ ক্যারেটের রুপার দাম ভরিতে ১৭৫ টাকা কমে দাঁড়িয়েছে ৩ হাজার ৬৭৪ টাকা। সোনা ও রুপার দামের সঙ্গে মূল্য সংযোজন কর বা ভ্যাট যুক্ত রয়েছে।', 'নিজস্ব প্রতিবেদক', 'https://media.prothomalo.com/prothomalo-bangla/2026-04-29/2sp02mqn/gold-slump.jpeg', 'https://www.prothomalo.com/business/87b7sxysl3', '2026-10-23 12:13:31'),
(4, 'বন্ড সুবিধায় সুতা আমদানির নিষেধাজ্ঞা 
প্রত্যাহারে প্রধানমন্ত্রীর সহায়তা চান 
পোশাকশিল্পের মালিকেরা', 'business/udhberocc6', NULL, 'বন্ড সুবিধায় ১০–৩০ কাউন্টের কটন বা তুলার তৈরি সুতা আমদানির ওপর নিষেধাজ্ঞা প্রত্যাহারে এবার প্রধানমন্ত্রী তারেক রহমানের সহায়তা চাইলেন তৈরি পোশাকশিল্প মালিকেরা। তাঁরা বলেছেন, সুতা আমদানিতে বন্ড সুবিধা প্রত্যাহারের সিদ্ধান্তে রপ্তানিমুখী তৈরি পোশাকশিল্পের জন্য একটি সংকটময় পরিস্থিতি তৈরি করেছে। এই সিদ্ধান্তে পোশাক খাতের কাঁচামাল আমদানিতে অনিশ্চয়তা, উৎপাদন ব্যয় বৃদ্ধি, সরবরাহ ব্যবস্থায় বিঘ্ন এবং আন্তর্জাতিক বাজারে বাংলাদেশের প্রতিযোগিতা সক্ষমতা ক্ষতিগ্রস্ত হওয়ার আশঙ্কা দিয়েছে। ইতিমধ্যে বিদেশি ক্রেতারা ভারত ও মিসরের মতো দেশে তৈরি পোশাকের ক্রয়াদেশ স্থানান্তর করছে। গতকাল বৃহস্পতিবার প্রধানমন্ত্রীর কার্যালয়ে পাঠানো এক চিঠিতে বন্ড সুবিধায় সুতা আমদানির নিষেধাজ্ঞা প্রত্যাহারের অনুরোধ করেছে তৈরি পোশাকশিল্প মালিকদের সংগঠন বিজিএমইএ ও নিট পোশাকশিল্প মালিকদের সংগঠন বিকেএমইএ। সংগঠন দুইটির সভাপতি অর্থাৎ বিজিএমইএর সভাপতি মাহমুদ হাসান খান ও বিকেএমইএর সভাপতি মোহাম্মদ হাতেম যৌথভাবে এই চিঠি দিয়েছেন।

গত বছর স্থলপথে সুতা আমদানি বন্ধ, সুতা আমদানির ওপর সেফগার্ড ডিউটি আরোপের জন্য দুই তৎপরতা চালানো, ২০২৬–২৯ সালের আমদানিতে নীতিতে নিট কাপড় আমদানি নিষিদ্ধ ও পরে প্রত্যাহার—ঘন ঘন এ ধরনের নীতি পরিবর্তনের কারণে ক্রেতাদের আস্থা নষ্ট হচ্ছে বলে উল্লেখ করেন বিজিএমইএ ও বিকেএমইএর সভাপতি। তাঁরা বলেন, ‘নীতি অনিশ্চয়তা বাংলাদেশের ব্যবসায়িক পরিবেশের ধারাবাহিকতা নিয়ে আন্তর্জাতিক ক্রেতাদের মধ্যে উদ্বেগ বৃদ্ধি করে বলে প্রতিয়মান হয়। ক্রেতারা ইতিমধ্যে ভারত ও মিসরে তাদের ক্রয়াদেশ স্থানান্তর করছে বলে আমরা অবগত হয়েছি।’ প্রধানমন্ত্রীকে দেওয়া চিঠিতে বিজিএমইএ ও বিকেএমইএর সভাপতি অভিযোগ করে বলেছেন, গত ২০ আগস্ট বাণিজ্য মন্ত্রণালয়ে বস্ত্র ও পোশাক খাতসংক্রান্ত এক সভা হয়। এতে নির্ধারিত আলোচ্যসূচির বাইরে বস্ত্রকল মালিকদের সংগঠন বিটিএমএর প্রতিনিধিরা ১০–৩০ কাউন্টের কটন সুতা আমদানির বন্ড সুবিধা প্রত্যাহারের বিষয়টি উত্থাপন করেন। সভায় এ বিষয়ে কোনো সিদ্ধান্ত না হলেও সভার কার্যবিবরণীতে কটন সুতা আমদানিতে বন্ড সুবিধা প্রত্যাহার এবং ব্যাংক গ্যারান্টি দিয়ে আমদানির অনুমতি বিষয়ে সিদ্ধান্ত আকারে যুক্ত করা হয়। পরে ওই কার্যবিবরণীর ভিত্তিতে ৭ সেপ্টেম্বর জাতীয় রাজস্ব বোর্ড (এনবিআর) কটন সুতা আমদানিতে বন্ড সুবিধা প্রত্যাহার এবং ব্যাংক গ্যারান্টির মাধ্যমে আমদানির আদেশ জারি করে।

চিঠিতে আরও বলা হয়, পরে তৈরি পোশাকশিল্পের মালিকদের অনুরোধে বাণিজ্য মন্ত্রণালয় ১৩ সেপ্টেম্বর সুতা আমদানিতে বন্ড সুবিধা বাতিলের সিদ্ধান্ত স্থগিত করার জন্য এনবিআরকে চিঠি পাঠায়। তবে সেই আদেশ প্রত্যাহার করেনি এনবিআর। উল্টো গত বুধবার সংস্থাটি অনুরূপ আরেকটি আদেশ জারি করে। এর ফলে রপ্তানি কার্যক্রমে অনিশ্চয়তা তৈরি হয়েছে। এবং তৈরি পোশাকশিল্পের কাঁচামাল সরবরাহ বিপর্যন্ত হয়েছে বলে দাবি করেছে বিজিএমইএ ও বিকেএমইএ। বিজিএমইএ ও বিকেএমইএর অভিযোগ করে বলেছে, এনবিআরের আদেশের পর স্থানীয় স্পিনিং মিলগুলো সুতার দাম প্রতি পাউন্ডে ৩০–৫০ সেন্ট বৃদ্ধি করেছে। অন্যদিকে আমদানি করা সুতার ক্ষেত্রে শুল্ক ও কর পরিশোধ অথবা ব্যাংক গ্যারান্টি দেওয়ার কারণে রপ্তানিকারকদের চলতি মূলধন আটকে যাচ্ছে। এতে সামগ্রিকভাবে ব্যয় বেড়ে যাচ্ছে। নিট পোশাক খাত সম্পূর্ণভাবে প্রতিযোগিতা সক্ষমতা হারিয়ে ফেলছে। বিশেষ করে ক্ষুদ্র ও মাঝারি রপ্তানিকারক প্রতিষ্ঠানগুলোতে এটি অতিরিক্ত তারল্যসংকট সৃষ্টি করছে, যা সরবরাহ শৃঙ্খল ধরে রাখা এবং উৎপাদন কার্যক্রম অব্যাহত রাখার ক্ষেত্রে বড় হুমকি হয়ে দাঁড়িয়েছে।

বিজিএমইএ ও বিকেএমইএর সভাপতি এনবিআরের জারি করা আদেশটি অবিলম্বে ও নিঃশর্তভাবে প্রত্যাহার করতে প্রধানমন্ত্রীকে অনুরোধ করেন। একই সঙ্গে তাঁরা বলেন, এলডিসি থেকে উত্তরণ পর্যন্ত এ ধরনের সিদ্ধান্ত নেওয়া থেকে বিরত থাকা উচিত। তবে আদেশটি প্রত্যাহারের পর বিজিএমইএ, বিকেএমইএ ও বিটিএমএর মধ্যে আলোচনার ভিত্তিতে একটি টেকসই নীতিকাঠামো প্রণয়ন করা যেতে পারে।', 'নিজস্ব প্রতিবেদক', 'https://media.prothomalo.com/prothomalo-bangla/2026-09-05/5ilzfp2r/BGMEA.jpg', 'https://www.prothomalo.com/business/udhberocc6', '2026-10-16 19:36:24'),
(4, '৮০ টাকার নিচে শুধু পেঁপে আর কুমড়া, সব সবজির দামই চড়া', 'business/dnv2x7vq2x', 'বাজারদর', 'শীত মৌসুম আসার আগে বাজারে সব ধরনের সবজির দাম বাড়তি। পেঁপে ও মিষ্টিকুমড়া ছাড়া আর কোনো সবজিই যেন ৮০ টাকার কমে পাওয়া যাচ্ছে না। তবে ব্রয়লার মুরগির দাম কিছুটা কমেছে। গত সপ্তাহের তুলনায় কেজিতে দাম কমেছে ৫ থেকে ১০ টাকা। ব্রয়লার মুরগির দাম কমলেও ডিম উচ্চ দামে স্থিতিশীল রয়েছে। চালের বাজারও গত সপ্তাহের দামে অপরিবর্তিত আছে।

গতকাল বৃহস্পতিবার সরেজমিনে রাজধানীর মোহাম্মদপুর টাউন হল বাজার ও কারওয়ান বাজার ঘুরে এসব তথ্য জানা গেছে। দেখা যায়, ফুলকপি, ঝিঙা, লাউ, কচুমুখি ও পটোল বিক্রি হচ্ছে ৮০ টাকা কেজি দরে। বেগুন ও কাঁকরোলের কেজি ১০০ টাকা। শীতের আগাম জাতের মুলা ও ঢ্যাঁড়স বিক্রি হচ্ছে ৮০ টাকা কেজি দরে। এর ঠিক দ্বিগুণ দামে বিক্রি হচ্ছে শীতের আগাম শিম—কেজি ১৬০ টাকা। আর প্রতি কেজি টমেটো বিক্রি হচ্ছে আরও বেশিতে, ১৮০ থেকে ২০০ টাকা কেজি দরে। টাউন হল বাজারের সবজি বিক্রেতা লিটন মিয়া জানান, শীতের সবজি আসার আগে দাম এমনিতেই কিছুটা বাড়তি থাকে। এর ওপর ট্রাকভাড়া বেড়েছে। ফলে সবজির দামে প্রভাব পড়েছে। বাজারে কম দামের সবজি বলতে এখন পাওয়া যায় পেঁপে ও কুমড়া। প্রতি কেজি পেঁপে ৩০ টাকায় ও মিষ্টিকুমড়া ৫০ টাকায় বিক্রি হয়। এ ছাড়া পেঁয়াজ বিক্রি হচ্ছে ৫৫ থেকে ৬০ টাকা কেজিতে। দেশি রসুনের কেজি ১৪০ টাকা। আমদানি করা রসুনের দাম অবশ্য আরও ৪০ টাকা বেশি, মানে ১৮০ টাকা। মরিচের দাম আগের সপ্তাহের মতো স্থিতিশীল, প্রতি কেজি ১০০ থেকে ১২০ টাকা।

ব্রয়লার মুরগির দাম কিছুটা কম ঢাকার বাজারে ব্রয়লার মুরগির দাম কেজিতে ৫ থেকে ১০ টাকা কমে ১৭৫ থেকে ১৮০ টাকায় বিক্রি হচ্ছে। সোনালি মুরগি বিক্রি হচ্ছে ৩২০ থেকে ৩৩০ টাকা কেজিতে। বিক্রেতারা জানান, গরমের তীব্রতা কিছুটা কমায় মুরগির উৎপাদন এখন বেড়েছে। ফলে বাজারে সরবরাহ ভালো রয়েছে। তাই এটির দাম কিছুটা কমেছে। কারওয়ান বাজারের একটি দোকানের কর্মী নাহিদ মিয়া বলেন, এখন সরবরাহ ভালো, তাই দাম বাড়েনি। সপ্তাহ দুয়েক আগে বাজারে ফার্মের মুরগির ডিমের ডজন ১৬০ টাকা ছুঁয়েছিল। ১০ থেকে ১৫ টাকা কমে এখন বিক্রি হচ্ছে ১৪৫ থেকে ১৫০ টাকায়। আর সাদা ডিমের ডজন ১৪০ টাকায়। শীতের সবজি বাজারে আসলে দাম আরও কমবে বলে জানান বিক্রেতারা।

এক-দেড় সপ্তাহ আগে চালের দাম কেজিতে ১ থেকে ২ টাকা বেড়েছিল। এখনো সে দামেই বাজার স্থির রয়েছে। প্রতি কেজি মোটা চাল ৫৫ টাকা, মাঝারি মানের আটাশ বা পাইজাম চাল ৫৫ থেকে ৬৫ টাকা, আর সরু চাল ৭৫ থেকে ৮০ টাকা। তবে বাজারে কয়েক ধরনের নাজিরশাইল চাল বিক্রি হয়। এসব চাল মানভেদে ৮০ থেকে ৮৬ টাকা কেজি দরে বিক্রি হয়। বিক্রেতারা জানান, এক-দেড় সপ্তাহ আগে নাজিরশাইল চালের দাম কেজিতে ২ থেকে ৩ টাকা বেড়েছিল। এখনো সেই বাড়তি দাম স্থির রয়েছে। মূলত জ্বালানির মূল্যবৃদ্ধির কারণে ট্রাকভাড়া বেড়ে যাওয়ায় চালের দাম কিছুটা বেড়েছে। এ ছাড়া প্রতি লিটার বোতলজাত সয়াবিন তেল আগের মতোই ২১০ টাকায় এবং ২ লিটার ৪১০ টাকায় বিক্রি হচ্ছে।', 'নিজস্ব প্রতিবেদক', 'https://media.prothomalo.com/prothomalo-bangla/2026-10-15/0ormww6y/WhatsApp-Image-2026-10-15-at-11.07.16-PM.jpeg', 'https://www.prothomalo.com/business/dnv2x7vq2x', '2026-10-16 08:00:00'),
(4, 'ভাড়া বাসা নাকি নিজের বাড়ি বা ফ্ল্যাট: সিদ্ধান্ত নেওয়ার সঠিক সময় কখন', 'business/hto3fm9bdp', NULL, 'নিজের একটি বাড়ি বা ফ্ল্যাট থাকবে—এই এক স্বপ্ন নিয়ে বেঁচে থাকে অনেকেই। তবে সেই স্বপ্ন পূরণের আগে সামনে আসে একটি গুরুত্বপূর্ণ প্রশ্ন—এখনই কি নিজের স্থায়ী আবাস কেনার সময়, নাকি আরও কিছুদিন ভাড়া বাসায় থাকাই ভালো? এমন সিদ্ধান্তের কোনো একক উত্তর নেই। কারণ, এটি নির্ভর করে একজনের আর্থিক সক্ষমতা, জীবনযাত্রা, ভবিষ্যৎ পরিকল্পনা, বাজার পরিস্থিতি এবং দীর্ঘমেয়াদি লক্ষ্য—সবকিছুর ওপর। সঠিক সময়ে সিদ্ধান্ত নিতে পারলে যেমন আর্থিক চাপ কমানো সম্ভব, তেমনি ভবিষ্যতের জন্য একটি স্থিতিশীল ভিত্তিও তৈরি করা যায়।

কোন পর্যায়ে নিজের বাড়ি কেনার কথা ভাববেন নিজের বাড়ি বা ফ্ল্যাট মানে শুধু একটি স্থায়ী ঠিকানা নয়, এটি দীর্ঘমেয়াদি একটি সম্পদও। নিয়মিত কিস্তি পরিশোধের মাধ্যমে ধীরে ধীরে নিজের সম্পদ তৈরি হয়। পাশাপাশি ভবিষ্যতে সম্পত্তির মূল্য বৃদ্ধি পাওয়ার সম্ভাবনাও থাকে। পরিবারের নিরাপত্তা, স্থায়িত্ব এবং মানসিক স্বস্তির দিক থেকেও নিজের বাড়ির আলাদা গুরুত্ব রয়েছে। তবে বাড়ি বা ফ্ল্যাট কেনার সিদ্ধান্ত নেওয়ার আগে কয়েকটি বিষয় বিবেচনা করা জরুরি। যেমন বুঝতে হবে আপনার মাসিক আয় স্থিতিশীল কি না, নিয়মিত সঞ্চয়ের অভ্যাস আছে কি না, ডাউন পেমেন্টের জন্য প্রয়োজনীয় অর্থ জোগাড় করতে পারবেন কি না; মাসিক কিস্তি পরিশোধ করলেও দৈনন্দিন খরচ ও জরুরি তহবিল বজায় রাখা সম্ভব হবে কি না। যদি এসব প্রশ্নের বেশির ভাগের উত্তর ইতিবাচক হয়, তাহলে নিজের বাড়ি বা ফ্ল্যাট কেনার পরিকল্পনা শুরু করার সময় এসেছে বলে ধরে নেওয়া যায়।

হোম লোন নেওয়ার সঠিক সময় কীভাবে নির্ধারণ করবেন এককালীন অর্থে বাড়ি বা ফ্ল্যাট কেনা অনেকেরই পক্ষেই সম্ভব হয় নয়। সে ক্ষেত্রে গৃহঋণ বা হোম লোনই ভরসা। কিন্তু লোন নেওয়ার ক্ষেত্রে শুধু সুদের হার নয়, নিজের আর্থিক সক্ষমতাও সবচেয়ে গুরুত্বপূর্ণ বিষয়। লোন নেওয়ার আগে নিশ্চিত হতে হবে যে মাসিক কিস্তি আপনার মোট মাসিক আয়ের এমন একটি অংশ, যা পরিশোধ করতে গিয়ে জীবনযাত্রার মান বা অন্যান্য প্রয়োজনীয় ব্যয় ব্যাহত না হয়। পাশাপাশি জরুরি পরিস্থিতির জন্য কিছু সঞ্চয়ও রাখা উচিত। এ ছাড়া কয়েকটি বিষয় আগেই যাচাই করে নেওয়া প্রয়োজন। যেমন বিভিন্ন ব্যাংকের সুদের হার ও অন্যান্য চার্জ তুলনা করা, ঋণের মেয়াদ ও কিস্তির পরিমাণ বুঝে নেওয়া, আগাম ঋণ পরিশোধের শর্ত সম্পর্কে জানা এবং নিজের ক্রেডিট ইতিহাস ও আর্থিক সক্ষমতা মূল্যায়ন করা ইত্যাদি।

শুধু কম সুদের হার দেখেই লোন গ্রহণের বিষয়ে সিদ্ধান্ত নেওয়া উচিত নয়। ঋণের পুরো কাঠামো এবং দীর্ঘমেয়াদি দায় বিবেচনায় রাখাটা জরুরি। প্রাইম ব্যাংকের অতিরিক্ত ব্যবস্থাপনা পরিচালক এম নাজিম এ চৌধুরী প্রথম আলোকে বলেন, ‘নিজস্ব বাড়ি কেনা জীবনের অন্যতম গুরুত্বপূর্ণ আর্থিক সিদ্ধান্ত। তাই এটি কেবল আবেগের ভিত্তিতে নয়, বরং সুপরিকল্পিত আর্থিক সক্ষমতার ওপর নির্ভর করে নেওয়া উচিত। স্থিতিশীল আয়, পর্যাপ্ত ডাউন পেমেন্ট এবং মাসিক কিস্তি নির্বিঘ্নে পরিশোধের সক্ষমতা নিশ্চিত হওয়ার পরই হোম লোন নেওয়ার সিদ্ধান্ত সবচেয়ে যুক্তিযুক্ত।’

এম নাজিম এ চৌধুরী আরও বলেন, ‘বর্তমান বাজারে গ্রাহকদের শুধু ইন্টারেস্ট হার নয়, ঋণের মোট ব্যয়, পরিশোধের শর্ত, সেবার মান এবং ব্যাংকের নির্ভরযোগ্যতাও বিবেচনায় নেওয়া উচিত। সঠিক পরিকল্পনা ও দায়িত্বশীল ঋণ ব্যবস্থাপনার মাধ্যমে হোম লোন দীর্ঘ মেয়াদে একটি মূল্যবান সম্পদ গঠনের কার্যকর মাধ্যম হতে পারে।’ ভাড়ায় থাকা বা নিজের বাড়ি বা ফ্ল্যাট কেনা—দুটিই পরিস্থিতিভেদে যৌক্তিক সিদ্ধান্ত হতে পারে। তবে যদি আপনার আর্থিক ভিত্তি শক্ত হয়, দীর্ঘমেয়াদি পরিকল্পনা স্পষ্ট থাকে এবং হোম লোনের কিস্তি নিয়মিত পরিশোধের সক্ষমতা থাকে, তাহলে নিজের স্থায়ী আবাসের স্বপ্ন পূরণের জন্য এখনই হতে পারে সঠিক সময়।', 'লেখা:', NULL, 'https://www.prothomalo.com/business/hto3fm9bdp', '2026-10-15 17:55:23'),
(4, '১২ বছরে গ্রামীণ ঋণে কৃষির অংশ কমেছে ৯ শতাংশ', 'business/9ofh4aw6bz', 'বিআইডিএসের সংলাপ', '২০১০ সালে গ্রামের ৩৬ শতাংশ পরিবার ঋণ গ্রহণ করত, যা ২০২২ সালে বেড়ে ৪২ শতাংশে উন্নীত হয়েছে। কিন্তু এসব ঋণের ২৫ শতাংশই তখন ছিল কৃষির জন্য। অথচ এখন কৃষির হিস্যা কমে ১৬ শতাংশে নেমেছে। অর্থাৎ এক যুগে কমেছে প্রায় ৯ শতাংশ। গ্রামীণ অর্থনীতির কাঠামোগত পরিবর্তনের ফলে এমনটা হয়েছে। এসব পরিবর্তনের মধ্যে রয়েছে গ্রামে নতুন ব্যবসা, বাড়িঘর তৈরি ও ভোগের প্রবণতা বৃদ্ধি পাওয়া। গতকাল সোমবার বাংলাদেশের খাদ্যব্যবস্থায় অর্থায়নের সুযোগ, চ্যালেঞ্জ ও নীতিগত করণীয় নিয়ে আয়োজিত এক নীতি সংলাপে এসব বিষয় উঠে আসে। ‘ফিন্যান্সিং ফুড সিস্টেমস ইন বাংলাদেশ: এভিডেন্স অ্যান্ড পলিসি ডায়ালগ’ শীর্ষক এ সংলাপের আয়োজন করে সরকারি গবেষণা সংস্থা বাংলাদেশ উন্নয়ন গবেষণা প্রতিষ্ঠান (বিআইডিএস) এবং আন্তর্জাতিক খাদ্যনীতি গবেষণা প্রতিষ্ঠান (আইএফপিআরআই)। সংলাপে প্রধান অতিথি ছিলেন কৃষিসচিব মো. সেলিম খান। মাইক্রোক্রেডিট রেগুলেটরি অথরিটির (এমআরএ) নির্বাহী ভাইস চেয়ারম্যান অধ্যাপক মোহাম্মদ হেলাল উদ্দিন বিশেষ অতিথি এবং পল্লী কর্ম-সহায়ক ফাউন্ডেশনের (পিকেএসএফ) ব্যবস্থাপনা পরিচালক (এমডি) মো. ফজলুল কাদের সম্মানিত অতিথি হিসেবে উপস্থিত ছিলেন।

বিআইডিএসের মহাপরিচালক অধ্যাপক এ কে এনামুল হকের সভাপতিত্বে সংলাপে গ্রামীণ ঋণবাজারের পরিবর্তন, প্রাণিসম্পদ খাতে অর্থায়ন, শহুরে খাদ্য বিক্রেতাদের জন্য আর্থিক পণ্য এবং কৃষিভিত্তিক ক্ষুদ্র ও মাঝারি উদ্যোগের অর্থায়ন নিয়ে আলোচনা হয়। অনুষ্ঠানে মূল প্রবন্ধ উপস্থাপন করেন বিআইডিএসের গবেষণা পরিচালক কাজী ইকবাল। এতে তিনি জানান, গ্রাম এলাকায় প্রতি চারটি ঋণের তিনটি নেওয়া হয় বিভিন্ন বেসরকারি উন্নয়ন সংস্থা থেকে। ২০১০ সালে গ্রামে ৪ দশমিক ৭ শতাংশ পরিবার ব্যাংক থেকে ঋণ নিত। ২০২২ সালে তা কমে হয়েছে ২ দশমিক ৯ শতাংশে। অর্থাৎ ব্যাংক থেকে পরিবারগুলোর ঋণ নেওয়া কমেছে। কৃষিঋণ কোন কোন কাজে ব্যয় করা হয়, সেটিও উপস্থাপনায় তুলে ধরা হয়। এতে দেখা যায়, ২০১০ সালে সারের পেছনে ব্যয় হতো ঋণের ৪৪ শতাংশ, যা ২০২২ সালে বেড়ে হয় ৫৬ শতাংশ। আবার এখন ঋণ পরিশোধের চাপও বেড়েছে। ৪১ শতাংশ ঋণ গ্রহণকারী পরিবার তাদের মাসিক আয়ের ৪০ শতাংশ কিস্তি পরিশোধে ব্যয় করে। ২০১০ সালে এমন ঋণগ্রহীতার হার ছিল ২২ শতাংশ। এ ছাড়া ৩৩ শতাংশ পরিবারের দুটি বা এর বেশি ঋণ রয়েছে।

কৃষি যান্ত্রিকীকরণে ব্যাংকঋণ কম অনুষ্ঠানে কৃষি যান্ত্রিকীকরণে অর্থায়ন নিয়ে একটি উপস্থাপনা দেন আইএফপিআরআইয়ের প্রতিনিধি মেহরাব বখতিয়ার। তিনি জানান, কৃষিযন্ত্র ক্রয়ে ১ লাখ থেকে ৩২ লাখ টাকা পর্যন্ত প্রয়োজন হয়। তবে এসব যন্ত্র দিয়ে বছরে গড়ে প্রায় পাঁচ লাখ টাকা পর্যন্ত আয় করা যায়। গ্রামে অন্য কোনো ব্যবসায়ে যন্ত্র ভাড়া দিয়ে এত বেশি আয় হয় না। তবু ব্যাংকগুলো যন্ত্র কেনার জন্য মাত্র ২ থেকে ৭ শতাংশ অর্থায়ন করে। দেশে বছরে দুই হাজার কোটি টাকার যন্ত্র বিক্রি হয়। মেহরাব বখতিয়ার জানান, কৃষিযন্ত্র ক্রয়ে ব্যাংক থেকে ঋণ না পেয়ে ক্রেতারা বাধ্য হয়ে অন্য উৎস থেকে ঋণ নেন। এর মধ্যে ৩২ শতাংশ আত্মীয়দের, ২৭ শতাংশ এনজিও প্রতিষ্ঠান এবং ৮ শতাংশ মহাজনদের কাছ থেকে ঋণ গ্রহণ করেন। প্রধান অতিথির বক্তব্যে কৃষিসচিব মো. সেলিম খান বলেন, কৃষককে সর্বাধিক গুরুত্ব দিয়ে দেশের কৃষিকে এগিয়ে নেওয়ার চেষ্টা করছে সরকার। এর অংশ হিসেবে কৃষক কার্ডের মাধ্যমে ঋণসহ ১০ ধরনের সুবিধা দেওয়া হবে কৃষকদের। এ বছর পেঁয়াজ আমদানি করতে হয়নি জানিয়ে কৃষিসচিব বলেন, দুই বছরের মধ্যে মরিচ ও টমেটো আমদানির প্রয়োজন হবে না।

অনুষ্ঠানে পিকেএসএফের ব্যবস্থাপনা পরিচালক (এমডি) মো. ফজলুল কাদের বলেন, কৃষকের কাছে ৯০ শতাংশ ঋণই যাচ্ছে বিভিন্ন এনজিও প্রতিষ্ঠানের মাধ্যমে। কিন্তু এসব ঋণের সুদ অনেক বেশি। তাই কৃষকদের ওপর ঋণ পরিশোধের চাপ বাড়ছে। আবার কৃষি উপকরণের দামও বেড়েছে। ফলে কৃষকের মুনাফা কমেছে। তাই কৃষকের সন্তান এখন কৃষিতে আসতে চায় না। বিআইডিএসের মহাপরিচালক অধ্যাপক এ কে এনামুল হক বলেন, এসব গবেষণার ফলাফল নীতিনির্ধারকদের চিন্তার খোরাক জোগাবে। একদিকে যেমন কৃষি পরিবার বিলীন হচ্ছে, অন্যদিকে ক্ষেত্র পরিবর্তন করে নতুনভাবে ফিরে আসছে তারা। তবে উৎপাদনশীলতা না বাড়াতে পারলে কৃষি খাতকে এগিয়ে নেওয়া কঠিন হবে। উন্মুক্ত আলোচনায় অংশ নিয়ে বাংলাদেশ কৃষি গবেষণা ইনস্টিটিউটের মুখ্য বৈজ্ঞানিক কর্মকর্তা মোহাম্মদ এরশাদুল হক বলেন, কৃষি যান্ত্রিকীকরণ একটি লাভজনক বিনিয়োগ ক্ষেত্র। এখানে ব্যাংকগুলোর এগিয়ে আসা উচিত। ব্যাংক হয়তো যন্ত্র উৎপাদনকারী প্রতিষ্ঠানকে ঋণ দিচ্ছে। তারা আবার কৃষককে বাকিতে যন্ত্র দিচ্ছে। তাই কৃষকের ওপর দ্বিগুণ সুদের ভার পড়ছে। সভায় সরকারি–বেসরকারি বিভিন্ন সংস্থার গবেষক ও বিশেষজ্ঞরা উপস্থিত ছিলেন।', 'নিজস্ব প্রতিবেদক', 'https://media.prothomalo.com/prothomalo-bangla/2026-10-12/uegn9xcr/WhatsApp-Image-2026-10-12-at-10.55.55-PM.jpeg', 'https://www.prothomalo.com/business/9ofh4aw6bz', '2026-10-13 08:30:00'),
(4, 'ঢাকার আকাশরেখায় নতুন উঁচু ভবন', 'business/mhkzeynova', 'হাতিরঝিলের আবহ ও ভালো যোগাযোগব্যবস্থা শান্তা হোল্ডিংসের ‘ঢাকা টাওয়ার’ রাজধানীর আকাশরেখায় নতুন সংযোজন হতে যাচ্ছে।', 'দেশের আবাসনে উন্নত বিশ্বের আদলে ভিন্ন রূপ এনে দিতে নতুন নতুন উঁচু ভবন গড়ছে শান্তা হোল্ডিংস। এসব ভবনে আন্তর্জাতিক ব্র্যান্ড, বহুজাতিক ও শীর্ষস্থানীয় দেশীয় প্রতিষ্ঠান এক ছাদের নিচে বিশ্বমানের কর্মপরিবেশ পাচ্ছে।

বাণিজ্যিক কেন্দ্র হিসেবে রূপ নিচ্ছে ঢাকার তেজগাঁও। এই রূপান্তরের অন্যতম প্রতীক হিসেবে গড়ে উঠেছে শান্তা হোল্ডিংসের ৪০ তলা ভবন ‘শান্তা পিনাকল’। প্রায় ৫০০ ফুট উঁচু ভবনটি ছড়িয়ে আছে প্রায় ৬ লাখ ৭০ হাজার বর্গফুট এলাকায়। নকশা করেছেন স্থপতি এহসান খানের নেতৃত্বে একদল দেশি-বিদেশি বিশেষজ্ঞ। প্রতিষ্ঠানটির ভাষ্য, দেশে এই প্রথম কোনো ভবনে পারফরম্যান্স মক-আপ ও উইন্ড টানেল টেস্টিং করা হয়েছে।

হাতিরঝিলের আবহ ও ভালো যোগাযোগব্যবস্থা শান্তা হোল্ডিংসের ‘ঢাকা টাওয়ার’ রাজধানীর আকাশরেখায় নতুন সংযোজন হতে যাচ্ছে। ঢাকা টাওয়ার তৈরিতে ডাচ স্থাপত্য প্রতিষ্ঠান ওএমএর সঙ্গে যৌথভাবে কাজ করছে শান্তা হোল্ডিংস। ২০ লাখ বর্গফুটের বিশাল আয়তনের ১৫০ মিটার উঁচু ঢাকা টাওয়ারে থাকছে আধুনিক বাণিজ্যিক ও খুচরা বিক্রয়কেন্দ্র। প্রতিষ্ঠানসংশ্লিষ্ট ব্যক্তিরা বলছেন, উদীয়মান অর্থনীতি ও নতুন প্রজন্মের উদ্যমী চেতনার প্রতীক হিসেবে এই টাওয়ারের ডিজাইন করা হয়েছে।', 'প্রথম আলো ডেস্ক', 'https://media.prothomalo.com/prothomalo-bangla/2026-10-10/rz6e48wf/View-22.jpg', 'https://www.prothomalo.com/business/mhkzeynova', '2026-10-11 10:30:00'),
(4, 'বহুতল ভবনে শান্তার রেকর্ড', 'business/wstm3577ci', 'কাজের ব্যতিক্রমী মান ও নান্দনিকতার সেরা স্বীকৃতি হিসেবে প্রতিষ্ঠানটি ২০১৮ সাল থেকে টানা চারবার সফলভাবে লাভ করেছে ‘সুপারব্র্যান্ডস’ অ্যাওয়ার্ড।', 'দেশের আবাসন ও বাণিজ্যিক ভবন নির্মাণ খাতে গত দুই দশকে এসেছে এক বৈপ্লবিক রূপান্তর। এই পরিবর্তনের অগ্রভাগে বেশ মজবুত অবস্থানে আছে শান্তা হোল্ডিংস লিমিটেড। ২০০৫ সালে শিল্পোদ্যোক্তা খন্দকার মনির উদ্দিনের উদ্যোগে প্রতিষ্ঠিত এই প্রতিষ্ঠানের নির্মাণ করা উন্নত আধুনিক আইকনিক স্থাপত্য সবার নজর কাড়ছে। বর্তমানে শান্তা হোল্ডিংস দেশীয় আবাসনশিল্পে উন্নত কন্ডোমিনিয়াম ও বিশ্বমানের বহুতল বাণিজ্যিক ভবনের নতুন ধারা তৈরি হয়েছে। দেশের আকাশরেখায় সর্বোচ্চ উঁচু ভবন তৈরি করে রেকর্ড গড়ছে বলে জানায় প্রতিষ্ঠানটি।

প্রতিষ্ঠার পর থেকে কোম্পানিটি সফলভাবে হস্তান্তর করেছে ৫৭টি আবাসিক এবং ১ কোটি ১০ লাখ বর্গফুট মোট আয়তনের ৭টি দৃষ্টিনন্দন বাণিজ্যিক ভবন। পরীবাগের ১৫০ ফ্ল্যাটের ‘দিগন্ত’ দেশের অন্যতম পূর্ণাঙ্গ আবাসিক কন্ডোমিয়াম এবং তেজগাঁও লিংক রোডের ‘শান্তা ওয়েস্টার্ন টাওয়ার’ দেশে তৎকালীন সময়ে আন্তর্জাতিক মানের আধুনিক বাণিজ্যিক ভবনের স্বীকৃতি পায়। বর্তমানে ঢাকার গুলশান, বারিধারা, বসুন্ধরা, বনানী, ধানমন্ডি ও মিরপুর এলাকায় প্রতিষ্ঠানটির ৩৫টি আধুনিক আবাসিক (প্রায় ২৬০০ ফ্ল্যাট) এবং ৮টি বাণিজ্যিক প্রকল্পের নির্মাণকাজ দ্রুতগতিতে চলমান। এর মধ্যে তেজগাঁওয়ে বাস্তবায়নাধীন ‘শান্তা পিনাকল’ হতে যাচ্ছে দেশের প্রথম ৪০ তলা সুউচ্চ ভবন, এ বছরেরই পুরোপুরি হস্তান্তরিত হবে।

শান্তা হোল্ডিংসের বৈপ্লবিক প্রবৃদ্ধি নিয়ে প্রতিষ্ঠানটির প্রধান বিক্রয় কর্মকর্তা শিহাব আহমেদ প্রথম আলোকে বলেন, ‘আমাদের মূল লক্ষ্য ছিল আন্তর্জাতিক মানের নাগরিক জীবনযাত্রা ও উন্নত বিজনেস সেন্টার তৈরি করা। বিশ্বের উন্নত শহর নিউইয়র্ক বা লন্ডনের স্কাইলাইনের মতো দৃষ্টিনন্দন আন্তর্জাতিক অবকাঠামো দিয়ে ঢাকাকে চমৎকারভাবে সাজানোই আমাদের মূল স্বপ্ন ছিল। আমাদের শান্তা পিনাকল প্রকল্পটি দেশের অন্যতম উইন্ড টানেল টেস্টেড ভবন। এ ছাড়া ৪২ মিলিমিটারের বিশেষ শক্ত গ্লাস, সেন্ট্রাল বিএমএস রুম, বিআইএম সফটওয়্যার এবং অ্যালুমিনিয়াম ফ্রেমওয়ার্কের সর্বাধুনিক প্রযুক্তি ব্যবহার করা হচ্ছে। বাণিজ্যিক প্রপার্টিতে দীর্ঘমেয়াদি চুক্তি ও আকর্ষণীয় রেন্টাল রিটার্ন থাকায় গ্রাহকদের মূল্যবান বিনিয়োগ অত্যন্ত লাভজনক ও নিরাপদ।’

কাজের ব্যতিক্রমী মান ও নান্দনিকতার সেরা স্বীকৃতি হিসেবে প্রতিষ্ঠানটি ২০১৮ সাল থেকে টানা চারবার সফলভাবে লাভ করেছে ‘সুপারব্র্যান্ডস’ অ্যাওয়ার্ড। এ ছাড়া ২০২৪ সালে কোম্পানিটি অর্জন করে ‘এশিয়া প্যাসিফিক প্রপার্টি অ্যাওয়ার্ড’ এবং ‘ইএসএসএবি সেফটি এক্সিলেন্স অ্যাওয়ার্ড’-এ অনন্য চ্যাম্পিয়ন হওয়ার গৌরব। দেশের আবাসনশিল্পের উন্নয়নের পাশাপাশি সামাজিক কার্যক্রমে শিক্ষা বিস্তার ও বৃত্তি প্রদান, শিক্ষাপ্রতিষ্ঠান স্থাপন এবং দেশের পিছিয়ে পড়া এলাকার বিদ্যালয়ের অবকাঠামোগত উন্নয়ন। গৃহহীনদের জন্য আবাসন–সুবিধা তৈরি করে দিয়েছে প্রতিষ্ঠানটি।', 'নিজস্ব প্রতিবেদক', NULL, 'https://www.prothomalo.com/business/wstm3577ci', '2026-10-11 10:15:00'),
(4, 'ঢাকায় আন্তর্জাতিক বাণিজ্যিক স্থাপত্য গড়ছে শান্তা', 'business/gm7jx2tqzl', 'সাক্ষাৎকার: শিহাব আহমেদ', 'প্রথম আলো : বর্তমানে অনেকের মুখেই শোনা যায়, ঢাকার স্কাইলাইন বদলে দিয়েছে শান্তা হোল্ডিংস। পিনাকল, ফোরামের মতো উঁচু ভবন নির্মাণের পেছনের গল্পটা কী? শিহাব আহমেদ : বাংলাদেশে আবাসন খাত বলতে একসময় মূলত একটি গ্যারেজ আর কয়েকটি ফ্ল্যাটের সমন্বয় বোঝাত। পরবর্তী সময়ে ডেভেলপার কোম্পানি বড় কমপ্লেক্স তৈরি করে নিচতলায় শিশুদের খেলার জায়গা রেখেছিল। তবে আমাদের প্রতিষ্ঠানের পরিকল্পনা ছিল আন্তর্জাতিক মানের সুযোগ-সুবিধা ঘরের ভেতরের পাশাপাশি প্রাঙ্গণেও ইনকরপোরেট করা। পরীবাগের ‘দিগন্ত’ কন্ডোমিনিয়াম দিয়ে আমাদের সেই সফল যাত্রা শুরু হয়। অন্যদিকে নিউইয়র্ক বা লন্ডনের ক্যানারি ওয়ার্ফের মতো ঢাকায় আন্তর্জাতিক মানের ব্যবসাকেন্দ্র গড়ে তোলার চিন্তা থেকে আমরা কমার্শিয়াল ভবনে আসি। ঢাকার স্কাইলাইন বদলে দেওয়া এবং বিশ্বমানের বাণিজ্যিক ভবন তৈরি করে তা উপভোগের সুযোগ দেওয়াই ছিল আমাদের স্বপ্ন।

প্রথম আলো : তেজগাঁওয়ে আপনারা ধারাবাহিক কয়েকটি আইকনিক কমার্শিয়াল ভবন নির্মাণ করেছেন। এসব ভবনের প্রযুক্তিগত ও কারিগরি পার্থক্যগুলো কীভাবে ব্যাখ্যা করবেন? শিহাব আহমেদ : তেজগাঁও শিল্প এলাকা থেকে বাণিজ্যিক এলাকায় রূপান্তরের পর প্রথম কমার্শিয়াল ভবন হিসেবে আমরা ‘শান্তা ওয়েস্টার্ন টাওয়ার’ করি। তখনকার ফার বিধিমালার কারণে এটি ১৪ তলার মধ্যে শেষ করতে হয়। এরপর ‘ফোরাম’ নির্মাণের মাধ্যমে তেজগাঁওয়ে টুইন টাওয়ার, ডেস্টিনেশন কন্ট্রোল এলিভেটর, বিএমএস রুম এবং দেশে প্রথম ইউনিটাইজড গ্লাস ফাসাদ যুক্ত করি। এই কাচের থার্মাল প্রোটেকশন অত্যধিক হওয়ায় এসি ও বিদ্যুতের খরচ ব্যাপকভাবে কমে যায়। পরবর্তী সময়ে ৫০০ ফুট উঁচু ‘পিনাকল’ করি, যা দেশের প্রথম উইন্ড টানেল টেস্টেড ভবন। এতে ৩ মিটার ম্যাট ঢালাই, প্রতি সেকেন্ডে ৪ মিটার গতির এলিভেটর, লিড প্লাটিনাম সার্টিফায়েড প্রযুক্তি এবং ৪০ তলার ওপরে ৫৬ ফুট উঁচু অসাধারণ ছাদ করা হয়েছে। আর তেজগাঁওয়ের সবচেয়ে বড় ৬ বিঘা জমির ওপর নির্মিত হচ্ছে ‘ঢাকা টাওয়ার’। সেখানে মাটির নিচে ৯ মিটার গভীর ম্যাট ঢালাই করা হয়েছে। এতে প্রথম বিআইএম (বিল্ডিং ইনফরমেশন মডেলিং) সফটওয়্যার, ৪২ মিলিমিটারের পুরু কাচ এবং দ্রুততম নির্মাণের জন্য অ্যালুমিনিয়াম ফরমওয়ার্ক প্রযুক্তি ব্যবহার করা হচ্ছে। নেদারল্যান্ডসের বিখ্যাত স্থপতিদের ওএমএ এর নকশা করেছে এবং ফরাসি প্রজেক্ট ম্যানেজমেন্ট কনসালট্যান্ট এর নির্মাণকাজ তদারকি করছে। এর ছাদে ‘ঢাকা আই’, বাগান ও রেস্তোরাঁ থাকবে।

প্রথম আলো : বাণিজ্যিক ভবনে করপোরেট প্রতিষ্ঠান ও বিনিয়োগকারীদের আগ্রহ এবং ব্যবসায়িক সুবিধার দিকগুলো কেমন দেখছেন? শিহাব আহমেদ : শুরুতে ওয়েস্টার্ন টাওয়ার বা ফোরাম বিক্রিতে গ্রাহকদের অনেক বোঝাতে হয়েছিল। তবে বর্তমানে আধুনিক ভবনের সুযোগ–সুবিধা থাকায় ক্রেতাদের আগ্রহের কারণে কাজ শুরুর আগেই ভালো বিক্রি হয়ে যায়। কারণ, বাণিজ্যিক স্থাপনায় বিনিয়োগ করে প্রাপ্তি বা রিটার্ন অন ইনভেস্টমেন্ট অত্যন্ত বেশি। স্থানভেদে আবাসিক ফ্ল্যাটের চেয়ে বেশি ভাড়া পাওয়া যায় বাণিজ্যিক ভবনে। এ ধরনের ভবনে একসঙ্গে উল্লেখযোগ্য অগ্রিম ভাড়া পাওয়া যায় এবং দীর্ঘ মেয়াদে চুক্তি করা (লিজ) সম্ভব হয়। অফিসের অন্দরসজ্জা (ইন্টেরিয়র) ও রক্ষণাবেক্ষণ সম্পূর্ণ ভাড়াটের দায়িত্বে থাকে এবং ভাড়াও পর্যায়ক্রমে মূল্যস্ফীতির সঙ্গে সমন্বয় হয়, যা বিনিয়োগকারীদের জন্য আকর্ষণীয় সুযোগ। কারণ, একটি নির্দিষ্ট মেয়াদে বিনিয়োগের অর্থ উঠে আসে এবং বেশ লাভজনক বিনিয়োগে পরিণত হয়। বর্তমানে শান্তার সব বাণিজ্যিক ভবন ক্রেতাদের কাছে পছন্দের শীর্ষে রয়েছে। কারণ, এই ভবন আন্তর্জাতিক মানের হওয়ায় বহুজাতিক ও দেশের শীর্ষস্থানীয় কোম্পানিগুলো ভাড়া নিতে বেশ আগ্রহী হয়।

প্রথম আলো : উঁচু ভবনে ব্যবহারযোগ্য জায়গা এবং কমন স্পেস নিয়ে ক্রেতাদের কী ধারণা থাকা প্রয়োজন? শিহাব আহমেদ : এটি নিখুঁত কারিগরি বিষয়। নিয়ম অনুযায়ী ১০ তলার বেশি ভবন হলে দুটি ফায়ার স্টেয়ার, লিফট ও লবি নিশ্চিত করতে হয়। প্লট ও ফ্লোরের আকৃতি যত বড় হয়, কমন স্পেসের শতকরা হার তত কমে আসে এবং কাস্টমাররা বেশি ব্যবহারযোগ্য স্পেস পান।', 'প্রথম আলো ডেস্ক', 'https://media.prothomalo.com/prothomalo-bangla/2026-10-10/9slfcpb2/F6A6381.JPG', 'https://www.prothomalo.com/business/gm7jx2tqzl', '2026-10-11 10:00:00'),
(4, 'স্থাপত্যে পরিবেশবান্ধব প্রযুক্তির সমন্বয়', 'business/2cnyys8hhp', 'গুলশান অ্যাভিনিউতে ৩০ কাঠার তিন দিকে খোলা প্লটে নির্মিত বিটিআই ল্যান্ডমার্ক আধুনিক প্রযুক্তির এক অনন্য স্থাপনা।', 'আবাসন খাতে নান্দনিক স্থাপত্য নকশা ও পরিবেশবান্ধব প্রযুক্তির সমন্বয়ে নতুন মানদণ্ড স্থাপন করেছে বিল্ডিং টেকনোলজি অ্যান্ড আইডিয়াজ লিমিটেড (বিটিআই)। ঢাকার অভিজাত এলাকায় নির্মিত তাদের দুটি আধুনিক প্রকল্প।

ঢাকার আফতাবনগরে অবস্থিত সিটি পয়েন্ট বিটিআইয়ের ‘ওয়েলনেস কমিউনিটিস’–এর একটি অন্যতম প্রকল্প। ৩৫ কাঠা জমির ওপরে নির্মিত তিনটি টাওয়ারে থাকছে সুস্থতা–বিষয়ক সুবিধার সংযোজন। এখানে বাসিন্দাদের জন্য থাকছে ব্যাডমিন্টন কোর্ট, প্রশস্ত হাঁটার জায়গা, হেলথ ক্লাব, ইনডোর খেলার জায়গা, কমিউনিটি লাউঞ্জ, নামাজের স্থান, বাচ্চাদের ও বড়দের জন্য পৃথক সুইমিং পুল। ফ্ল্যাটের আকার ১৪৫০+ থেকে ১৭৫০+ বর্গফুট, তিন বেডরুমের এ ফ্ল্যাট সব ধরনের প্রয়োজন মাথায় রেখেই নকশা করা হয়েছে।

গুলশান অ্যাভিনিউতে ৩০ কাঠার তিন দিকে খোলা প্লটে নির্মিত বিটিআই ল্যান্ডমার্ক আধুনিক প্রযুক্তির এক অনন্য স্থাপনা। লো-ই ইনসুলেটেড টেম্পার্ড-অ্যামিনেটেড সেফটি গ্লাস দ্বারা আবৃত এ ভবনের সামনের দিকে অ্যানোডাইজড অ্যালুমিনিয়ামের লুভার ব্যবহার করা হয়েছে, যা সূর্যের তাপ নিয়ন্ত্রণ করে এবং ৫৫ শতাংশ পর্যন্ত বিদ্যুৎ সাশ্রয় করে । এ ছাড়া ভয়েডের ব্যবহারে বছরজুড়ে ভবনটিতে পর্যাপ্ত প্রাকৃতিক বাতাস প্রবাহিত হয়। এখানে তিনতলা বিশিষ্ট পার্কিং স্পেস রয়েছে। অগ্নিনিরাপত্তা ব্যবস্থার জন্য বিটিআই ল্যান্ডমার্ক ইএসএসএবি ফায়ার সেফটি অ্যাওয়ার্ড অর্জন করেছে।', 'প্রথম আলো ডেস্ক', 'https://media.prothomalo.com/prothomalo-bangla/2026-10-10/kqskx7m3/WhatsApp-Image-2026-10-10-at-12.13.57-PM-2.jpeg', 'https://www.prothomalo.com/business/2cnyys8hhp', '2026-10-11 09:45:00'),
(5, 'আজ টিভিতে যা দেখবেন (২৩ অক্টোবর ২০২৬)', 'sports/m327n8h4gc', 'সংযুক্ত আরব আমিরাতে ত্রিদেশীয় সিরিজের ফাইনাল আজ, মুখোমুখি আফগানিস্তান ও জিম্বাবুয়ে। ইংলিশ প্রিমিয়ার লিগে রাতে মুখোমুখি ইপসউইচ ও নটিংহাম।', 'সংযুক্ত আরব আমিরাতে ত্রিদেশীয় সিরিজের ফাইনাল আজ, মুখোমুখি আফগানিস্তান ও জিম্বাবুয়ে। ইংলিশ প্রিমিয়ার লিগে রাতে মুখোমুখি ইপসউইচ ও নটিংহাম।

